// Star Wars TCG - Fully scripted variant. Generated by docs/feature-plans/game-bots/swtcg/tools/scene.mjs; edit the sources, not this file.
// ============================================================================================
// Star Wars TCG rules kernel - part 0: types, constants, small pure helpers.
//
// The kernel files (k0..k9) are concatenated, in order, into ONE scene script (no imports, no
// exports - a scene script is not a module) and cut back out by `extractKernelModule` for the
// trainer. Everything here must stay pure: no table API, no Math.random, no Date, plain JSON
// state. Words the scene-script scanner refuses even in comments are avoided on purpose.
// ============================================================================================

/** Card type flags (a card may carry several arena types). */
const T_SPACE = 1;
const T_GROUND = 2;
const T_CHAR = 4;
const T_BATTLE = 8;
const T_MISSION = 16;
const T_EQUIP = 32;
const T_LOCATION = 64;
const T_RESOURCE = 128;
const T_SUBORD = 256;
const T_EVENT = 512;
const T_UNIT = T_SPACE | T_GROUND | T_CHAR;

/** Arena indices: battle proceeds 0 -> 1 -> 2. */
const AR_SPACE = 0;
const AR_GROUND = 1;
const AR_CHAR = 2;
const ARENA_NAMES = ["Space", "Ground", "Character"];

/** Where a card instance is. */
type Zone =
  | "deck" | "hand" | "disc" | "build" | "a0" | "a1" | "a2"
  | "res" | "evt" | "sup" | "out" | "under" | "aside";

/** A numeric keyword's value, or 1 for a flag keyword. */
type KwMap = { [kw: string]: number };

/** Stat buff with a duration. `u`: T = until end of turn, A = for this attack, B = end of battle, G = game. */
interface Buff {
  sp: number;
  pw: number;
  hp: number;
  u: "T" | "A" | "B" | "G";
  kw: KwMap | null;
}

/** One cost element of an activated ability. */
type Cost =
  | { c: "force"; n: number }
  | { c: "forceX"; cap: number }
  | { c: "bp"; n: number }
  | { c: "tap" }
  | { c: "discard"; n: number }
  | { c: "addCtr"; n: number }
  | { c: "remCtr"; n: number }
  | { c: "dmgSelf"; n: number }
  | { c: "tapOther"; f: Filter }
  | { c: "retreatSelf" };

/** A filter over card instances, relative to the ability's controller. */
interface Filter {
  /** "me" | "opp" | "any" */
  side: "me" | "opp" | "any";
  /** Required type flags (any of), 0 = any unit. */
  ty: number;
  /** Lower-case subtype words that must ALL appear (empty = no constraint). */
  sub: string[];
  /** Restrict to an arena: -1 any, 0..2 fixed, 3 = "this arena" (the source's arena). */
  ar: number;
  /** Exclude the source itself. */
  other: boolean;
  /** Extra constraints. */
  tapped: number; // -1 any, 0 untapped only, 1 tapped only
  damaged: boolean;
  unique: boolean;
}

/** An effect step. Targets: "self" (the source), "tgt" (the chosen target), "all" (every match of f). */
type Eff =
  | { e: "stat"; who: Who; sp: number; pw: number; hp: number; u: "T" | "A" | "B" | "G"; kw: KwMap | null }
  | { e: "prevent"; kind: "evade" | "deflect" | "absorb" | "protect" | "persuade" | "all"; n: number; x: boolean }
  | { e: "retaliate"; n: number }
  | { e: "intercept" }
  | { e: "redirect" }
  | { e: "ambush"; n: number }
  | { e: "draw"; n: number }
  | { e: "force"; n: number; opp: boolean }
  | { e: "bp"; n: number; opp: boolean }
  | { e: "damage"; who: Who; n: number; dice: boolean; nx: boolean }
  | { e: "counters"; who: Who; n: number; remove: boolean }
  | { e: "tap"; who: Who }
  | { e: "untap"; who: Who }
  | { e: "retreat"; who: Who }
  | { e: "discardUnit"; who: Who }
  | { e: "disrupt"; what: "attack" | "battle" | "act" | "mission" | "any" | "dsr"; unless: number }
  | { e: "oppDiscard"; n: number; random: boolean }
  | { e: "mill"; n: number; opp: boolean }
  | { e: "addCtr"; n: number }
  | { e: "equip" }
  | { e: "meditate" }
  | { e: "attackAgain" }
  | { e: "search"; ty: number; sub: string[]; n: number; dest: "hand" | "build"; bc: number; from: "deck" | "disc"; uq: boolean }
  | { e: "selfDiscard"; n: number }
  | { e: "take"; n: number; nm: string; ars: number[] }
  | { e: "noop" };

/** A condition on a static ability ("as long as ..."). */
type Cond =
  | { c: "name"; n: string; ar: number }
  | { c: "have"; f: Filter }
  | { c: "selfAr"; ar: number }
  | { c: "pilot" }
  | { c: "force"; n: number }
  | { c: "loc"; sub: string[]; ar: number }
  | { c: "undamaged" }
  | { c: "damaged" };

/** Who an effect step applies to. */
type Who =
  | { w: "self" }
  | { w: "tgt"; i: number }
  | { w: "all"; f: Filter }
  | { w: "attacker" }
  | { w: "defender" }
  | { w: "equipped" };

/** When an activated ability (or Battle card) may be played. */
interface Timing {
  build: boolean; // during your build step
  battle: boolean; // general POP during the battle phase (no unit attacking)
  attack: boolean; // during an attack (attack POP)
  prevent: boolean; // damage prevention POP
  wouldAttack: boolean; // instead of this unit's attack
  arena: number; // -1 any arena, else only during that arena's battle step
  once: boolean;
}

/** One parsed ability. `k`: kw = keyword, act = activated, trig = triggered, aura = static, eq = equipped grant. */
type Ability =
  | { k: "kw"; kw: string; n: number }
  | { k: "act"; cost: Cost[]; tg: Filter[]; fx: Eff[]; tm: Timing; src: string }
  | { k: "trig"; ev: string; tg: Filter[]; fx: Eff[]; opt: boolean; src: string }
  | { k: "aura"; f: Filter; sp: number; pw: number; hp: number; kw: KwMap | null; acts?: Ability[]; cond?: Cond; src: string }
  | { k: "cred"; f: Filter; n: number; src: string }
  | { k: "eq"; sub: string[]; sp: number; pw: number; hp: number; kw: KwMap | null; acts: Ability[]; src: string }
  | { k: "pilot"; sub: string[]; sp: number; pw: number; hp: number; kw: KwMap | null; src: string }
  | { k: "treat"; sub: string[] }
  | { k: "none"; src: string };

/** A card definition, parsed once in `initial`. */
interface Def {
  n: string; // full printed name
  base: string; // unique-stack name (version letter removed)
  uq: boolean;
  ty: number;
  sub: string[]; // lower-case subtype words
  side: string;
  cost: number;
  costX: boolean;
  sp: number;
  pw: number;
  hp: number;
  ab: Ability[];
  /** Static keywords summed over the printed abilities (fast path for combat). */
  kw: KwMap;
  /** Abilities the parser could not read; the card still plays with its stats and keywords. */
  unk: number;
  txt: string;
}

/** A card instance. */
interface Card {
  d: number; // def index
  o: number; // owner seat index
  c: number; // controller seat index
  z: Zone;
  fd: boolean; // face down (partially built / unknown)
  bc: number; // build counters
  dm: number; // damage counters
  tp: boolean;
  rc: number; // resource / misc counters
  h: number; // host instance when z === "under", else -1
  ut: number; // 0 none, 1 stacked (unique stack), 2 equipment, 3 pilot
  mv: boolean; // moved between arenas this turn
  eqT: boolean; // equipped/detached this turn
  ua: number; // once-per-turn abilities used (bit per ability index)
  bf: Buff[];
  dep: number; // turn it entered play (deploy-trigger bookkeeping)
}

interface Player {
  force: number;
  bp: number; // build points left this build step / setup budget
  deck: number[]; // instance ids, index 0 = next draw
  mull: boolean; // mulligan done
  setupDone: boolean;
  setupSpent: number;
  drew: boolean; // took this turn's draw
  pending: number; // id of a card set aside in mulligan count
}

/** What the game is waiting for. */
type Phase =
  | "event" | "resource" | "mulligan" | "setup"
  | "build" | "retreat" | "pop" | "choose-attacker" | "attack-target"
  | "target" | "double" | "roll" | "over" | "flow";

/** A Play-or-Pass chance. */
interface Pop {
  /** gen = general (no unit attacking), atk = attack POP, prev = damage prevention, start/end = step POPs, dsr = a chance to disrupt the play on the stack. */
  kind: "gen" | "atk" | "prev" | "bstart" | "astart" | "aend" | "dsr";
  /** Consecutive passes so far; two in a row closes the chance. */
  passes: number;
}

/** The attack in progress. */
interface Attack {
  a: number; // attacker instance
  d: number; // defender instance
  ar: number; // arena the attack is in (the defender's)
  pw: number; // power bonus for this attack from effects
  shields: number;
  hits: number;
  dice: number[];
  pending: number; // pending damage after hits
  prevented: number;
  deflect: { from: number; n: number }[];
  retaliate: { u: number; n: number }[];
  disrupted: boolean;
  persuade: number;
  absorbTo: number[]; // [unit, amount] pairs flattened
  usedPrev: number[]; // instance*8+ability used this damage instance
  stage: number; // 0 declared, 1 rolled, 2 resolved
}

/** A target choice in progress for an effect being played. */
interface Choice {
  src: number; // source instance (or -1)
  ab: number; // ability index on the source def (-1 = the card itself, e.g. a Battle card's first effect)
  ctrl: number; // controller seat index
  need: Filter[]; // target filters still to choose
  got: number[]; // chosen targets
  /** What to do once all targets are chosen: "act" pays and resolves an activated ability, "trig" resolves a trigger. */
  then: "act" | "trig" | "battle";
  x: number; // X chosen (Pay X Force)
  /** The phase to return to afterwards. */
  back: Phase;
  /** Who was to act before a trigger's target choice interrupted (-1: unchanged). */
  bw: number;
}

/** A Battle card or activated ability that has been paid for and waits to resolve (the response stack). */
interface Pending {
  holder: number;
  k: number;
  ctrl: number;
  got: number[];
  x: number;
  /** A Battle card played from hand. */
  battle: boolean;
  /** Its effect disrupts something (what "Disrupt a disrupt" may answer). */
  dsr: boolean;
  /** Disrupted: it resolves to nothing. */
  off: boolean;
  fromHand: boolean;
}

/** Where play returns to once the response stack has resolved. */
interface StackBack {
  ph: Phase;
  who: number;
  pop: Pop | null;
  popNext: string;
  fl: string;
}

interface State {
  v: number;
  seats: string[];
  defs: Def[];
  cards: (Card | null)[];
  P: Player[];
  dark: number; // seat index playing first (Dark Side)
  rng: number;
  turn: number;
  ph: Phase;
  /** Seat index that must decide now. */
  who: number;
  /** Seat index whose step it is (build/retreat), or the attacking side. */
  step: number;
  arena: number;
  pop: Pop | null;
  /** The phase a POP returns to when it closes. */
  popNext: string;
  atk: Attack | null;
  choice: Choice | null;
  sel: number; // selected instance for 2-step actions (attacker / equipment), -1 none
  /** Result: -1 playing, 0/1 winner seat index, 2 draw. */
  win: number;
  /** Units that attacked in the current battle step (ids), so a re-untapped unit does not loop forever. */
  attacked: number[];
  /** The die rolled for build this turn. */
  roll: number;
  /** Event-log lines for the table (bounded; cleared each apply by the table side reading it). */
  log: string[];
  plies: number;
  /** Triggered abilities waiting to resolve, in order. */
  q: { src: number; ab: number; ctrl: number }[];
  /** The next automatic step when no decision is pending. */
  fl: string;
  /** Seat that took the last setup action / whose setup turn it is. */
  setupTurn: number;
  /** The response stack: plays waiting to resolve, the latest last. */
  stk: Pending[];
  stkBack: StackBack | null;
  /** Physical dice: the table rolls real dice and feeds their faces in (setup `dice: "table"`). */
  pd: boolean;
  /** Die faces fed in by the table, used before the seeded RNG. */
  dq: number[];
  /** Dice the pending roll needs (phase "roll"). */
  rollN: number;
  /** What the pending roll is for: "build" or "attack". */
  rollWhy: string;
}

/** Per-card actions (policy layout: slot * NA + action). */
const A_BUILD = 0;
const A_DEPLOY0 = 1; // complete/deploy into arena 0..2 (1,2,3)
const A_DEPLOY_BZ = 4; // complete into the build zone (units) / complete a non-unit
const A_MOVE0 = 5; // move a unit to arena 0..2 (5,6,7)
const A_ATTACK = 8; // own unit: choose as attacker; enemy unit: attack it
const A_RETREAT = 9;
const A_ACT0 = 10; // activate ability 0..3 (10..13)
const A_TARGET = 14; // choose as the pending target / select (mulligan, setup)
const A_EQUIP = 15; // equipment: select it; unit: attach the selected equipment to it
const NA = 16;
/** Card instances per game (128 per seat). */
const SLOTS = 256;
const HALF = 128;
/**
 * Move cells: a move names a CELL, laid out from the mover's side (see `cellMapOf`), not an
 * instance - so the policy is small and the same for both seats.
 */
const CELLS = 128;

/** Global actions, after the card block. */
const G_PASS = 0; // pass / done / end step
const G_MULL_DISCARD = 1;
const G_MULL_RETURN = 2;
const G_SKIP_ATTACK = 3; // tap the attacker without attacking
const G_NO = 4; // decline an optional trigger / double strike
const G_X0 = 5; // choose X = 0..15 (5..20); in a "roll" phase G_X0 + v is "the die shows v" (1..6)
const NG = 24;
const POLICY_SIZE = CELLS * NA + NG;

/** A move: `r` the cell of the card it concerns (-1 for a global move), `a` the action. */
interface Move {
  r: number;
  a: number;
}

// --------------------------------------------------------------------------------------------
// Seeded randomness (mulberry32, state kept in the game state as a uint32).
// --------------------------------------------------------------------------------------------

function rngNext(s: State): number {
  let a = (s.rng + 0x6d2b79f5) >>> 0;
  s.rng = a;
  let t = a;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

function rollDie(s: State): number {
  if (s.dq && s.dq.length > 0) return s.dq.shift() as number;
  return 1 + Math.floor(rngNext(s) * 6);
}

function shuffleIds(s: State, ids: number[]): void {
  for (let i = ids.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rngNext(s) * (i + 1));
    const t = ids[i];
    ids[i] = ids[j];
    ids[j] = t;
  }
}

function hashString(text: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < text.length; i += 1) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

function emptyFilter(): Filter {
  return { side: "any", ty: 0, sub: [], ar: -1, other: false, tapped: -1, damaged: false, unique: false };
}

function emptyTiming(): Timing {
  return { build: false, battle: false, attack: false, prevent: false, wouldAttack: false, arena: -1, once: false };
}

function arenaOfZone(z: Zone): number {
  return z === "a0" ? 0 : z === "a1" ? 1 : z === "a2" ? 2 : -1;
}

function zoneOfArena(ar: number): Zone {
  return ar === 0 ? "a0" : ar === 1 ? "a1" : "a2";
}

function arenaTypeFlag(ar: number): number {
  return ar === 0 ? T_SPACE : ar === 1 ? T_GROUND : T_CHAR;
}

// ============================================================================================
// Star Wars TCG rules kernel - part 1: card text -> abilities.
//
// Card text arrives as the catalogue writes it: abilities separated by " | ", activated
// abilities as "cost -> effect". The parser reads the common grammar (every keyword, the
// keyword activations, stat changes, damage, counters, draws, Force and build changes, the
// usual targets and timings) and marks everything else `none`. A card with an unread ability
// still plays with its stats and keywords; `Def.unk` counts what was skipped.
// ============================================================================================

/** Numeric keywords (cumulative values). */
const NUM_KW = [
  "Accuracy", "Shields", "Critical Hit", "Lucky", "Fury", "Parry", "Bombard", "Stun", "Focus",
  "Damage Control", "Resilience", "Riposte", "Velocity", "Avenge", "Surge", "Ion Cannon",
  "Backfire", "Area Damage", "Barrage", "Hidden Cost", "Overload"
];
/** Flag keywords. */
const FLAG_KW = [
  "Armor", "Stealth", "Overkill", "Double Strike", "Inspiration", "Precision", "Ferocity",
  "Cunning", "Double Damage", "Fortitude", "Intimidation"
];

const SUBTYPE_STOP = ["the", "a", "an", "of", "your", "unit", "units", "card", "cards", "and", "or", "in", "any", "arena"];

function cleanText(text: string): string {
  return text
    .replace(/’/g, "'")
    .replace(/“|”/g, "\"")
    .replace(/\s+/g, " ")
    .trim();
}

/** Remove reminder text in parentheses (keeps quoted granted abilities). */
function stripReminder(text: string): string {
  let out = "";
  let depth = 0;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text.charAt(i);
    if (ch === "(") {
      depth += 1;
      continue;
    }
    if (ch === ")") {
      if (depth > 0) depth -= 1;
      continue;
    }
    if (depth === 0) out += ch;
  }
  return out.replace(/\s+/g, " ").trim();
}

function parseIntWord(word: string): number {
  const w = word.toLowerCase();
  const words: { [k: string]: number } = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, all: 99 };
  if (w in words) return words[w];
  const n = parseInt(w, 10);
  return isNaN(n) ? -1 : n;
}

/** Card type string -> flags. */
function parseTypeFlags(type: string, subtype: string): number {
  const t = type.toLowerCase();
  let f = 0;
  if (t.indexOf("battle") >= 0) f |= T_BATTLE;
  if (t.indexOf("mission") >= 0) f |= T_MISSION;
  if (t.indexOf("equipment") >= 0) f |= T_EQUIP;
  if (t.indexOf("location") >= 0) f |= T_LOCATION;
  if (t.indexOf("resource") >= 0) f |= T_RESOURCE;
  if (t.indexOf("subordinate") >= 0) f |= T_SUBORD;
  if (t.indexOf("event") >= 0) f |= T_EVENT;
  // Units carry their arenas in the type; Equipment, Locations and Subordinates in the subtype.
  const arenaText = f === 0 ? t : (t + " " + subtype.split(" - ")[0]).toLowerCase();
  if (f === 0 || (f & (T_EQUIP | T_LOCATION | T_SUBORD)) !== 0) {
    if (arenaText.indexOf("space") >= 0) f |= T_SPACE;
    if (arenaText.indexOf("ground") >= 0) f |= T_GROUND;
    if (arenaText.indexOf("character") >= 0) f |= T_CHAR;
  }
  return f;
}

function parseSubtypes(subtype: string): string[] {
  return subtype
    .toLowerCase()
    .replace(/[^a-z0-9' -]/g, " ")
    .split(/[\s-]+/)
    .filter((w) => w.length > 0 && w !== "space" && w !== "ground" && w !== "character");
}

/** Try to read `text` as a list of keywords: "Focus 2, Precision, and Avenge 1". */
function parseKeywordList(text: string): KwMap | null {
  let t = stripReminder(text).replace(/\.$/, "").trim();
  if (t.length === 0) return null;
  t = t.replace(/,? and /g, ", ");
  const parts = t.split(/\s*,\s*/);
  const out: KwMap = {};
  for (const raw of parts) {
    const p = raw.trim();
    if (p.length === 0) continue;
    let matched = false;
    for (const kw of NUM_KW) {
      if (p.indexOf(kw) === 0) {
        const rest = p.slice(kw.length).trim();
        const m = /^([+-]?\d+)$/.exec(rest);
        if (m) {
          out[kw] = (out[kw] || 0) + parseInt(m[1], 10);
          matched = true;
        }
        break;
      }
    }
    if (matched) continue;
    let flag = p === "Elude" ? "Precision" : p;
    if (FLAG_KW.indexOf(flag) >= 0) {
      out[flag] = 1;
      continue;
    }
    return null;
  }
  return Object.keys(out).length > 0 ? out : null;
}

/** "+2 speed, +1 power, and +1 health" / "-3 power" -> stat triple, or null. */
function parseStatList(text: string): { sp: number; pw: number; hp: number } | null {
  const t = text.replace(/,? and /g, ", ").trim();
  const parts = t.split(/\s*,\s*/);
  let sp = 0;
  let pw = 0;
  let hp = 0;
  let any = false;
  for (const p of parts) {
    const m = /^([+-]\d+) (speed|power|health)$/.exec(p.trim());
    if (!m) return null;
    const n = parseInt(m[1], 10);
    if (m[2] === "speed") sp += n;
    else if (m[2] === "power") pw += n;
    else hp += n;
    any = true;
  }
  return any ? { sp, pw, hp } : null;
}

/** "+1 power and Accuracy 1" / "Lucky 2" / "+2 power" -> stats + keywords, or null. */
function parseGrant(text: string): { sp: number; pw: number; hp: number; kw: KwMap | null } | null {
  let t = stripReminder(text).replace(/\.$/, "").trim();
  t = t.replace(/,? and /g, ", ");
  const parts = t.split(/\s*,\s*/).filter((p) => p.length > 0);
  let sp = 0;
  let pw = 0;
  let hp = 0;
  const kw: KwMap = {};
  let anyKw = false;
  for (const p of parts) {
    const st = parseStatList(p);
    if (st) {
      sp += st.sp;
      pw += st.pw;
      hp += st.hp;
      continue;
    }
    const k = parseKeywordList(p);
    if (k) {
      for (const key of Object.keys(k)) kw[key] = (kw[key] || 0) + k[key];
      anyKw = true;
      continue;
    }
    return null;
  }
  return { sp, pw, hp, kw: anyKw ? kw : null };
}

function parseArenaPhrase(text: string): number {
  if (/in the Space arena/i.test(text)) return AR_SPACE;
  if (/in the Ground arena/i.test(text)) return AR_GROUND;
  if (/in the Character arena/i.test(text)) return AR_CHAR;
  if (/in this arena|in the same arena/i.test(text)) return 3;
  return -1;
}

/**
 * The noun part of a target phrase -> type flags and subtype words.
 * "units" -> any unit; "Characters" -> T_CHAR; "Space units" -> T_SPACE; "Jedi" -> subtype jedi.
 */
function parseNoun(noun: string, f: Filter): boolean {
  const low = noun.toLowerCase().replace(/\bin (the|this|any|that) [a-z]+ ?(arena)?\b.*$/, "").trim();
  // Lists: "Space and Ground units", "Separatist, Trade Federation, and Geonosian units".
  if (/,| and | or /.test(low) && !/ with | that /.test(low)) {
    let tail = "";
    const lm = /\s(units?|characters?)$/.exec(low);
    let body = low;
    if (lm) {
      tail = lm[1];
      body = low.slice(0, low.length - lm[0].length);
    }
    const pieces = body.split(/\s*,\s*(?:and |or )?|\s+and\s+|\s+or\s+/).filter((x) => x.length > 0);
    if (pieces.length < 2) return parseNounOne(noun, f);
    let ty = 0;
    const alts: string[] = [];
    for (const piece of pieces) {
      if (piece === "space") ty |= T_SPACE;
      else if (piece === "ground") ty |= T_GROUND;
      else if (piece === "character" || piece === "characters") ty |= T_CHAR;
      else {
        const g = emptyFilter();
        if (!parseNounOne(piece + (tail ? " " + tail : ""), g)) return false;
        alts.push(g.sub.join(" "));
        if (g.ty !== T_UNIT) ty |= g.ty;
      }
    }
    if (tail === "characters" || tail === "character") ty |= T_CHAR;
    f.ty = ty === 0 ? T_UNIT : ty;
    if (alts.length > 0) {
      if (ty !== 0 && alts.length < pieces.length) return false;
      f.sub = ["|" + alts.join("|")];
    }
    return true;
  }
  return parseNounOne(noun, f);
}

function parseNounOne(noun: string, f: Filter): boolean {
  let n = noun.toLowerCase().replace(/\bin (the|this|any|that) [a-z]+ ?(arena)?\b.*$/, "").trim();
  n = n.replace(/\bwith .*$/, "").replace(/\bthat .*$/, "").trim();
  if (n.indexOf("untapped ") === 0) {
    f.tapped = 0;
    n = n.slice(9);
  }
  if (n.indexOf("tapped ") === 0) {
    f.tapped = 1;
    n = n.slice(7);
  }
  if (n.indexOf("damaged ") === 0) {
    f.damaged = true;
    n = n.slice(8);
  }
  if (n.indexOf("unique ") === 0) {
    f.unique = true;
    n = n.slice(7);
  }
  if (n.indexOf("other ") === 0) {
    f.other = true;
    n = n.slice(6);
  }
  n = n.trim();
  if (n === "location" || n === "locations") {
    f.ty = T_LOCATION;
    return true;
  }
  if (n === "mission" || n === "missions" || n === "mission cards") {
    f.ty = T_MISSION;
    return true;
  }
  if (n === "equipment" || n === "equipment cards") {
    f.ty = T_EQUIP;
    return true;
  }
  if (n === "battle cards" || n === "battle card") {
    f.ty = T_BATTLE;
    return true;
  }
  if (n === "unit" || n === "units") {
    f.ty = T_UNIT;
    return true;
  }
  if (n === "character" || n === "characters" || n === "character unit" || n === "character units") {
    f.ty = T_CHAR;
    return true;
  }
  if (n === "space unit" || n === "space units") {
    f.ty = T_SPACE;
    return true;
  }
  if (n === "ground unit" || n === "ground units") {
    f.ty = T_GROUND;
    return true;
  }
  if (n === "ground units or characters" || n === "ground unit or character") {
    f.ty = T_GROUND | T_CHAR;
    return true;
  }
  // "Jedi", "Droids", "Capital Ships", "Republic units", "Sith Characters"
  let words = n.split(/\s+/).filter((w) => w.length > 0);
  if (words.length === 0 || words.length > 3) return false;
  const last = words[words.length - 1];
  if (last === "units" || last === "unit") {
    words = words.slice(0, -1);
    f.ty = T_UNIT;
  } else if (last === "characters" || last === "character") {
    words = words.slice(0, -1);
    f.ty = T_CHAR;
  } else {
    f.ty = T_UNIT;
  }
  if (words.length === 0) return true;
  for (const w of words) {
    if (SUBTYPE_STOP.indexOf(w) >= 0 || /[^a-z']/.test(w)) return false;
  }
  // Plural: "droids" -> "droid", "jedi" stays.
  f.sub = words.map((w, i) => (i === words.length - 1 && w.length > 3 && /s$/.test(w) && !/ss$/.test(w) ? w.slice(0, -1) : w));
  return true;
}

type TargetRef = { kind: "self" } | { kind: "prev" } | { kind: "attacker" } | { kind: "defender" } | { kind: "tgt"; f: Filter } | { kind: "all"; f: Filter };

/** Parse a target phrase relative to the card `name`. */
function parseTarget(phrase: string, name: string, base: string): TargetRef | null {
  let p = phrase.trim().replace(/\.$/, "");
  const lower = p.toLowerCase();
  if (lower === "this unit" || lower === "it" && false || p === name || p === base || lower === "this card" || lower === "this character") return { kind: "self" };
  const firstName = base.split(" ")[0];
  if (p === firstName && firstName.length > 2) return { kind: "self" };
  if (lower === "that unit" || lower === "the chosen unit" || lower === "it" || lower === "that character" || /^the chosen [a-z ]+$/.test(lower)) return { kind: "prev" };
  if (lower === "the attacking unit" || lower === "an attacking unit" || lower === "that attacking unit") return { kind: "attacker" };
  if (lower === "the defending unit") return { kind: "defender" };
  const f = emptyFilter();
  f.ar = parseArenaPhrase(p);
  let m: RegExpExecArray | null;
  if ((m = /^each of your opponent'?s (.+)$/i.exec(p))) {
    f.side = "opp";
    return parseNoun(m[1], f) ? { kind: "all", f } : null;
  }
  if ((m = /^each of your (.+)$/i.exec(p))) {
    f.side = "me";
    return parseNoun(m[1], f) ? { kind: "all", f } : null;
  }
  if ((m = /^each (unit|character|space unit|ground unit) (.*)$/i.exec(p))) {
    f.side = "any";
    return parseNoun(m[1], f) ? { kind: "all", f } : null;
  }
  if ((m = /^(?:one of|choose one of) your opponent'?s (.+)$/i.exec(p)) || (m = /^an opponent'?s (.+)$/i.exec(p)) || (m = /^target opponent'?s (.+)$/i.exec(p))) {
    f.side = "opp";
    return parseNoun(m[1], f) ? { kind: "tgt", f } : null;
  }
  if ((m = /^(?:one of|choose one of) your (.+)$/i.exec(p))) {
    f.side = "me";
    return parseNoun(m[1], f) ? { kind: "tgt", f } : null;
  }
  if ((m = /^(?:a|an|target|another) (.+)$/i.exec(p))) {
    f.side = "any";
    if (/^another /i.test(p)) f.other = true;
    return parseNoun(m[1], f) ? { kind: "tgt", f } : null;
  }
  return null;
}

/** "as long as ..." -> condition, or null. */
function parseCond(text: string, name: string, base: string): Cond | null {
  const t = text.replace(/\.$/, "").trim();
  const first = base.split(" ")[0];
  const isMe = (w: string) => w === "this unit" || w === name || w === base || w === first || w === "it";
  let m: RegExpExecArray | null;
  if ((m = /^(.+?) is in the (Space|Ground|Character) arena$/.exec(t)) && isMe(m[1])) return { c: "selfAr", ar: m[2] === "Space" ? 0 : m[2] === "Ground" ? 1 : 2 };
  if ((m = /^(.+?) has (?:a|at least one) Pilot$/.exec(t)) && isMe(m[1])) return { c: "pilot" };
  if ((m = /^(.+?) has no damage counters on it$/.exec(t)) && isMe(m[1])) return { c: "undamaged" };
  if ((m = /^(.+?) (?:has (?:one or more|any|a) damage counters? on it|is damaged)$/.exec(t)) && isMe(m[1])) return { c: "damaged" };
  if ((m = /^your Force total is (\d+) or more$/i.exec(t))) return { c: "force", n: parseInt(m[1], 10) };
  if ((m = /^there is an? ([\w' -]*?)\s?Location in (any arena|the (Space|Ground|Character) arena)$/i.exec(t))) {
    return { c: "loc", sub: m[1] ? parseSubtypes(m[1]) : [], ar: m[3] ? (m[3] === "Space" ? 0 : m[3] === "Ground" ? 1 : 2) : -1 };
  }
  if ((m = /^there is an? (?!Location\b)([A-Z][\w' -]+?) in (any arena|the (Space|Ground|Character) arena)$/.exec(t))) {
    const f = emptyFilter();
    f.side = "any";
    f.ar = m[3] ? (m[3] === "Space" ? 0 : m[3] === "Ground" ? 1 : 2) : -1;
    if (!parseNoun(m[1], f)) return null;
    return { c: "have", f };
  }
  if ((m = /^you have an? Location in (any arena|the (Space|Ground|Character) arena)$/i.exec(t))) {
    return { c: "loc", sub: [], ar: m[2] ? (m[2] === "Space" ? 0 : m[2] === "Ground" ? 1 : 2) : -1 };
  }
  if ((m = /^(?:a|an) ([A-Z][\w' -]+?) is in (any arena|the (Space|Ground|Character) arena)$/.exec(t))) {
    const f = emptyFilter();
    f.side = "any";
    f.ar = m[3] ? (m[3] === "Space" ? 0 : m[3] === "Ground" ? 1 : 2) : -1;
    if (!parseNoun(m[1], f)) return null;
    return { c: "have", f };
  }
  if ((m = /^you have (a|an|another|any) (.+?) in (any arena|this arena|the (?:Space|Ground|Character) arena)$/i.exec(t))) {
    const f = emptyFilter();
    f.side = "me";
    f.other = m[1] === "another";
    f.ar = parseArenaPhrase("in " + m[3]);
    if (!parseNoun(m[2], f)) return null;
    return { c: "have", f };
  }
  if ((m = /^([A-Z][\w' -]+?) is in (any arena|the (Space|Ground|Character) arena)$/.exec(t))) {
    return { c: "name", n: m[1].toLowerCase(), ar: m[3] ? (m[3] === "Space" ? 0 : m[3] === "Ground" ? 1 : 2) : -1 };
  }
  return null;
}

interface ParseCtx {
  name: string;
  base: string;
  tg: Filter[];
  /** Target index of the last chosen target ("that unit"). */
  last: number;
  tm: Timing;
  ok: boolean;
}

function whoFor(ref: TargetRef, ctx: ParseCtx): Who | null {
  if (ref.kind === "self") return { w: "self" };
  if (ref.kind === "attacker") return { w: "attacker" };
  if (ref.kind === "defender") return { w: "defender" };
  if (ref.kind === "prev") return ctx.last >= 0 ? { w: "tgt", i: ctx.last } : { w: "self" };
  if (ref.kind === "all") return { w: "all", f: ref.f };
  ctx.tg.push(ref.f);
  ctx.last = ctx.tg.length - 1;
  return { w: "tgt", i: ctx.last };
}

function parseDuration(text: string): "T" | "A" | "B" | "G" | null {
  if (/for this attack/i.test(text)) return "A";
  if (/until end of battle/i.test(text)) return "B";
  if (/until (the )?end of (the )?turn|this turn/i.test(text)) return "T";
  if (/until end of game|for the rest of the game/i.test(text)) return "G";
  return null;
}

/** Play-only restrictions. Unknown conditions fail the parse (the ability is then unusable). */
function parseRestriction(sentence: string, ctx: ParseCtx): boolean {
  const s = sentence.replace(/^Play only /i, "").replace(/\.$/, "");
  const clauses = s.split(/,? and (?:only )?/i);
  for (const c0 of clauses) {
    const c = c0.trim().toLowerCase();
    if (c === "during your build step") ctx.tm.build = true;
    else if (c === "when no unit is attacking" || c === "if no unit is attacking" || c === "while no unit is attacking") ctx.tm.battle = true;
    else if (c === "when this unit would attack" || c === "if this unit would attack") ctx.tm.wouldAttack = true;
    else if (c === "once per turn" || c === "once each turn") ctx.tm.once = true;
    else if (c === "when the battle phase starts" || c === "during the battle phase" || c === "during battle") ctx.tm.battle = true;
    else if (c === "when this unit is attacking" || c === "if this unit is attacking" || c === "when this unit attacks") ctx.tm.attack = true;
    else if (c === "when this unit is being attacked" || c === "if this unit is being attacked" || c === "when this unit is attacked") ctx.tm.attack = true;
    else if (/^(?:when|during) the (space|ground|character) battle step(?: starts| ends)?$/.test(c)) {
      const m = /(space|ground|character)/.exec(c) as RegExpExecArray;
      ctx.tm.arena = m[1] === "space" ? 0 : m[1] === "ground" ? 1 : 2;
      ctx.tm.battle = true;
    } else if (c === "any time" || c === "anytime") {
      ctx.tm.build = true;
      ctx.tm.battle = true;
      ctx.tm.attack = true;
    } else if (c === "if this unit is in an arena" || c === "if this unit is in its arena") {
      // the default for unit abilities
    } else return false;
  }
  return true;
}

/** "Do 3 damage to X", "This unit does 2 dice of damage to X", "Put 2 damage counters on X"... */
function parseEffectSentence(sentence0: string, ctx: ParseCtx, fx: Eff[]): boolean {
  let sentence = stripReminder(sentence0).replace(/"$/, "").replace(/^"/, "").trim();
  if (sentence.length === 0) return true;
  sentence = sentence.replace(/\.$/, "").trim();
  let m: RegExpExecArray | null;
  if (/^Play only /i.test(sentence)) return parseRestriction(sentence, ctx);
  if (/^Play (?:any ?time|at any time)$/i.test(sentence)) {
    ctx.tm.build = ctx.tm.battle = ctx.tm.attack = true;
    return true;
  }
  if (/^(?:Then )?shuffle your deck$/i.test(sentence)) return true;
  // Keyword activations.
  if ((m = /^((?:Evade|Deflect|Absorb|Protect|Persuade) \d+) and ((?:Evade|Deflect|Absorb|Protect|Persuade) \d+)$/.exec(sentence))) {
    return parseEffectSentence(m[1], ctx, fx) && parseEffectSentence(m[2], ctx, fx);
  }
  if ((m = /^(Evade|Deflect|Absorb|Protect|Persuade) (\d+|X)$/.exec(sentence))) {
    const kind = m[1].toLowerCase() as "evade" | "deflect" | "absorb" | "protect" | "persuade";
    fx.push({ e: "prevent", kind, n: m[2] === "X" ? 0 : parseInt(m[2], 10), x: m[2] === "X" });
    ctx.tm.prevent = true;
    return true;
  }
  if ((m = /^Retaliate (\d+)$/.exec(sentence))) {
    fx.push({ e: "retaliate", n: parseInt(m[1], 10) });
    ctx.tm.attack = true;
    return true;
  }
  if (sentence === "Intercept") {
    fx.push({ e: "intercept" });
    ctx.tm.attack = true;
    return true;
  }
  if (sentence === "Redirect") {
    fx.push({ e: "redirect" });
    ctx.tm.attack = true;
    return true;
  }
  if ((m = /^Ambush (\d+)$/.exec(sentence))) {
    fx.push({ e: "ambush", n: parseInt(m[1], 10) });
    return true;
  }
  if (/^Equip$/.test(sentence)) {
    fx.push({ e: "equip" });
    ctx.tm.build = true;
    return true;
  }
  if (/^Meditate$/.test(sentence)) {
    fx.push({ e: "meditate" });
    return true;
  }
  if ((m = /^Search your deck for (a|an|one|up to two|up to three|up to \d+|two|three|\d+) (.+?) cards?(?:,| and)? (?:(?:show (?:it|them) to your opponent|reveal (?:it|them)),? (?:and )?)?(?:and )?put (?:it|them) into your (hand|build zone)(?: with (\d+) build counters? on (?:it|them))?$/i.exec(sentence))) {
    const desc = parseCardDesc(m[2]);
    if (!desc) return false;
    fx.push({ e: "search", ty: desc.ty, sub: desc.sub, n: parseIntWord(m[1].replace(/^up to /i, "")), dest: m[3].toLowerCase() === "hand" ? "hand" : "build", bc: m[4] ? parseInt(m[4], 10) : 0, from: "deck", uq: desc.uq });
    return true;
  }
  if ((m = /^Search your deck for (a|an|one) (.+?) card$/i.exec(sentence))) {
    const desc = parseCardDesc(m[2]);
    if (!desc) return false;
    fx.push({ e: "search", ty: desc.ty, sub: desc.sub, n: 1, dest: "hand", bc: 0, from: "deck", uq: desc.uq });
    return true;
  }
  if ((m = /^If you do, (?:show it to your opponent,? and )?put it into your (hand|build zone)(?: with (\d+) build counters? on it)?$/i.exec(sentence))) {
    const last = fx[fx.length - 1];
    if (!last || last.e !== "search") return false;
    last.dest = m[1].toLowerCase() === "hand" ? "hand" : "build";
    last.bc = m[2] ? parseInt(m[2], 10) : 0;
    return true;
  }
  if ((m = /^Return (a|an|one|up to two|two) (.+?) cards? from your discard pile to your hand$/i.exec(sentence))) {
    const desc = parseCardDesc(m[2]);
    if (!desc) return false;
    fx.push({ e: "search", ty: desc.ty, sub: desc.sub, n: parseIntWord(m[1].replace(/^up to /i, "")), dest: "hand", bc: 0, from: "disc", uq: desc.uq });
    return true;
  }
  // "Take 1 60/2/1 Vulture Droid Fighter Subordinate with "..." and put it into the Space arena."
  if ((m = /^Take (\d+|a|an|one|two) (?:[\d*X]+\/[\d*X]+\/[\d*X]+ )?(.+?) Subordinates?(?: with .+?)? and put (?:it|them|each) (?:in ?to|in) (the (Space|Ground|Character)(?: or (?:the )?(Space|Ground|Character))? arenas?|its arena|their arenas?|this arena|the same arena)$/i.exec(sentence))) {
    const arOf = (w: string) => (w === "Space" ? 0 : w === "Ground" ? 1 : 2);
    const ars = m[4] ? [arOf(m[4])].concat(m[5] ? [arOf(m[5])] : []) : /this arena|same arena/i.test(m[3]) ? [3] : [];
    fx.push({ e: "take", n: parseIntWord(m[1]), nm: m[2].toLowerCase().replace(/\s*\([a-z]\)$/, "").trim(), ars });
    return true;
  }
  if (/^Look at your opponent'?s hand$/i.test(sentence) || /^Look at the (?:t[o]p|next) \d+ cards? of your deck$/i.test(sentence)) {
    fx.push({ e: "noop" });
    return true;
  }
  if ((m = /^Draw (?:up to )?(a|one|two|three|\d+) cards?,? (?:and )?then discard (a|one|two|three|\d+) cards? from your hand$/i.exec(sentence))) {
    fx.push({ e: "draw", n: parseIntWord(m[1]) });
    fx.push({ e: "selfDiscard", n: parseIntWord(m[2]) });
    return true;
  }
  if ((m = /^(?:Then )?(?:you )?gain \+(\d+) Force$/i.exec(sentence))) {
    fx.push({ e: "force", n: parseInt(m[1], 10), opp: false });
    return true;
  }
  if ((m = /^(?:Then )?discard (a|one|two|\d+) cards? from your hand$/i.exec(sentence))) {
    fx.push({ e: "selfDiscard", n: parseIntWord(m[1]) });
    return true;
  }
  if ((m = /^Draw (a|one|two|three|\d+) cards?$/i.exec(sentence))) {
    fx.push({ e: "draw", n: parseIntWord(m[1]) });
    return true;
  }
  if ((m = /^(?:Then )?(?:You )?gain (\d+) Force$/i.exec(sentence))) {
    fx.push({ e: "force", n: parseInt(m[1], 10), opp: false });
    return true;
  }
  if ((m = /^(?:You )?gain (\d+) build points?$/i.exec(sentence))) {
    fx.push({ e: "bp", n: parseInt(m[1], 10), opp: false });
    return true;
  }
  if ((m = /^Your opponent loses (\d+) Force$/i.exec(sentence))) {
    fx.push({ e: "force", n: -parseInt(m[1], 10), opp: true });
    return true;
  }
  if ((m = /^Your opponent loses (\d+) build points?$/i.exec(sentence))) {
    fx.push({ e: "bp", n: -parseInt(m[1], 10), opp: true });
    return true;
  }
  if ((m = /^Your opponent discards (a|one|two|\d+) cards?(?: at random)? from (?:his or her|their) hand$/i.exec(sentence))) {
    fx.push({ e: "oppDiscard", n: parseIntWord(m[1]), random: /random/i.test(sentence) });
    return true;
  }
  if ((m = /^Add (\d+) counters? to (?:your Resource|this card|this Resource)$/i.exec(sentence))) {
    fx.push({ e: "addCtr", n: parseInt(m[1], 10) });
    return true;
  }
  if ((m = /^Disrupt (an attack|a Battle card or (?:an )?activated ability|a Battle card|an activated ability|a disrupt|a Mission card|a non-unit card)(?: against [^,]+?)?(?: unless (?:your|its controller'?s?) opponent pays (\d+) Force| unless its controller pays (\d+) Force)?$/i.exec(sentence))) {
    const w = m[1].toLowerCase();
    const what = w === "an attack" ? "attack" : w.indexOf(" or ") >= 0 ? "any" : w === "a disrupt" ? "dsr" : w === "a mission card" ? "mission" : w === "an activated ability" ? "act" : "battle";
    fx.push({ e: "disrupt", what, unless: m[2] ? parseInt(m[2], 10) : m[3] ? parseInt(m[3], 10) : 0 });
    if (what === "attack") ctx.tm.attack = true;
    return true;
  }
  if ((m = /^(?:This unit|[A-Z][\w' -]*) gets (.+?)(?: until end of turn| for this attack| until end of battle| this turn| until the end of turn)?$/.exec(sentence)) && (m[0].indexOf("This unit") === 0 || m[0].indexOf(ctx.base.split(" ")[0]) === 0 || m[0].indexOf(ctx.name) === 0)) {
    const g = parseGrant(m[1]);
    if (!g) return false;
    fx.push({ e: "stat", who: { w: "self" }, sp: g.sp, pw: g.pw, hp: g.hp, u: parseDuration(sentence) || "T", kw: g.kw });
    return true;
  }
  // "<Target> gets +N power for this attack."
  if ((m = /^(.+?) gets? (.+?)( until end of turn| for this attack| until end of battle| this turn| until the end of turn)?$/.exec(sentence))) {
    const ref = parseTarget(m[1], ctx.name, ctx.base);
    const g = parseGrant(m[2]);
    if (!ref || !g) return false;
    const who = whoFor(ref, ctx);
    if (!who) return false;
    fx.push({ e: "stat", who, sp: g.sp, pw: g.pw, hp: g.hp, u: parseDuration(sentence) || "T", kw: g.kw });
    return true;
  }
  if ((m = /^(?:Do|This unit does) X damage to (.+)$/.exec(sentence))) {
    const ref = parseTarget(m[1], ctx.name, ctx.base);
    if (!ref) return false;
    const who = whoFor(ref, ctx);
    if (!who) return false;
    fx.push({ e: "damage", who, n: -1, dice: false, nx: false });
    return true;
  }
  if ((m = /^Prevent (?:up to )?X damage to (.+)$/i.exec(sentence))) {
    const ref = parseTarget(m[1], ctx.name, ctx.base);
    if (!ref) return false;
    fx.push({ e: "prevent", kind: ref.kind === "self" ? "evade" : "protect", n: 0, x: true });
    if (ref.kind === "tgt") {
      ctx.tg.push(ref.f);
      ctx.last = ctx.tg.length - 1;
    }
    ctx.tm.prevent = true;
    return true;
  }
  if ((m = /^Choose (an? (?!arena\b)[\w' -]+)$/i.exec(sentence))) {
    const ref = parseTarget(m[1], ctx.name, ctx.base);
    if (ref && ref.kind === "tgt") {
      whoFor(ref, ctx);
      return true;
    }
  }
  if ((m = /^Choose (.+)$/i.exec(sentence)) && !/^Choose (an arena|one:|one of the following)/i.test(sentence)) {
    const ref = parseTarget("one of " + m[1].replace(/^one of /i, ""), ctx.name, ctx.base) || parseTarget(m[1], ctx.name, ctx.base);
    if (!ref || ref.kind !== "tgt") return false;
    whoFor(ref, ctx);
    return true;
  }
  if ((m = /^(?:This unit does|Do|[A-Z][\w' -]* does) (\d+) (dice of )?damage to (.+?)( that can't be prevented)?$/.exec(sentence))) {
    if (!/^(This unit does|Do )/.test(sentence) && sentence.indexOf(ctx.base.split(" ")[0]) !== 0) return false;
    const ref = parseTarget(m[3], ctx.name, ctx.base);
    if (!ref) return false;
    const who = whoFor(ref, ctx);
    if (!who) return false;
    fx.push({ e: "damage", who, n: parseInt(m[1], 10), dice: !!m[2], nx: !!m[4] });
    return true;
  }
  if ((m = /^Put (\d+|a) damage counters? on (.+)$/i.exec(sentence))) {
    const ref = parseTarget(m[2], ctx.name, ctx.base);
    if (!ref) return false;
    const who = whoFor(ref, ctx);
    if (!who) return false;
    fx.push({ e: "counters", who, n: parseIntWord(m[1]), remove: false });
    return true;
  }
  if ((m = /^Remove (?:up to )?(\d+|a|all) damage counters? from (.+)$/i.exec(sentence))) {
    const ref = parseTarget(m[2], ctx.name, ctx.base);
    if (!ref) return false;
    const who = whoFor(ref, ctx);
    if (!who) return false;
    fx.push({ e: "counters", who, n: parseIntWord(m[1]), remove: true });
    return true;
  }
  if ((m = /^Prevent (?:up to )?(\d+|all) damage to (.+)$/i.exec(sentence))) {
    const ref = parseTarget(m[2], ctx.name, ctx.base);
    if (!ref) return false;
    if (ref.kind === "self") {
      fx.push({ e: "prevent", kind: m[1] === "all" ? "all" : "evade", n: m[1] === "all" ? 99 : parseInt(m[1], 10), x: false });
    } else if (ref.kind === "tgt" || ref.kind === "defender") {
      fx.push({ e: "prevent", kind: m[1] === "all" ? "all" : "protect", n: m[1] === "all" ? 99 : parseInt(m[1], 10), x: false });
    } else return false;
    ctx.tm.prevent = true;
    return true;
  }
  if ((m = /^(Tap|Untap|Retreat|Discard) (.+)$/.exec(sentence))) {
    if (m[1] === "Discard" && /from your hand|your hand|cards? from/i.test(m[2])) return false;
    const ref = parseTarget(m[2], ctx.name, ctx.base);
    if (!ref) return false;
    const who = whoFor(ref, ctx);
    if (!who) return false;
    const e = m[1] === "Tap" ? "tap" : m[1] === "Untap" ? "untap" : m[1] === "Retreat" ? "retreat" : "discardUnit";
    fx.push({ e, who } as Eff);
    return true;
  }
  if ((m = /^Discard the (?:t[o]p|next) (\d+|a) cards? (?:of|from) your opponent'?s deck$/i.exec(sentence))) {
    fx.push({ e: "mill", n: parseIntWord(m[1]), opp: true });
    return true;
  }
  if (/^This unit may attack again/i.test(sentence) || /^This unit can attack again/i.test(sentence)) {
    fx.push({ e: "attackAgain" });
    return true;
  }
  return false;
}

/** "Kylo Ren unit", "Location", "Jedi Character unit", "Equipment" -> type flags + words. */
function parseCardDesc(desc0: string): { ty: number; sub: string[]; uq: boolean } | null {
  let d = desc0.trim();
  let ty = 0;
  let uq = false;
  if (/^unique /i.test(d)) {
    uq = true;
    d = d.slice(7).trim();
  }
  const strip = (re: RegExp, flag: number) => {
    const mm = re.exec(d);
    if (mm) {
      ty |= flag;
      d = d.slice(0, mm.index).trim();
    }
  };
  strip(/\s*\bLocation$/i, T_LOCATION);
  strip(/\s*\bEquipment$/i, T_EQUIP);
  strip(/\s*\bMission$/i, T_MISSION);
  strip(/\s*\bBattle$/i, T_BATTLE);
  strip(/\s*\bResource$/i, T_RESOURCE);
  if (/\bunit$/i.test(d)) {
    d = d.replace(/\s*\bunit$/i, "").trim();
    if (/\bSpace$/i.test(d)) {
      ty |= T_SPACE;
      d = d.replace(/\s*\bSpace$/i, "").trim();
    } else if (/\bGround$/i.test(d)) {
      ty |= T_GROUND;
      d = d.replace(/\s*\bGround$/i, "").trim();
    } else if (/\bCharacter$/i.test(d)) {
      ty |= T_CHAR;
      d = d.replace(/\s*\bCharacter$/i, "").trim();
    } else ty |= T_UNIT;
  }
  if (ty === 0 && /^(any|a) ?$/i.test(d)) return { ty: 0, sub: [], uq };
  const words = d.toLowerCase().replace(/[^a-z0-9' -]/g, " ").split(/[\s-]+/).filter((w) => w.length > 0 && w !== "any" && w !== "non" && w !== "with");
  if (words.length > 4 || /[0-9]/.test(d)) return null;
  return { ty, sub: words, uq };
}

/** Split an effect paragraph into sentences, keeping quoted text whole. */
function splitSentences(text: string): string[] {
  const out: string[] = [];
  let cur = "";
  let q = false;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text.charAt(i);
    if (ch === "\"") q = !q;
    cur += ch;
    if (!q && ch === "." && (i + 1 >= text.length || text.charAt(i + 1) === " ")) {
      out.push(cur.trim());
      cur = "";
    }
  }
  if (cur.trim().length > 0) out.push(cur.trim());
  return out;
}

function parseEffects(text: string, ctx: ParseCtx): Eff[] {
  const fx: Eff[] = [];
  for (const s of splitSentences(text)) {
    if (parseEffectSentence(s, ctx, fx)) continue;
    // "Tap that unit and do 2 damage to it": two effects joined by "and".
    const j = /^(.+?),? and ((?:do|tap|untap|draw|gain|put|remove|retreat|discard|this unit gets|it gets)\b.*)$/i.exec(stripReminder(s).replace(/\.$/, ""));
    if (j) {
      const rest = j[2].charAt(0).toUpperCase() + j[2].slice(1);
      const mark = fx.length;
      if (parseEffectSentence(j[1], ctx, fx) && parseEffectSentence(rest.replace(/ to it$/, " to that unit").replace(/^It gets/, "That unit gets"), ctx, fx)) continue;
      fx.length = mark;
    }
    ctx.ok = false;
    break;
  }
  return fx;
}

/** "Pay 2 Force, tap this unit" -> costs, or null. */
function parseCosts(text: string, name: string, base: string): Cost[] | null {
  let t = stripReminder(text).replace(/^\[tap\]|^\[Tap\]/, "Tap").replace(/\.$/, "").trim();
  t = t.replace(/^Pay X Force, (?:where X is (\d+) or less|up to (\d+))/i, (_a, x1: string, x2: string) => "Pay X Force max " + (x1 || x2));
  t = t.replace(/^(?:INSERT|Reserves|Enhance): */i, "");
  const parts = t.split(/\s*,\s*|\s+and\s+/).filter((p) => p.length > 0);
  const out: Cost[] = [];
  for (const p0 of parts) {
    const p = p0.replace(/^\[tap\]$|^\[Tap\]$/, "Tap").trim();
    let m: RegExpExecArray | null;
    if ((m = /^Pay (\d+) (?:more )?Force$/i.exec(p))) out.push({ c: "force", n: parseInt(m[1], 10) });
    else if (/^Pay X Force$/i.test(p)) out.push({ c: "forceX", cap: 99 });
    else if ((m = /^Pay X Force max (\d+)$/i.exec(p))) out.push({ c: "forceX", cap: parseInt(m[1], 10) });
    else if ((m = /^Pay (\d+) build(?: points?)?$/i.exec(p))) out.push({ c: "bp", n: parseInt(m[1], 10) });
    else if ((m = /^(?:Pay )?(\d+) Force$/i.exec(p))) out.push({ c: "force", n: parseInt(m[1], 10) });
    else if ((m = /^(\d+) Force pay$/i.exec(p))) out.push({ c: "force", n: parseInt(m[1], 10) });
    else if ((m = /^Pay (\d+) build points?, (\d+) Force$/i.exec(p))) {
      out.push({ c: "bp", n: parseInt(m[1], 10) });
      out.push({ c: "force", n: parseInt(m[2], 10) });
    } else if (/^Tap(?: this unit)?$/i.test(p) || p === "Tap " + base || p === "Tap " + name) out.push({ c: "tap" });
    else if ((m = /^Discard (a|one|two|\d+) cards? from your hand$/i.exec(p))) out.push({ c: "discard", n: parseIntWord(m[1]) });
    else if ((m = /^Add (\d+) counters?(?: to (?:this card|your Resource|this Resource))?$/i.exec(p))) out.push({ c: "addCtr", n: parseInt(m[1], 10) });
    else if ((m = /^Remove (\d+) counters?(?: from (?:this card|your Resource|this Resource))?$/i.exec(p))) out.push({ c: "remCtr", n: parseInt(m[1], 10) });
    else if ((m = /^Put (\d+|a) damage counters? on (?:this unit|it)$/i.exec(p))) out.push({ c: "dmgSelf", n: parseIntWord(m[1]) });
    else if (/^Retreat this unit$/i.test(p)) out.push({ c: "retreatSelf" });
    else if ((m = /^Tap (one of your .+)$/i.exec(p))) {
      const ref = parseTarget(m[1], name, base);
      if (!ref || ref.kind !== "tgt") return null;
      out.push({ c: "tapOther", f: ref.f });
    } else return null;
  }
  return out;
}

/** A trigger's event key, or null. Covers the common "When ..." openings. */
function parseTriggerEvent(cond: string, name: string, base: string): string | null {
  const c = cond.replace(/,$/, "").trim();
  const first = base.split(" ")[0];
  const isSelf = (w: string) => w === "this unit" || w === name || w === base || w === first;
  let m: RegExpExecArray | null;
  if ((m = /^When(?:ever)? you deploy (.+)$/i.exec(c)) && isSelf(m[1])) return "deploy";
  if ((m = /^When(?:ever)? (.+?) attacks(?: a unit)?$/i.exec(c)) && isSelf(m[1])) return "attacks";
  if ((m = /^When(?:ever)? (.+?) is attacked$/i.exec(c)) && isSelf(m[1])) return "attacked";
  if ((m = /^When(?:ever)? (.+?) is discarded$/i.exec(c)) && isSelf(m[1])) return "discarded";
  if ((m = /^When(?:ever)? (.+?) damages (?:a|an|one of your opponent'?s) unit$/i.exec(c)) && isSelf(m[1])) return "damages";
  if (/^When your build step starts$/i.test(c)) return "buildStart";
  if (/^When each turn starts$/i.test(c)) return "turnStart";
  if (/^When(?:ever)? the roll for build points is made$/i.test(c) || /^When(?:ever)? you roll for build points$/i.test(c)) return "buildRoll";
  if (/^When the battle phase starts$/i.test(c)) return "battleStart";
  if (/^When the battle phase ends$/i.test(c)) return "battleEnd";
  if (/^When this arena'?s battle step starts$/i.test(c)) return "arenaStart";
  if ((m = /^When the (Space|Ground|Character) battle step starts$/i.exec(c))) return "arenaStart" + (m[1] === "Space" ? 0 : m[1] === "Ground" ? 1 : 2);
  if ((m = /^When you complete (this|.+)$/i.exec(c)) && (m[1] === "this" || /^this (Location|Mission|Resource|Equipment)/.test(m[1]) || m[1] === name)) return "complete";
  return null;
}

/** Parse one " | " part of a card's text. */
function parseAbility(raw: string, def: Def): Ability {
  let text = cleanText(raw);
  const name = def.n;
  const base = def.base;
  const isInsert = /^INSERT:\s*/i.test(text);
  text = text.replace(/^INSERT:\s*/i, "");
  if (/^Reserves:/i.test(text)) return { k: "none", src: text };
  // Keywords.
  const kws = parseKeywordList(text);
  if (kws) {
    const keys = Object.keys(kws);
    if (keys.length === 1) return { k: "kw", kw: keys[0], n: kws[keys[0]] };
    return { k: "aura", f: selfFilter(), sp: 0, pw: 0, hp: 0, kw: kws, src: text };
  }
  let m: RegExpExecArray | null;
  if ((m = /^Switch: (.+)$/.exec(text))) {
    // Encoded as an aura whose per-arena grants live in the source string; resolved at stat time.
    const per = m[1].split("/").map((p) => parseGrant(p.trim()) || (p.trim() === "None" ? { sp: 0, pw: 0, hp: 0, kw: null } : null));
    if (per.some((p) => p === null)) return { k: "none", src: text };
    return { k: "kw", kw: "Switch:" + JSON.stringify(per), n: 1 };
  }
  if ((m = /^(Foresight|Forewarning|Bounty|Deploy): (.+)$/.exec(text))) {
    const ctx: ParseCtx = { name, base, tg: [], last: -1, tm: emptyTiming(), ok: true };
    const fx = parseEffects(m[2], ctx);
    if (!ctx.ok || (ctx.tg.length > 0 && (m[1] === "Foresight" || m[1] === "Forewarning"))) return { k: "none", src: text };
    const ev = m[1] === "Deploy" ? "deploy" : m[1].toLowerCase();
    return { k: "trig", ev, tg: ctx.tg, fx, opt: false, src: text };
  }
  if ((m = /^Upkeep: (.+)$/.exec(text))) {
    // Upkeep with a single payable cost becomes a build-step-start trigger of "pay".
    return { k: "kw", kw: "Upkeep:" + m[1], n: 1 };
  }
  if ((m = /^Alternative Cost: (.+)$/.exec(text))) {
    const costs = parseCosts(m[1], name, base);
    if (!costs) return { k: "none", src: text };
    return { k: "kw", kw: "Alt:" + JSON.stringify(costs), n: 1 };
  }
  if ((m = /^Treat (?:this unit|this card|[\w' -]+?) as (?:a |an )?([\w -]+?)\.?$/.exec(text))) {
    const who = /^Treat (.+?) as /.exec(text);
    if (/^Treat (this unit|this card)/.test(text) || text.indexOf("Treat " + base.split(" ")[0]) === 0 || (who && base.indexOf(who[1]) >= 0)) {
      return { k: "treat", sub: parseSubtypes(m[1]) };
    }
  }
  // Activated: cost -> effect (an arrow inside a quoted granted ability does not count).
  const arrow = indexOutsideQuotes(text, "->");
  if (arrow >= 0) {
    const idx = arrow;
    const costText = text.slice(0, idx).trim();
    const effText = text.slice(idx + 2).trim();
    if (/^Enhance:/i.test(costText)) return { k: "none", src: text };
    const cost = parseCosts(costText, name, base);
    if (!cost) return { k: "none", src: text };
    const ctx: ParseCtx = { name, base, tg: [], last: -1, tm: emptyTiming(), ok: true };
    const fx = parseEffects(effText, ctx);
    if (!ctx.ok || fx.length === 0) return { k: "none", src: text };
    const tm = ctx.tm;
    if (!tm.build && !tm.battle && !tm.attack && !tm.prevent && !tm.wouldAttack) {
      // Default for an unrestricted activated ability: any POP of the battle phase.
      tm.battle = true;
      tm.attack = true;
    }
    if (isInsert) {
      // INSERT abilities work from anywhere in the stack; treated as the card's own here.
    }
    return { k: "act", cost, tg: ctx.tg, fx, tm, src: text };
  }
  // Equipment grants.
  if ((m = /^Equipped (.+?) (?:also )?gets (.+)$/.exec(text))) {
    const subj = m[1].toLowerCase().replace(/^unique /, "");
    const sub = subj === "unit" || subj === "character" || subj === "character unit" || subj === "space unit" || subj === "ground unit" ? [] : subj.split(/ or /).length > 1 ? [] : parseSubtypes(subj);
    // Split off quoted granted activated abilities.
    const quoted: string[] = [];
    const plain = m[2].replace(/"([^"]*)"/g, (_all, q: string) => {
      quoted.push(q);
      return "";
    }).replace(/\s*,?\s*and\s*$/, "").replace(/,\s*$/, "").trim();
    const g = plain.length > 0 ? parseGrant(plain) : { sp: 0, pw: 0, hp: 0, kw: null };
    if (!g) return { k: "none", src: text };
    const acts: Ability[] = [];
    for (const q of quoted) {
      const inner = parseAbility(q, def);
      if (inner.k === "none") return { k: "none", src: text };
      acts.push(inner);
    }
    if (subj.split(/ or /).length > 1) {
      return { k: "eq", sub: ["|" + subj.split(/ or /).map((w) => parseSubtypes(w).join(" ")).join("|")], sp: g.sp, pw: g.pw, hp: g.hp, kw: g.kw, acts, src: text };
    }
    return { k: "eq", sub, sp: g.sp, pw: g.pw, hp: g.hp, kw: g.kw, acts, src: text };
  }
  // Pilot: "Starfighter Pilot. The Starfighter gets: - +2 power - Accuracy 1"
  if ((m = /^(?:\[Pilot\] )?([\w ,]+?) Pilot\. The [\w ]+? gets:? (.+)$/.exec(text))) {
    const parts = m[2].split(/\s*[-*]\s*(?=[+A-Z])|\s*-(?=\+)/).map((p) => p.trim()).filter((p) => p.length > 0);
    let sp = 0;
    let pw = 0;
    let hp = 0;
    const kw: KwMap = {};
    for (const p of parts) {
      const g = parseGrant(p.replace(/\.$/, ""));
      if (!g) continue; // a bullet the parser cannot read is skipped; the rest still applies
      sp += g.sp;
      pw += g.pw;
      hp += g.hp;
      if (g.kw) for (const key of Object.keys(g.kw)) kw[key] = (kw[key] || 0) + g.kw[key];
    }
    return { k: "pilot", sub: parseSubtypes(m[1].replace(/ and /g, " ")), sp, pw, hp, kw: Object.keys(kw).length ? kw : null, src: text };
  }
  // Cost reductions: "Each of your Stormtroopers costs 1 less build counter to deploy."
  if ((m = /^Each of your (.+?) costs? (\d+) (?:less|fewer) build (?:counters?|points?) to (?:deploy|complete|build)\.?$/i.exec(text))) {
    const f = emptyFilter();
    f.side = "me";
    if (!parseNoun(m[1], f)) return { k: "none", src: text };
    return { k: "cred", f, n: parseInt(m[2], 10), src: text };
  }
  // "Each of your opponent's Characters loses Stealth."
  if ((m = /^(Each of your .+?|Each unit .+?) loses (.+?)\.?$/.exec(text))) {
    const ref = parseTarget(m[1], name, base);
    const k0 = parseKeywordList(m[2]);
    if (!ref || ref.kind !== "all" || !k0) return { k: "none", src: text };
    const kw: KwMap = {};
    for (const key of Object.keys(k0)) kw[key] = -999;
    return { k: "aura", f: ref.f, sp: 0, pw: 0, hp: 0, kw, src: text };
  }
  // Conditional grants: "As long as C, S gets G." / "S gets G as long as C."
  {
    let cm2 = /^As long as (.+?), (.+?) gets? (.+?)\.?$/.exec(text);
    let condText = "";
    let subj = "";
    let grant = "";
    if (cm2) {
      condText = cm2[1];
      subj = cm2[2];
      grant = cm2[3];
    } else if ((cm2 = /^(.+?) gets? (.+?) as long as (.+?)\.?$/.exec(text))) {
      subj = cm2[1];
      grant = cm2[2];
      condText = cm2[3];
    }
    if (cm2) {
      const cond = parseCond(condText, name, base);
      const quoted: string[] = [];
      const plain = grant.replace(/"([^"]*)"/g, (_all, q: string) => {
        quoted.push(q);
        return "";
      }).replace(/\s*,?\s*and\s*$/, "").replace(/,\s*$/, "").trim();
      const g = plain.length > 0 ? parseGrant(plain) : { sp: 0, pw: 0, hp: 0, kw: null };
      const ref = parseTarget(subj, name, base);
      if (!cond || !g || !ref || (ref.kind !== "self" && ref.kind !== "all")) return { k: "none", src: text };
      const acts: Ability[] = [];
      for (const q of quoted) {
        const inner = parseAbility(q.replace(/\.$/, ""), def);
        if (inner.k === "none") return { k: "none", src: text };
        acts.push(inner);
      }
      const aura: Ability & { k: "aura" } = { k: "aura", f: ref.kind === "self" ? selfFilter() : ref.f, sp: g.sp, pw: g.pw, hp: g.hp, kw: g.kw, cond, src: text };
      if (acts.length > 0) aura.acts = acts; // never an `acts: undefined` key: it would not survive a JSON round trip
      return aura;
    }
  }
  // Yoda: "+1 power and +1 health, each of your Jedi Padawans gets."
  if ((m = /^(.+), (each of your .+?) gets\.?$/.exec(text))) {
    return parseAbility(m[2].charAt(0).toUpperCase() + m[2].slice(1) + " gets " + m[1].replace(/,$/, ""), def);
  }
  if (/^Damage from this unit(?:'s attacks?)? can'?t be prevented\.?$/i.test(text)) return { k: "kw", kw: "Ferocity", n: 1 };
  if ((m = /^Damage from ([A-Z][\w' -]+?) can'?t be prevented\.?$/.exec(text)) && base.indexOf(m[1]) >= 0) return { k: "kw", kw: "Ferocity", n: 1 };
  if ((m = /^(?:This unit|[A-Z][\w' -]+?) (?:can|may) attack (?:units?|a unit) in the (Space|Ground|Character) arena(?: instead of (?:a unit|units) in the (?:Space|Ground|Character) arena)?\.?$/.exec(text))) {
    return { k: "kw", kw: "AttackAr" + (m[1] === "Space" ? 0 : m[1] === "Ground" ? 1 : 2), n: 1 };
  }
  if (/^This unit doesn'?t count toward controlling (?:any|an|the) arenas?\.?$/i.test(text)) return { k: "kw", kw: "NoControl", n: 1 };
  if (/^This unit can'?t attack or be attacked\.?$/i.test(text)) return { k: "kw", kw: "Untouchable", n: 1 };
  if (/^This unit can'?t attack\.?$/i.test(text)) return { k: "kw", kw: "NoAttack", n: 1 };
  if (/^This unit can'?t retreat\.?$/i.test(text) || /^[A-Z][\w' -]+ can'?t retreat\.?$/.test(text)) return { k: "kw", kw: "NoRetreat", n: 1 };
  if ((m = /^This unit gets -(\d+) power for each damage counter on it\.?$/i.exec(text))) return { k: "kw", kw: "Wounded", n: parseInt(m[1], 10) };
  if (/^(?:The )?[A-Z][\w' -]+ can have an extra Pilot\.?$/.test(text) || /^This unit can have an extra Pilot\.?$/i.test(text)) return { k: "kw", kw: "ExtraPilot", n: 1 };
  if ((m = /^Reduced Cost (\d+): If (.+?)\.?$/.exec(text))) {
    const cond = parseCond(m[2], name, base) || parseCond(m[2].replace(/^(?:a|an) /i, "you have a "), name, base);
    if (!cond) return { k: "none", src: text };
    return { k: "kw", kw: "Reduced:" + JSON.stringify({ n: parseInt(m[1], 10), cond }), n: 1 };
  }
  if ((m = /^Each of your Battle cards costs? (\d+) less Force to play\.?$/i.exec(text))) return { k: "kw", kw: "BattleDiscount", n: parseInt(m[1], 10) };
  // A plain, permanent grant to the card itself: "This unit gets +1 power and Accuracy 1."
  if ((m = /^(This unit|[A-Z][\w' -]+?) gets (.+?)\.?$/.exec(text)) && !/until|for this attack|this turn|when|whenever|if /i.test(m[2])) {
    const ref = parseTarget(m[1], name, base);
    const g = parseGrant(m[2]);
    if (ref && ref.kind === "self" && g) return { k: "aura", f: selfFilter(), sp: g.sp, pw: g.pw, hp: g.hp, kw: g.kw, src: text };
  }
  // Auras: "Each of your other Jedi in this arena gets +1 power."
  if ((m = /^(Each of your .+?|Each unit .+?) gets? (.+?)\.?$/.exec(text)) && !/until|for this attack|as long as|when|while/i.test(m[2].replace(/"[^"]*"/g, ""))) {
    const ref = parseTarget(m[1], name, base);
    const quoted: string[] = [];
    const plain = m[2].replace(/"([^"]*)"/g, (_all, q: string) => {
      quoted.push(q);
      return "";
    }).replace(/\s*,?\s*and\s*$/, "").replace(/,\s*$/, "").trim();
    const g = plain.length > 0 ? parseGrant(plain) : { sp: 0, pw: 0, hp: 0, kw: null };
    if (!ref || ref.kind !== "all" || !g) return { k: "none", src: text };
    if (quoted.length === 0) return { k: "aura", f: ref.f, sp: g.sp, pw: g.pw, hp: g.hp, kw: g.kw, src: text };
    const acts: Ability[] = [];
    for (const q of quoted) {
      const inner = parseAbility(q, def);
      if (inner.k === "none") return { k: "none", src: text };
      acts.push(inner);
    }
    return { k: "aura", f: ref.f, sp: g.sp, pw: g.pw, hp: g.hp, kw: g.kw, acts, src: text };
  }
  // Triggers: "When you deploy this unit, draw a card."
  if ((m = /^(When(?:ever)? [^,]+), (?:you may )?(.+)$/.exec(text))) {
    const ev = parseTriggerEvent(m[1], name, base);
    if (!ev) return { k: "none", src: text };
    const ctx: ParseCtx = { name, base, tg: [], last: -1, tm: emptyTiming(), ok: true };
    const fx = parseEffects(m[2].charAt(0).toUpperCase() + m[2].slice(1), ctx);
    if (!ctx.ok || fx.length === 0) return { k: "none", src: text };
    return { k: "trig", ev, tg: ctx.tg, fx, opt: /you may/.test(text), src: text };
  }
  // A Mission's or Battle card's plain effect (no cost): resolved when it is completed/played.
  if ((def.ty & (T_MISSION | T_BATTLE)) !== 0 && /^Choose one: /i.test(text)) {
    const first = text.replace(/^Choose one: /i, "").split(/,? or |, /)[0].replace(/\.$/, "");
    return parseAbility(first.charAt(0).toUpperCase() + first.slice(1) + ".", def);
  }
  if ((def.ty & (T_MISSION | T_BATTLE)) !== 0) {
    const ctx: ParseCtx = { name, base, tg: [], last: -1, tm: emptyTiming(), ok: true };
    const fx = parseEffects(text, ctx);
    if (ctx.ok && fx.length > 0) {
      if ((def.ty & T_BATTLE) !== 0) {
        const tm = ctx.tm;
        if (!tm.build && !tm.battle && !tm.attack && !tm.prevent) {
          tm.battle = true;
          tm.attack = true;
        }
        return { k: "act", cost: [], tg: ctx.tg, fx, tm, src: text };
      }
      return { k: "trig", ev: "complete", tg: ctx.tg, fx, opt: false, src: text };
    }
  }
  return { k: "none", src: text };
}

/** Index of `needle` outside double-quoted spans, or -1. */
function indexOutsideQuotes(text: string, needle: string): number {
  let q = false;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text.charAt(i);
    if (ch === "\"") q = !q;
    else if (!q && text.startsWith(needle, i)) return i;
  }
  return -1;
}

function selfFilter(): Filter {
  const f = emptyFilter();
  f.side = "me";
  f.ar = -2; // marker: the source itself
  return f;
}

function num(v: unknown): number {
  if (typeof v === "number") return isFinite(v) ? v : 0;
  if (typeof v === "string") {
    const n = parseInt(v, 10);
    return isNaN(n) ? 0 : n;
  }
  return 0;
}

/** Raw catalogue row as it arrives in the setup (or from the catalogue file). */
interface RawCard {
  name: string;
  type: string;
  subtype?: string;
  side?: string;
  cost?: string | number | null;
  speed?: string | number | null;
  power?: string | number | null;
  health?: string | number | null;
  text?: string;
  set?: string;
  /** The catalogue id the table spawns faces from (ignored by the rules). */
  cid?: string;
}

function parseDef(raw: RawCard): Def {
  const name = cleanText(String(raw.name || "?"));
  const ver = /\(([A-Z]{1,2})\)/.exec(name);
  const base = name.replace(/\s*\([^)]*\)/g, "").trim();
  const subtype = cleanText(String(raw.subtype || ""));
  const ty = parseTypeFlags(String(raw.type || ""), subtype);
  const costStr = String(raw.cost === null || raw.cost === undefined ? "" : raw.cost);
  const def: Def = {
    n: name,
    base,
    uq: !!ver,
    ty,
    sub: parseSubtypes(subtype),
    side: String(raw.side || "N").charAt(0).toUpperCase(),
    cost: num(raw.cost),
    costX: /X/.test(costStr),
    sp: num(raw.speed),
    pw: num(raw.power),
    hp: num(raw.health),
    ab: [],
    kw: {},
    unk: 0,
    txt: cleanText(String(raw.text || ""))
  };
  if (def.txt.length > 0) {
    const parts: string[] = [];
    for (const part0 of def.txt.split(/\s*\|\s*/)) {
      // "cost -> Choose one: A. Or: B." becomes one playable option per choice.
      const cm3 = /^(.*->\s*)Choose one: (.+)$/.exec(part0);
      if (cm3) {
        for (const opt of cm3[2].split(/\s*\bOr:\s*/)) if (opt.trim().length > 0) parts.push(cm3[1] + opt.trim());
        continue;
      }
      const tm3 = /^(When[^,]+, )(?:you may )?choose one: (.+?)(?:\s*\bOr:.*)?$/.exec(part0);
      if (tm3) {
        parts.push(tm3[1] + tm3[2].trim());
        continue;
      }
      parts.push(part0);
    }
    for (const part of parts) {
      if (part.trim().length === 0) continue;
      const ab = parseAbility(part, def);
      if (ab.k === "none") def.unk += 1;
      if (ab.k === "kw" && ab.kw.indexOf(":") < 0) def.kw[ab.kw] = (def.kw[ab.kw] || 0) + ab.n;
      if (ab.k === "aura" && ab.f.ar === -2 && ab.kw && !ab.cond) {
        // Static keyword lists on the card itself also feed the fast keyword lookups (Hidden Cost...).
        for (const key of Object.keys(ab.kw)) if (key === "Hidden Cost") def.kw[key] = (def.kw[key] || 0) + ab.kw[key];
      }
      if (ab.k === "treat") for (const w of ab.sub) if (def.sub.indexOf(w) < 0) def.sub.push(w);
      def.ab.push(ab);
    }
  }
  return def;
}

// ============================================================================================
// Star Wars TCG rules kernel - part 2: card access, derived stats, zones, damage.
// ============================================================================================

const MAX_TURNS = 40;
const MAX_PLIES = 6000;
const START_BUILD = 30;
const HAND_SIZE = 7;

function card(s: State, id: number): Card {
  return s.cards[id] as Card;
}

function defOf(s: State, id: number): Def {
  return s.defs[(s.cards[id] as Card).d];
}

function other(seat: number): number {
  return 1 - seat;
}

function isUnitDef(d: Def): boolean {
  return (d.ty & T_UNIT) !== 0 && (d.ty & (T_EQUIP | T_LOCATION | T_BATTLE | T_MISSION | T_RESOURCE | T_EVENT)) === 0;
}

/** Every live instance id. */
function allIds(s: State): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.cards.length; i += 1) if (s.cards[i]) out.push(i);
  return out;
}

/** Face-up units in arena `ar` (any controller when seat < 0). */
function unitsIn(s: State, ar: number, seat: number): number[] {
  const z = zoneOfArena(ar);
  const out: number[] = [];
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (!c || c.z !== z || c.fd) continue;
    if (seat >= 0 && c.c !== seat) continue;
    if (!isUnitDef(s.defs[c.d])) continue;
    out.push(i);
  }
  return out;
}

function inArena(c: Card): boolean {
  return c.z === "a0" || c.z === "a1" || c.z === "a2";
}

function handOf(s: State, seat: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (c && c.z === "hand" && c.o === seat) out.push(i);
  }
  return out;
}

function zoneIds(s: State, seat: number, z: Zone): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (c && c.z === z && c.c === seat) out.push(i);
  }
  return out;
}

/** Cards under a host (stacked versions, equipment, pilots). */
function attached(s: State, host: number, ut: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (c && c.z === "under" && c.h === host && (ut < 0 || c.ut === ut)) out.push(i);
  }
  return out;
}

function log(s: State, line: string): void {
  if (s.log.length < 60) s.log.push(line);
}

function nameOf(s: State, id: number): string {
  return id >= 0 && s.cards[id] ? defOf(s, id).n : "?";
}

// --------------------------------------------------------------------------------------------
// Derived stats
// --------------------------------------------------------------------------------------------

interface Stats {
  sp: number;
  pw: number;
  hp: number;
  kw: KwMap;
}

function addKw(into: KwMap, kw: KwMap | null): void {
  if (!kw) return;
  for (const k of Object.keys(kw)) into[k] = (into[k] || 0) + kw[k];
}

function hasSub(d: Def, words: string[]): boolean {
  if (words.length === 0) return true;
  if (words.length === 1 && words[0].charAt(0) === "|") {
    // "Jedi or Sith": any alternative's words all present.
    const alts = words[0].slice(1).split("|");
    for (const alt of alts) {
      const ws = alt.split(" ").filter((w) => w.length > 0);
      if (hasSub(d, ws)) return true;
    }
    return false;
  }
  for (const w of words) {
    let found = false;
    for (const sw of d.sub) {
      if (sw === w || sw === w + "s" || sw + "s" === w) {
        found = true;
        break;
      }
    }
    if (!found && d.base.toLowerCase().indexOf(w) < 0) return false;
  }
  return true;
}

/** Does unit `id` match `f`, seen from controller `ctrl` with source `src`? */
function matches(s: State, id: number, f: Filter, ctrl: number, src: number): boolean {
  const c = s.cards[id];
  if (!c || c.fd) return false;
  const d = s.defs[c.d];
  if (f.ar === -2) return id === src;
  if (!isUnitDef(d)) return false;
  if (!inArena(c)) return false;
  if (f.side === "me" && c.c !== ctrl) return false;
  if (f.side === "opp" && c.c === ctrl) return false;
  if (f.other && id === src) return false;
  const ar = arenaOfZone(c.z);
  if (f.ar >= 0 && f.ar <= 2 && ar !== f.ar) return false;
  if (f.ar === 3) {
    const sc = src >= 0 ? s.cards[src] : null;
    if (!sc || arenaOfZone(sc.z) !== ar) return false;
  }
  if (f.ty !== 0 && f.ty !== T_UNIT) {
    if ((arenaTypeFlag(ar) & f.ty) === 0) return false;
  }
  if (f.tapped === 0 && c.tp) return false;
  if (f.tapped === 1 && !c.tp) return false;
  if (f.damaged && c.dm === 0) return false;
  if (f.unique && !d.uq) return false;
  return hasSub(d, f.sub);
}

/** Is a static ability's condition true for source `src` controlled by `ctrl`? */
function evalCond(s: State, cond: Cond, src: number, ctrl: number): boolean {
  const c = s.cards[src];
  if (!c) return false;
  switch (cond.c) {
    case "selfAr":
      return arenaOfZone(c.z) === cond.ar;
    case "pilot":
      return attached(s, src, 3).length > 0;
    case "undamaged":
      return c.dm === 0;
    case "damaged":
      return c.dm > 0;
    case "force":
      return s.P[ctrl].force >= cond.n;
    case "have":
      return candidates(s, cond.f, ctrl, src).length > 0;
    case "loc":
      for (let i = 0; i < s.cards.length; i += 1) {
        const o = s.cards[i];
        if (!o || !inArena(o) || (s.defs[o.d].ty & T_LOCATION) === 0) continue;
        if (cond.ar >= 0 && arenaOfZone(o.z) !== cond.ar) continue;
        if (hasSub(s.defs[o.d], cond.sub)) return true;
      }
      return false;
    case "name":
      for (let i = 0; i < s.cards.length; i += 1) {
        const o = s.cards[i];
        if (!o || o.fd || !inArena(o)) continue;
        if (cond.ar >= 0 && arenaOfZone(o.z) !== cond.ar) continue;
        if (s.defs[o.d].base.toLowerCase().indexOf(cond.n) >= 0) return true;
      }
      return false;
    default:
      return false;
  }
}

/** Effective speed/power/health/keywords of a unit (a face-up card in any zone). */
function stats(s: State, id: number): Stats {
  const c = card(s, id);
  const d = s.defs[c.d];
  const out: Stats = { sp: d.sp, pw: d.pw, hp: d.hp, kw: {} };
  addKw(out.kw, d.kw);
  const ar = arenaOfZone(c.z);
  // Unique stack bonus.
  const stack = attached(s, id, 1);
  out.sp += 10 * stack.length;
  out.pw += stack.length;
  out.hp += stack.length;
  for (const b of c.bf) {
    out.sp += b.sp;
    out.pw += b.pw;
    out.hp += b.hp;
    addKw(out.kw, b.kw);
  }
  // Printed conditional/switch abilities on the card itself.
  for (const ab of d.ab) {
    if (ab.k === "aura" && ab.f.ar === -2 && (!ab.cond || evalCond(s, ab.cond, id, c.c))) {
      out.sp += ab.sp;
      out.pw += ab.pw;
      out.hp += ab.hp;
      addKw(out.kw, ab.kw);
    }
    if (ab.k === "kw" && ab.kw.indexOf("Switch:") === 0 && ar >= 0) {
      const per = JSON.parse(ab.kw.slice(7)) as ({ sp: number; pw: number; hp: number; kw: KwMap | null } | null)[];
      // The n-th listed arena type gets the n-th grant.
      const order: number[] = [];
      if ((d.ty & T_SPACE) !== 0) order.push(0);
      if ((d.ty & T_GROUND) !== 0) order.push(1);
      if ((d.ty & T_CHAR) !== 0) order.push(2);
      const g = per[order.indexOf(ar)];
      if (g) {
        out.sp += g.sp;
        out.pw += g.pw;
        out.hp += g.hp;
        addKw(out.kw, g.kw);
      }
    }
  }
  // Equipment and pilots attached to it.
  for (const eid of attached(s, id, -1)) {
    const e = card(s, eid);
    if (e.ut === 1) continue;
    const ed = s.defs[e.d];
    if (e.tp && e.ut === 2) continue; // tapped Equipment grants nothing
    for (const ab of ed.ab) {
      if (e.ut === 2 && ab.k === "eq" && (ab.sub.length === 0 || hasSub(d, ab.sub))) {
        out.sp += ab.sp;
        out.pw += ab.pw;
        out.hp += ab.hp;
        addKw(out.kw, ab.kw);
      }
      if (e.ut === 3 && ab.k === "pilot") {
        out.sp += ab.sp;
        out.pw += ab.pw;
        out.hp += ab.hp;
        addKw(out.kw, ab.kw);
      }
    }
  }
  if (ar >= 0) {
    // Auras, Inspiration and Intimidation from units and Locations in play.
    for (let i = 0; i < s.cards.length; i += 1) {
      const sc = s.cards[i];
      if (!sc || sc.fd || !inArena(sc)) continue;
      const sd = s.defs[sc.d];
      const sar = arenaOfZone(sc.z);
      if (i !== id && sar === ar && sc.c === c.c && sd.kw["Inspiration"] && sd.uq && isUnitDef(sd)) {
        out.sp += 10;
        out.pw += 1;
        out.hp += 1;
      }
      for (const ab of sd.ab) {
        if (ab.k !== "aura" || ab.f.ar === -2) continue;
        const isLocation = (sd.ty & T_LOCATION) !== 0;
        if (!isLocation && !isUnitDef(sd)) continue;
        if (ab.cond && !evalCond(s, ab.cond, i, sc.c)) continue;
        // A Location's "this arena" is its own arena.
        if (matches(s, id, ab.f, sc.c, i)) {
          out.sp += ab.sp;
          out.pw += ab.pw;
          out.hp += ab.hp;
          addKw(out.kw, ab.kw);
        }
      }
    }
    if (out.kw["Intimidation"] && d.uq) {
      const n = unitsIn(s, ar, other(c.c)).length;
      out.sp += 10 * n;
      out.pw += n;
      out.hp += n;
    }
    if (out.kw["Resilience"] && c.dm >= Math.abs(out.kw["Resilience"])) out.pw += out.kw["Resilience"];
    if (out.kw["Wounded"]) out.pw -= out.kw["Wounded"] * c.dm;
  }
  for (const key of Object.keys(out.kw)) if (out.kw[key] <= -500) delete out.kw[key];
  if (out.sp < 0) out.sp = 0;
  if (out.pw < 0) out.pw = 0;
  return out;
}

/** Activated abilities a card can use: its own `act`s plus those granted by Equipment, auras and pilots. */
function actsOf(s: State, id: number): { ab: Ability & { k: "act" }; from: number; idx: number }[] {
  const c = card(s, id);
  const d = s.defs[c.d];
  const out: { ab: Ability & { k: "act" }; from: number; idx: number }[] = [];
  d.ab.forEach((ab, idx) => {
    if (ab.k === "act" && !(ab.fx.length === 1 && ab.fx[0].e === "equip")) out.push({ ab, from: id, idx });
    if (ab.k === "aura" && ab.f.ar === -2 && ab.acts && (!ab.cond || evalCond(s, ab.cond, id, c.c))) {
      ab.acts.forEach((inner, j) => {
        if (inner.k === "act") out.push({ ab: inner, from: id, idx: 100 + idx * 8 + j });
      });
    }
  });
  if (isUnitDef(d)) {
    for (const eid of attached(s, id, 2)) {
      const e = card(s, eid);
      if (e.tp) continue;
      s.defs[e.d].ab.forEach((ab, idx) => {
        if (ab.k === "eq" && (ab.sub.length === 0 || hasSub(d, ab.sub))) {
          ab.acts.forEach((inner, j) => {
            if (inner.k === "act") out.push({ ab: inner, from: eid, idx: 100 + idx * 8 + j });
          });
        }
      });
    }
    if (inArena(c)) {
      for (let i = 0; i < s.cards.length; i += 1) {
        const sc = s.cards[i];
        if (!sc || sc.fd || !inArena(sc)) continue;
        s.defs[sc.d].ab.forEach((ab, idx) => {
          if (ab.k === "aura" && ab.acts && ab.f.ar !== -2 && matches(s, id, ab.f, sc.c, i)) {
            ab.acts.forEach((inner, j) => {
              if (inner.k === "act") out.push({ ab: inner, from: i, idx: 100 + idx * 8 + j });
            });
          }
        });
      }
    }
  }
  return out;
}

function remainingHealth(s: State, id: number): number {
  return stats(s, id).hp - card(s, id).dm;
}

/** Does a card definition match a filter's type and subtype (for costs and searches)? */
function defMatches(d: Def, ty: number, sub: string[], uniqueOnly: boolean): boolean {
  if (ty !== 0) {
    if (ty === T_UNIT) {
      if (!isUnitDef(d)) return false;
    } else if ((ty & (T_LOCATION | T_MISSION | T_EQUIP | T_BATTLE | T_RESOURCE)) !== 0) {
      if ((d.ty & ty) === 0) return false;
    } else if (!isUnitDef(d) || (d.ty & ty) === 0) return false;
  }
  if (uniqueOnly && !d.uq) return false;
  return hasSub(d, sub);
}

/** Build-cost reduction for `d` from its owner's cards in play ("costs N less build counter to deploy"). */
function costReduction(s: State, seat: number, d: Def): number {
  let n = 0;
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (!c || c.fd || c.c !== seat) continue;
    if (!inArena(c) && c.z !== "res" && c.z !== "evt") continue;
    for (const ab of s.defs[c.d].ab) if (ab.k === "cred" && defMatches(d, ab.f.ty, ab.f.sub, ab.f.unique)) n += ab.n;
  }
  return n;
}

/** Total build cost of a unit stack (head card + 1 per card under it). */
function stackCost(s: State, id: number): number {
  return defOf(s, id).cost + attached(s, id, 1).length;
}

// --------------------------------------------------------------------------------------------
// Moving cards
// --------------------------------------------------------------------------------------------

function draw(s: State, seat: number, n: number): void {
  const p = s.P[seat];
  for (let k = 0; k < n; k += 1) {
    const id = p.deck.shift();
    if (id === undefined) return; // out of cards: keep playing
    const c = card(s, id);
    c.z = "hand";
    c.fd = false;
  }
}

function resetCard(c: Card): void {
  c.fd = false;
  c.bc = 0;
  c.dm = 0;
  c.tp = false;
  c.rc = 0;
  c.h = -1;
  c.ut = 0;
  c.mv = false;
  c.eqT = false;
  c.ua = 0;
  c.bf = [];
}

/** Put a card into its owner's discard pile, taking what was attached with it. A Subordinate goes back to its supply. */
function toDiscard(s: State, id: number, normal: boolean): void {
  const c = card(s, id);
  const isSubordinate = (s.defs[c.d].ty & T_SUBORD) !== 0;
  for (const aid of attached(s, id, -1)) {
    const a = card(s, aid);
    if (a.ut === 2 && normal) {
      // Equipment returns to its controller's build zone when the unit is discarded normally.
      resetCard(a);
      a.z = "build";
      a.c = a.o;
    } else {
      resetCard(a);
      a.z = "disc";
      a.c = a.o;
    }
  }
  resetCard(c);
  c.z = isSubordinate ? "sup" : "disc";
  c.c = c.o;
}

/** Remove a destroyed unit; fire its discard trigger. */
function discardUnit(s: State, id: number, killer: number): void {
  const c = card(s, id);
  if (!inArena(c)) return;
  log(s, nameOf(s, id) + " is discarded.");
  const d = defOf(s, id);
  queueTriggers(s, id, "discarded");
  toDiscard(s, id, true);
  void d;
  if (killer >= 0 && s.cards[killer] && inArena(card(s, killer))) {
    // Bounty: resolved immediately for the killer's controller.
    for (let i = 0; i < defOf(s, killer).ab.length; i += 1) {
      const ab = defOf(s, killer).ab[i];
      if (ab.k === "trig" && ab.ev === "bounty") s.q.push({ src: killer, ab: i, ctrl: card(s, killer).c });
    }
  }
}

/** Damage counters on a unit; discards it when they reach its health. */
function addDamage(s: State, id: number, n: number, killer: number): void {
  if (n <= 0 || !s.cards[id]) return;
  const c = card(s, id);
  if (!inArena(c)) return;
  c.dm += n;
  if (c.dm >= stats(s, id).hp) discardUnit(s, id, killer);
}

/** Roll `n` dice of damage at `target`: each 4+ (5+ against Armor) is one damage. */
function diceOfDamage(s: State, target: number, n: number, src: number): number {
  if (!s.cards[target] || !inArena(card(s, target))) return 0;
  const armor = stats(s, target).kw["Armor"] ? 5 : 4;
  let hits = 0;
  for (let i = 0; i < n; i += 1) if (rollDie(s) >= armor) hits += 1;
  log(s, nameOf(s, src) + " does " + n + " dice of damage to " + nameOf(s, target) + ": " + hits + ".");
  addDamage(s, target, hits, src);
  return hits;
}

function untapAll(s: State): void {
  for (const c of s.cards) {
    if (!c) continue;
    if (c.z === "under" && c.ut === 1) continue;
    c.tp = false;
  }
}

/** Units that count toward controlling an arena (not those that "don't count toward controlling"). */
function controllers(s: State, ar: number, seat: number): number {
  let n = 0;
  for (const u of unitsIn(s, ar, seat)) if (!defOf(s, u).kw["NoControl"]) n += 1;
  return n;
}

function controlsArena(s: State, seat: number, ar: number): boolean {
  return controllers(s, ar, seat) > 0 && controllers(s, ar, other(seat)) === 0;
}

function arenasControlled(s: State, seat: number): number {
  let n = 0;
  for (let ar = 0; ar < 3; ar += 1) if (controlsArena(s, seat, ar)) n += 1;
  return n;
}

/** Clear durations at the end of an attack ("A"), a battle ("B") or the turn ("T"). */
function expire(s: State, u: "A" | "B" | "T"): void {
  for (const c of s.cards) {
    if (!c) continue;
    if (c.bf.length === 0) continue;
    c.bf = c.bf.filter((b) => {
      if (u === "A") return b.u !== "A";
      if (u === "B") return b.u !== "A" && b.u !== "B";
      return b.u === "G";
    });
  }
}

// ============================================================================================
// Star Wars TCG rules kernel - part 3: costs, targets, effects and triggers.
// ============================================================================================

type ActEntry = { ab: Ability & { k: "act" }; from: number; idx: number };

/**
 * Activated abilities may be played as often as their cost can be paid (cards that may not say
 * "Play only once per turn"). Two exceptions are limited to once per turn here: abilities marked
 * so, and abilities whose cost spends nothing (they could otherwise be repeated forever).
 */
function limitedPerTurn(ab: Ability & { k: "act" }, c: Card): boolean {
  if (ab.tm.once) return true;
  if (c.z === "res") return true;
  const spends = ab.cost.some((x) => (x.c === "force" && x.n > 0) || x.c === "forceX" || (x.c === "bp" && x.n > 0) || x.c === "tap" || x.c === "discard" || x.c === "remCtr" || x.c === "dmgSelf" || x.c === "tapOther" || x.c === "retreatSelf");
  return !spends;
}

/** Instances a filter can target right now. */
function candidates(s: State, f: Filter, ctrl: number, src: number): number[] {
  const out: number[] = [];
  for (let i = 0; i < s.cards.length; i += 1) if (s.cards[i] && matches(s, i, f, ctrl, src)) out.push(i);
  return out;
}

/** Cards a "discard N cards from your hand" cost takes: the cheapest first (never `except`). */
function discardPicks(s: State, seat: number, n: number, except: number): number[] {
  const hand = handOf(s, seat).filter((id) => id !== except);
  hand.sort((a, b) => defOf(s, a).cost - defOf(s, b).cost || a - b);
  return hand.slice(0, n);
}

function xFor(s: State, ctrl: number, fx: Eff[], costs?: Cost[]): number {
  let force = s.P[ctrl].force;
  if (costs) for (const c of costs) if (c.c === "forceX") force = Math.min(force, c.cap);
  for (const e of fx) {
    if (e.e === "prevent" && e.x && s.atk) return Math.max(0, Math.min(force, s.atk.pending - s.atk.prevented, 15));
  }
  return Math.min(force, 15);
}

/** Force a Battle card played from hand costs less ("Each of your Battle cards costs 1 less Force"). */
function battleDiscount(s: State, ctrl: number, src: number): number {
  if (src < 0 || card(s, src).z !== "hand" || (defOf(s, src).ty & T_BATTLE) === 0) return 0;
  let n = 0;
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (!c || c.fd || c.c !== ctrl || (!inArena(c) && c.z !== "res" && c.z !== "evt")) continue;
    n += s.defs[c.d].kw["BattleDiscount"] || 0;
  }
  return n;
}

function canPay(s: State, src: number, ctrl: number, costs: Cost[], x: number, except: number): boolean {
  const p = s.P[ctrl];
  let force = -battleDiscount(s, ctrl, src);
  let bp = 0;
  for (const c of costs) {
    if (c.c === "force") force += c.n;
    else if (c.c === "forceX") force += x;
    else if (c.c === "bp") bp += c.n;
    else if (c.c === "tap") {
      if (src < 0 || card(s, src).tp) return false;
    } else if (c.c === "discard") {
      if (discardPicks(s, ctrl, c.n, except).length < c.n) return false;
    } else if (c.c === "remCtr") {
      const r = resourceOf(s, ctrl, src);
      if (r < 0 || card(s, r).rc < c.n) return false;
    } else if (c.c === "addCtr") {
      if (resourceOf(s, ctrl, src) < 0) return false;
    } else if (c.c === "tapOther") {
      if (candidates(s, c.f, ctrl, src).filter((id) => !card(s, id).tp && id !== src).length === 0) return false;
    } else if (c.c === "retreatSelf") {
      if (src < 0 || !inArena(card(s, src))) return false;
    }
  }
  return p.force >= Math.max(0, force) && p.bp >= bp;
}

/** The Resource a counter cost uses: the source itself when it is one, else the seat's Resource. */
function resourceOf(s: State, seat: number, src: number): number {
  if (src >= 0 && card(s, src).z === "res") return src;
  const r = zoneIds(s, seat, "res");
  return r.length > 0 ? r[0] : -1;
}

function pay(s: State, src: number, ctrl: number, costs: Cost[], x: number, except: number): void {
  const p = s.P[ctrl];
  let discount = battleDiscount(s, ctrl, src);
  for (const c of costs) {
    if (c.c === "force") {
      const off = Math.min(discount, c.n);
      discount -= off;
      p.force -= c.n - off;
    } else if (c.c === "forceX") p.force -= x;
    else if (c.c === "bp") p.bp -= c.n;
    else if (c.c === "tap") card(s, src).tp = true;
    else if (c.c === "discard") for (const id of discardPicks(s, ctrl, c.n, except)) toDiscard(s, id, false);
    else if (c.c === "remCtr") card(s, resourceOf(s, ctrl, src)).rc -= c.n;
    else if (c.c === "addCtr") card(s, resourceOf(s, ctrl, src)).rc += c.n;
    else if (c.c === "dmgSelf") addDamage(s, src, c.n, -1);
    else if (c.c === "tapOther") {
      const pick = candidates(s, c.f, ctrl, src).filter((id) => !card(s, id).tp && id !== src);
      pick.sort((a, b) => stats(s, a).pw - stats(s, b).pw);
      if (pick.length > 0) card(s, pick[0]).tp = true;
    } else if (c.c === "retreatSelf") retreatUnit(s, src);
  }
  if (p.force < 0) p.force = 0;
}

function retreatUnit(s: State, id: number): void {
  const c = card(s, id);
  if (!inArena(c)) return;
  if ((defOf(s, id).ty & T_SUBORD) !== 0) {
    // A Subordinate that leaves its arena returns to its owner's supply.
    toDiscard(s, id, true);
    return;
  }
  c.z = "build";
  for (const pid of attached(s, id, 3)) card(s, pid).tp = true;
}

/** Can the attack's defender legally become `id` (Intercept / Redirect)? */
function canBeAttacked(s: State, id: number, attacker: number): boolean {
  const c = card(s, id);
  if (!inArena(c)) return false;
  const k = stats(s, id).kw;
  if (k["Untouchable"]) return false;
  if (k["Stealth"] && !c.tp && c.dm === 0) return false;
  void attacker;
  return true;
}

/** Is this prevention / attack-time keyword effect relevant to the attack in progress? */
/** True when the effect certainly changes nothing now: removing damage where there is none. */
function fxPointless(s: State, e: Eff, src: number, ctrl: number, tg: Filter[]): boolean {
  if (e.e !== "counters" || !e.remove) return false;
  if (e.who.w === "self") return src < 0 || !s.cards[src] || card(s, src).dm <= 0;
  if (e.who.w === "tgt") {
    const f = tg[e.who.i];
    return !!f && !candidates(s, f, ctrl, src).some((id) => card(s, id).dm > 0);
  }
  return false;
}

function fxRelevant(s: State, e: Eff, src: number, ctrl: number, tg: Filter[]): boolean {
  const atk = s.atk;
  if (e.e === "prevent") {
    if (!atk || atk.stage !== 1 || atk.pending - atk.prevented <= 0) return false;
    if (!s.cards[atk.d] || card(s, atk.d).c !== ctrl) return false;
    if (e.kind === "protect") {
      if (tg.length > 0) return matches(s, atk.d, tg[0], ctrl, src);
      return src >= 0 && src !== atk.d && arenaOfZone(card(s, src).z) === atk.ar;
    }
    if (e.kind === "all" && tg.length > 0) return matches(s, atk.d, tg[0], ctrl, src);
    return src === atk.d;
  }
  if (e.e === "retaliate") {
    return !!atk && atk.stage === 0 && src === atk.d && s.cards[atk.a] !== null && arenaOfZone(card(s, atk.a).z) === atk.ar;
  }
  if (e.e === "intercept") {
    if (!atk || atk.stage !== 0 || src === atk.d || !s.cards[atk.d]) return false;
    if (card(s, atk.d).c !== ctrl || arenaOfZone(card(s, src).z) !== atk.ar) return false;
    if (stats(s, atk.a).kw["Precision"]) return false;
    return canBeAttacked(s, src, atk.a);
  }
  if (e.e === "redirect") {
    if (!atk || atk.stage !== 0 || src !== atk.d || stats(s, atk.a).kw["Precision"]) return false;
    return unitsIn(s, atk.ar, ctrl).some((u) => u !== src && canBeAttacked(s, u, atk.a));
  }
  if (e.e === "disrupt") {
    if (e.what === "attack") return !!atk && atk.stage === 0 && card(s, atk.a).c !== ctrl;
    return disruptMatches(s, e.what, ctrl);
  }
  if (e.e === "ambush" || e.e === "meditate" || e.e === "equip" || e.e === "attackAgain") return false;
  return true;
}

/** Does a "Disrupt a …" of kind `what` (played by `ctrl`) answer the play now on the stack? */
function disruptMatches(s: State, what: string, ctrl: number): boolean {
  const head = s.stk.length > 0 ? s.stk[s.stk.length - 1] : null;
  if (!head || head.off || head.ctrl === ctrl) return false;
  if (what === "battle") return head.battle;
  if (what === "act") return !head.battle;
  if (what === "any") return true;
  if (what === "dsr") return head.dsr;
  return false;
}

/** Can `seat` disrupt the play on the stack right now? */
function canRespond(s: State, seat: number): boolean {
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (!c || c.fd) continue;
    const ok = (c.z === "hand" && c.o === seat && (s.defs[c.d].ty & T_BATTLE) !== 0) || (c.z !== "hand" && c.c === seat && (inArena(c) || c.z === "res"));
    if (!ok) continue;
    for (const ent of actsOf(s, i)) if (actUsable(s, ent, seat, "dsr", i)) return true;
  }
  return false;
}

/**
 * May `ctrl` use activated ability `ent` right now, in POP/step `when`?
 * `when`: "build" | "gen" | "atk" | "prev" | "would".
 */
function actUsable(s: State, ent: ActEntry, ctrl: number, when: string, holder: number): boolean {
  const ab = ent.ab;
  const tm = ab.tm;
  // A disrupt chance admits only effects that disrupt the play on the stack (whatever their timing).
  if (when === "dsr") {
    if (!ab.fx.some((e) => e.e === "disrupt" && e.what !== "attack")) return false;
  } else if (s.stk.length > 0) return false;
  else if (when === "build" && !tm.build) return false;
  if (when === "gen" && !tm.battle) return false;
  if (when === "atk" && !tm.attack) return false;
  if (when === "prev" && !tm.prevent) return false;
  if (when === "would" && !tm.wouldAttack) return false;
  if ((when === "gen" || when === "atk" || when === "prev") && tm.arena >= 0 && tm.arena !== s.arena) return false;
  if (when === "atk" && !s.atk) return false;
  const c = holder >= 0 ? card(s, holder) : null;
  if (c && isUnitDef(defOf(s, holder)) && !inArena(c) && c.z !== "hand") return false;
  if (c && c.z !== "hand" && c.c !== ctrl) return false;
  // Once per turn per ability (keyword prevention/attack effects: once per attack instead).
  const bit = 1 << (ent.idx % 30);
  const perAttack = ab.fx.some((e) => e.e === "prevent" || e.e === "retaliate" || e.e === "intercept" || e.e === "redirect");
  if (perAttack) {
    if (s.atk && s.atk.usedPrev.indexOf(holder * 1000 + ent.idx) >= 0) return false;
  } else if (c && c.z !== "hand" && (c.ua & bit) !== 0 && limitedPerTurn(ab, c)) return false;
  // A Resource: one activated effect per turn, whichever it is.
  if (c && c.z === "res" && c.ua !== 0) return false;
  for (const e of ab.fx) if (!fxRelevant(s, e, holder, ctrl, ab.tg)) return false;
  // An ability that would do nothing at all is not offered (a bot used to tap every unit in its
  // build step to "remove up to 2 damage counters" from units with none).
  if (ab.fx.length > 0 && ab.fx.every((e) => fxPointless(s, e, holder, ctrl, ab.tg))) return false;
  // Targets: every required target needs at least one candidate (prevent targets are implicit).
  const needsTargets = !ab.fx.some((e) => e.e === "prevent");
  if (needsTargets) for (const f of ab.tg) if (candidates(s, f, ctrl, holder).length === 0) return false;
  const x = xFor(s, ctrl, ab.fx, ab.cost);
  if (ab.fx.some((e) => (e.e === "prevent" && e.x) || (e.e === "damage" && e.n < 0)) && x <= 0) return false;
  return canPay(s, holder, ctrl, ab.cost, x, c && c.z === "hand" ? holder : -1);
}

function resolveWho(s: State, who: Who, src: number, ctrl: number, tg: number[]): number[] {
  if (who.w === "self") return src >= 0 && s.cards[src] && inArena(card(s, src)) ? [src] : [];
  if (who.w === "tgt") {
    const id = tg[who.i];
    return id !== undefined && id >= 0 && s.cards[id] && inArena(card(s, id)) ? [id] : [];
  }
  if (who.w === "attacker") return s.atk && s.cards[s.atk.a] && inArena(card(s, s.atk.a)) ? [s.atk.a] : [];
  if (who.w === "defender") return s.atk && s.cards[s.atk.d] && inArena(card(s, s.atk.d)) ? [s.atk.d] : [];
  if (who.w === "equipped") {
    const h = src >= 0 ? card(s, src).h : -1;
    return h >= 0 ? [h] : [];
  }
  return candidates(s, who.f, ctrl, src);
}

/** Apply an ability's effects. `src` is the unit (or card) the ability belongs to. */
function resolveFx(s: State, src: number, ctrl: number, fx: Eff[], tg: number[], x: number): void {
  const opp = other(ctrl);
  for (const e of fx) {
    if (e.e === "stat") {
      const u = e.u === "A" && !s.atk ? "T" : e.u;
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) {
        card(s, id).bf.push({ sp: e.sp, pw: e.pw, hp: e.hp, u, kw: e.kw });
      }
    } else if (e.e === "prevent") {
      const atk = s.atk;
      if (!atk) continue;
      const n = Math.min(e.x ? x : e.n, atk.pending - atk.prevented);
      if (n <= 0) continue;
      atk.prevented += n;
      log(s, nameOf(s, src) + " prevents " + n + " damage.");
      if (e.kind === "deflect") {
        const foes = unitsIn(s, atk.ar, opp);
        const to = foes.indexOf(atk.a) >= 0 ? atk.a : foes.length > 0 ? foes[0] : -1;
        if (to >= 0) atk.deflect.push({ from: src, n: n * 1000 + to });
      } else if (e.kind === "absorb") {
        card(s, src).bf.push({ sp: 0, pw: n, hp: 0, u: "T", kw: null });
      } else if (e.kind === "persuade") {
        if (s.cards[atk.a]) card(s, atk.a).bf.push({ sp: 0, pw: -n, hp: 0, u: "T", kw: null });
      }
    } else if (e.e === "retaliate") {
      if (s.atk) s.atk.retaliate.push({ u: src, n: e.n });
    } else if (e.e === "intercept" || e.e === "redirect") {
      const atk = s.atk;
      if (!atk) continue;
      if (e.e === "intercept") atk.d = src;
      else {
        const opts = unitsIn(s, atk.ar, ctrl).filter((u) => u !== src && canBeAttacked(s, u, atk.a));
        opts.sort((a, b) => remainingHealth(s, b) - remainingHealth(s, a));
        if (opts.length > 0) atk.d = opts[0];
      }
      log(s, nameOf(s, atk.d) + " is now the defending unit.");
    } else if (e.e === "draw") draw(s, ctrl, e.n);
    else if (e.e === "force") {
      const p = s.P[e.opp ? opp : ctrl];
      p.force = Math.max(0, p.force + e.n);
    } else if (e.e === "bp") {
      const p = s.P[e.opp ? opp : ctrl];
      p.bp = Math.max(0, p.bp + e.n);
    } else if (e.e === "damage") {
      const n = e.n < 0 ? x : e.n;
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) {
        if (e.dice) diceOfDamage(s, id, n, src);
        else addDamage(s, id, n, src);
      }
    } else if (e.e === "counters") {
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) {
        if (e.remove) card(s, id).dm = Math.max(0, card(s, id).dm - e.n);
        else addDamage(s, id, e.n, -1);
      }
    } else if (e.e === "tap") {
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) card(s, id).tp = true;
    } else if (e.e === "untap") {
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) card(s, id).tp = false;
    } else if (e.e === "retreat") {
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) retreatUnit(s, id);
    } else if (e.e === "discardUnit") {
      for (const id of resolveWho(s, e.who, src, ctrl, tg)) discardUnit(s, id, -1);
    } else if (e.e === "disrupt") {
      if (e.what === "attack" && s.atk) {
        s.atk.disrupted = true;
        log(s, "The attack is disrupted.");
      } else if (e.what !== "attack" && disruptMatches(s, e.what, ctrl)) {
        const head = s.stk[s.stk.length - 1];
        if (e.unless > 0 && s.P[head.ctrl].force >= e.unless) {
          s.P[head.ctrl].force -= e.unless;
          log(s, s.seats[head.ctrl] + " pays " + e.unless + " Force, so " + nameOf(s, head.holder) + " is not disrupted.");
        } else {
          head.off = true;
          log(s, nameOf(s, head.holder) + " is disrupted.");
        }
      }
    } else if (e.e === "oppDiscard") {
      for (let k = 0; k < e.n; k += 1) {
        const hand = handOf(s, opp);
        if (hand.length === 0) break;
        const pick = e.random ? hand[Math.floor(rngNext(s) * hand.length)] : discardPicks(s, opp, 1, -1)[0];
        toDiscard(s, pick, false);
      }
    } else if (e.e === "mill") {
      const p = s.P[e.opp ? opp : ctrl];
      for (let k = 0; k < e.n; k += 1) {
        const id = p.deck.shift();
        if (id === undefined) break;
        toDiscard(s, id, false);
      }
    } else if (e.e === "addCtr") {
      const r = resourceOf(s, ctrl, src);
      if (r >= 0) card(s, r).rc += e.n;
    } else if (e.e === "take") {
      // Subordinates come from the controller's supply; with none there, nothing happens.
      let left = e.n;
      for (let i = 0; i < s.cards.length && left > 0; i += 1) {
        const c = s.cards[i];
        if (!c || c.z !== "sup" || c.o !== ctrl) continue;
        const d = s.defs[c.d];
        if ((d.ty & T_SUBORD) === 0) continue;
        const nm = d.base.toLowerCase();
        if (nm !== e.nm && nm.indexOf(e.nm) < 0 && e.nm.indexOf(nm) < 0) continue;
        const allowed = arenasFor(d);
        let ar = -1;
        for (const want of e.ars) {
          const w = want === 3 && src >= 0 ? arenaOfZone(card(s, src).z) : want;
          if (w >= 0 && allowed.indexOf(w) >= 0) {
            ar = w;
            break;
          }
        }
        if (ar < 0) ar = allowed.length > 0 ? allowed[0] : -1;
        if (ar < 0) continue;
        resetCard(c);
        c.c = ctrl;
        c.z = zoneOfArena(ar);
        c.dep = s.turn;
        log(s, s.seats[ctrl] + " takes " + d.n + " into the " + ARENA_NAMES[ar] + " arena.");
        ambush(s, i);
        left -= 1;
      }
    } else if (e.e === "selfDiscard") {
      for (const id of discardPicks(s, ctrl, e.n, -1)) toDiscard(s, id, false);
    } else if (e.e === "search") {
      // The card is taken automatically: the highest-cost match (a simplification of "choose").
      const p = s.P[ctrl];
      const pool = e.from === "deck" ? p.deck.slice() : zoneIds(s, ctrl, "disc").filter((id) => card(s, id).o === ctrl);
      const hits = pool.filter((id) => defMatches(defOf(s, id), e.ty, e.sub, e.uq));
      hits.sort((a, b) => defOf(s, b).cost - defOf(s, a).cost || a - b);
      for (const id of hits.slice(0, Math.max(1, e.n))) {
        if (e.from === "deck") p.deck = p.deck.filter((x) => x !== id);
        const c = card(s, id);
        resetCard(c);
        c.c = ctrl;
        if (e.dest === "build") {
          c.z = "build";
          c.fd = true;
          c.bc = e.bc;
        } else c.z = "hand";
        log(s, s.seats[ctrl] + " takes " + defOf(s, id).n + " from " + (e.from === "deck" ? "the deck" : "the discard pile") + ".");
      }
      if (e.from === "deck") shuffleIds(s, p.deck);
    }
  }
}

/** Queue a card's own triggers for `ev`. */
function queueTriggers(s: State, id: number, ev: string): void {
  const c = s.cards[id];
  if (!c) return;
  const d = s.defs[c.d];
  for (let i = 0; i < d.ab.length; i += 1) {
    const ab = d.ab[i];
    if (ab.k === "trig" && ab.ev === ev) s.q.push({ src: id, ab: i, ctrl: c.c });
  }
}

/** Queue every in-play card's triggers for a table-wide event, Dark Side's first. */
function queueGlobal(s: State, ev: string, onlySeat: number): void {
  for (const seat of [s.dark, other(s.dark)]) {
    if (onlySeat >= 0 && seat !== onlySeat) continue;
    for (let i = 0; i < s.cards.length; i += 1) {
      const c = s.cards[i];
      if (!c || c.fd || c.c !== seat) continue;
      if (!inArena(c) && c.z !== "res" && c.z !== "evt") continue;
      const d = s.defs[c.d];
      for (let k = 0; k < d.ab.length; k += 1) {
        const ab = d.ab[k];
        if (ab.k !== "trig") continue;
        if (ab.ev === ev || (ev.indexOf("arenaStart") === 0 && ab.ev === "arenaStart" && arenaOfZone(c.z) === s.arena)) {
          s.q.push({ src: i, ab: k, ctrl: c.c });
        }
      }
    }
  }
}

/**
 * Resolve queued triggers until one needs a decision. Returns true when the game now waits for
 * a target choice.
 */
function processQueue(s: State): boolean {
  while (s.q.length > 0) {
    const t = s.q.shift() as { src: number; ab: number; ctrl: number };
    const c = s.cards[t.src];
    if (!c) continue;
    if (t.ab === -1) {
      // A completed Mission leaves play once its effects have resolved.
      if (c.z === "aside") toDiscard(s, t.src, false);
      continue;
    }
    const ab = s.defs[c.d].ab[t.ab];
    if (!ab || ab.k !== "trig") continue;
    if (ab.tg.length > 0) {
      const ok = ab.tg.every((f) => candidates(s, f, t.ctrl, t.src).length > 0);
      if (!ok) continue;
      s.choice = { src: t.src, ab: t.ab, ctrl: t.ctrl, need: ab.tg.slice(), got: [], then: "trig", x: 0, back: s.ph === "target" ? "build" : s.ph, bw: s.who };
      s.ph = "target";
      s.who = t.ctrl;
      return true;
    }
    log(s, nameOf(s, t.src) + ": " + ab.src);
    resolveFx(s, t.src, t.ctrl, ab.fx, [], 0);
    if (s.win >= 0) return false;
  }
  return false;
}

// ============================================================================================
// Star Wars TCG rules kernel - part 4: turn flow, legal moves and apply.
//
// The game is a state machine. `s.ph` is the decision being waited for; when it is "flow",
// `advance` runs the automatic step named by `s.fl` until the next real decision. A POP chance
// in which the player to act has nothing playable is passed automatically.
// ============================================================================================

/** Cell <-> instance, from one seat's side of the table. */
interface CellMap {
  cellOf: number[];
  instOf: number[];
}

/**
 * The cell layout, from `me`'s side: my hand (20), my build zone (12), my three arenas (10 each,
 * Locations included), my Resource and Event (2); then the opponent's build zone (12), arenas (3 x 10)
 * and Resource/Event (2); then 20 "choice" cells - the Events in my supply or the Resources in my deck
 * while I choose one, otherwise my attached Equipment and Pilots. Each block is in instance order.
 * A card with no cell (a block overflowed) cannot be acted on.
 */
function cellMapOf(s: State, me: number): CellMap {
  const cellOf: number[] = [];
  for (let i = 0; i < SLOTS; i += 1) cellOf.push(-1);
  const instOf: number[] = [];
  for (let i = 0; i < CELLS; i += 1) instOf.push(-1);
  const put = (base: number, n: number, ids: number[]) => {
    ids.sort((x, y) => x - y);
    for (let k = 0; k < ids.length && k < n; k += 1) {
      cellOf[ids[k]] = base + k;
      instOf[base + k] = ids[k];
    }
  };
  const opp = other(me);
  const where = (seat: number, test: (c: Card) => boolean) => {
    const out: number[] = [];
    for (let i = 0; i < s.cards.length; i += 1) {
      const c = s.cards[i];
      if (c && c.c === seat && test(c)) out.push(i);
    }
    return out;
  };
  put(0, 20, handOf(s, me));
  put(20, 12, where(me, (c) => c.z === "build"));
  for (let ar = 0; ar < 3; ar += 1) put(32 + ar * 10, 10, where(me, (c) => c.z === zoneOfArena(ar)));
  put(62, 2, where(me, (c) => c.z === "res" || c.z === "evt"));
  put(64, 12, where(opp, (c) => c.z === "build"));
  for (let ar = 0; ar < 3; ar += 1) put(76 + ar * 10, 10, where(opp, (c) => c.z === zoneOfArena(ar)));
  put(106, 2, where(opp, (c) => c.z === "res" || c.z === "evt"));
  let choice: number[];
  if (s.ph === "event" && s.who === me) choice = zoneIds(s, me, "sup").filter((id) => (defOf(s, id).ty & T_EVENT) !== 0);
  else if (s.ph === "resource" && s.who === me) choice = resourceChoices(s, me);
  else choice = where(me, (c) => c.z === "under" && (c.ut === 2 || c.ut === 3));
  put(108, 20, choice);
  return { cellOf, instOf };
}

/** One Resource card per name from the deck: what the Pull Resource step offers. */
function resourceChoices(s: State, seat: number): number[] {
  const seen: { [n: string]: boolean } = {};
  const out: number[] = [];
  for (const id of s.P[seat].deck) {
    const d = defOf(s, id);
    if ((d.ty & T_RESOURCE) === 0 || seen[d.n]) continue;
    seen[d.n] = true;
    out.push(id);
  }
  return out;
}

/** The instance a move's cell names in this state (-1 for none). */
function cellInst(s: State, r: number): number {
  return r >= 0 ? cellMapOf(s, s.who).instOf[r] : -1;
}

/** The cell map `legalMoves` is building moves against (set at its start). */
let LM: CellMap = { cellOf: [], instOf: [] };

/** A card move; r = -2 marks a card with no cell (dropped before `legalMoves` returns). */
function cm(s: State, id: number, a: number): Move {
  const r = LM.cellOf[id];
  return { r: r === undefined || r < 0 ? -2 : r, a };
}

function gm(a: number): Move {
  return { r: -1, a };
}

function hasCost(d: Def): boolean {
  return (d.ty & (T_BATTLE | T_EVENT | T_SUBORD)) === 0;
}

/** Arenas a unit (or Location) may go to. */
function arenasFor(d: Def): number[] {
  const out: number[] = [];
  if ((d.ty & T_SPACE) !== 0) out.push(0);
  if ((d.ty & T_GROUND) !== 0) out.push(1);
  if ((d.ty & T_CHAR) !== 0) out.push(2);
  return out;
}

/** The same-name unique unit this card would stack onto, -1 when none, -2 when it may not enter play. */
function stackTarget(s: State, id: number): number {
  const c = card(s, id);
  const d = s.defs[c.d];
  if (!d.uq || !isUnitDef(d)) return -1;
  for (let i = 0; i < s.cards.length; i += 1) {
    const o = s.cards[i];
    if (!o || i === id || o.fd || o.c !== c.o) continue;
    if (!inArena(o) && o.z !== "build") continue;
    const od = s.defs[o.d];
    if (!od.uq || od.base !== d.base || !isUnitDef(od)) continue;
    const under = attached(s, i, 1);
    if (under.length >= 3) return -2;
    if (od.n === d.n || under.some((u) => defOf(s, u).n === d.n)) return -2;
    return i;
  }
  return -1;
}

/** Build points still needed to complete `id` (hand card or partially built card). */
function completeCost(s: State, id: number): number {
  const c = card(s, id);
  const d = s.defs[c.d];
  let cost = d.cost;
  const st = stackTarget(s, id);
  if (st >= 0) cost = 1 + Math.max(0, d.cost - defOf(s, st).cost);
  else {
    for (const ab of d.ab) {
      if (ab.k !== "kw" || ab.kw.indexOf("Reduced:") !== 0) continue;
      const rc = JSON.parse(ab.kw.slice(8)) as { n: number; cond: Cond };
      if (evalCond(s, rc.cond, id, c.o) && rc.n < cost) cost = rc.n;
    }
    cost = Math.max(0, cost - costReduction(s, c.o, d));
  }
  return Math.max(0, cost - (c.fd ? c.bc : 0));
}

/** Alternative Cost costs printed on a card, or null. */
function altCost(d: Def): Cost[] | null {
  for (const ab of d.ab) if (ab.k === "kw" && ab.kw.indexOf("Alt:") === 0) return JSON.parse(ab.kw.slice(4)) as Cost[];
  return null;
}

/** How `seat` can pay to complete `id` now: build points, Hidden Cost (Force), Alternative Cost, or not at all. */
function completionPayment(s: State, id: number, seat: number): "bp" | "hidden" | "alt" | null {
  const c = card(s, id);
  const d = s.defs[c.d];
  const need = completeCost(s, id);
  if (need <= s.P[seat].bp) return "bp";
  const hc = d.kw["Hidden Cost"] || 0;
  if (c.fd && hc > 0 && c.bc >= Math.min(hc, d.cost) && s.P[seat].force >= need && isUnitDef(d)) return "hidden";
  const alt = altCost(d);
  if (alt && stackTarget(s, id) === -1 && canPay(s, id, seat, alt, 0, id)) return "alt";
  return null;
}

/** How many Pilots a unit may carry. */
function pilotCapacity(d: Def): number {
  const sub = " " + d.sub.join(" ") + " ";
  for (const w of ["army", "capital ship", "cruiser", "fleet", "fortification", "station"]) if (sub.indexOf(" " + w + " ") >= 0) return 3;
  for (const w of ["gunship", "patrol ship", "squad", "squadron", "transport", "walker"]) if (sub.indexOf(" " + w + " ") >= 0) return 2;
  return 1;
}

function pilotAbility(d: Def): (Ability & { k: "pilot" }) | null {
  for (const ab of d.ab) if (ab.k === "pilot") return ab;
  return null;
}

/** May Pilot `pid` pilot unit `u`? */
function canPilot(s: State, pid: number, u: number): boolean {
  const pd = defOf(s, pid);
  const ab = pilotAbility(pd);
  const uc = card(s, u);
  const ud = defOf(s, u);
  if (!ab || !inArena(uc) || uc.c !== card(s, pid).c || u === pid) return false;
  if (arenaOfZone(uc.z) === AR_CHAR) return false;
  if (ud.sub.indexOf("droid") >= 0) return false;
  if (attached(s, u, 3).length >= pilotCapacity(ud) + (ud.kw["ExtraPilot"] ? 1 : 0)) return false;
  const words = ab.sub.filter((w) => w !== "and" && w !== "or");
  return words.some((w) => hasSub(ud, [w]));
}

function locationIn(s: State, ar: number): number {
  const z = zoneOfArena(ar);
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (c && c.z === z && (s.defs[c.d].ty & T_LOCATION) !== 0) return i;
  }
  return -1;
}

/** Where a completed card may go: arenas 0..2, 3 = build zone / no arena. */
function completeTargets(s: State, id: number): number[] {
  const c = card(s, id);
  const d = s.defs[c.d];
  if (isUnitDef(d)) {
    const st = stackTarget(s, id);
    if (st === -2) return [];
    if (st >= 0) {
      const z = card(s, st).z;
      return [z === "build" ? 3 : arenaOfZone(z)];
    }
    return arenasFor(d).concat([3]);
  }
  if ((d.ty & T_LOCATION) !== 0) {
    return arenasFor(d).filter((ar) => {
      const old = locationIn(s, ar);
      return old < 0 || defOf(s, old).cost <= d.cost;
    });
  }
  if ((d.ty & T_RESOURCE) !== 0) return zoneIds(s, c.o, "res").length === 0 ? [3] : [];
  if ((d.ty & (T_MISSION | T_EQUIP)) !== 0) return [3];
  return [];
}

function actionForTarget(t: number): number {
  return t === 3 ? A_DEPLOY_BZ : A_DEPLOY0 + t;
}

/** Equipment `eq` may attach to unit `u`? */
function canEquip(s: State, eq: number, u: number): boolean {
  const e = card(s, eq);
  const uc = card(s, u);
  if (!inArena(uc) || uc.c !== e.c) return false;
  const ar = arenaOfZone(uc.z);
  const ed = s.defs[e.d];
  if ((ed.ty & T_UNIT) !== 0 && (ed.ty & arenaTypeFlag(ar)) === 0) return false;
  if (e.h === u) return false;
  // Skills and Traits: one copy per unit; uniques: one per unit too.
  for (const other0 of attached(s, u, 2)) if (defOf(s, other0).n === ed.n) return false;
  return true;
}

/** Can `sel` (Equipment or a Pilot) be attached to anything right now? */
function hasAttachTarget(s: State, sel: number, seat: number): boolean {
  const isPilot = pilotAbility(defOf(s, sel)) !== null && isUnitDef(defOf(s, sel));
  if (!isPilot) {
    const cost = equipCost(s, sel);
    if (!cost || !canPay(s, sel, seat, cost, 0, -1)) return false;
  }
  for (let ar = 0; ar < 3; ar += 1) {
    for (const u of unitsIn(s, ar, seat)) {
      if (isPilot ? canPilot(s, sel, u) : canEquip(s, sel, u)) return true;
    }
  }
  return false;
}

function equipCost(s: State, eq: number): Cost[] | null {
  for (const ab of defOf(s, eq).ab) if (ab.k === "act" && ab.fx.length === 1 && ab.fx[0].e === "equip") return ab.cost;
  return null;
}

// --------------------------------------------------------------------------------------------
// Legal moves
// --------------------------------------------------------------------------------------------

function popWhen(kind: string): string {
  return kind === "atk" ? "atk" : kind === "prev" ? "prev" : kind === "dsr" ? "dsr" : "gen";
}

/** Activated abilities and Battle cards `seat` could play in POP/step `when`. */
function playableActs(s: State, seat: number, when: string): Move[] {
  const out: Move[] = [];
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (!c || c.fd) continue;
    const d = s.defs[c.d];
    let holderOk = false;
    if (c.z === "hand" && c.o === seat && (d.ty & T_BATTLE) !== 0 && when !== "build" && when !== "would") holderOk = true;
    if (c.z === "hand" && c.o === seat && (d.ty & T_BATTLE) !== 0 && when === "dsr") holderOk = true;
    if (c.z !== "hand" && c.c === seat && (inArena(c) || c.z === "res")) holderOk = true;
    if (!holderOk) continue;
    const acts = actsOf(s, i);
    for (let k = 0; k < acts.length && k < 4; k += 1) {
      if (actUsable(s, acts[k], seat, when, i)) out.push(cm(s, i, A_ACT0 + k));
    }
  }
  return out;
}

function hiddenCostMoves(s: State, seat: number): Move[] {
  const out: Move[] = [];
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (!c || c.z !== "build" || !c.fd || c.o !== seat) continue;
    const d = s.defs[c.d];
    const hc = d.kw["Hidden Cost"] || 0;
    if (hc <= 0 || !isUnitDef(d)) continue;
    const need = completeCost(s, i);
    if (c.bc < Math.min(hc, d.cost) || s.P[seat].force < need) continue;
    for (const t of completeTargets(s, i)) if (t < 3) out.push(cm(s, i, actionForTarget(t)));
  }
  return out;
}

function attackTargets(s: State, a: number): number[] {
  const ac = card(s, a);
  const ar = arenaOfZone(ac.z);
  const k = stats(s, a).kw;
  const arenas = [ar];
  if (k["Bombard"] && ar !== AR_GROUND) arenas.push(AR_GROUND);
  if (k["Ion Cannon"] && ar !== AR_SPACE) arenas.push(AR_SPACE);
  if (k["Barrage"] && ar !== AR_CHAR) arenas.push(AR_CHAR);
  for (let x = 0; x < 3; x += 1) if (k["AttackAr" + x] && arenas.indexOf(x) < 0) arenas.push(x);
  const out: number[] = [];
  for (const x of arenas) for (const u of unitsIn(s, x, other(ac.c))) if (canBeAttacked(s, u, a)) out.push(u);
  return out;
}

function legalMoves(s: State): Move[] {
  LM = cellMapOf(s, s.who);
  return legalMovesRaw(s).filter((m) => m.r !== -2);
}

function legalMovesRaw(s: State): Move[] {
  const seat = s.who;
  const p = s.P[seat];
  const out: Move[] = [];
  switch (s.ph) {
    case "roll": {
      for (let v = 1; v <= 6; v += 1) out.push(gm(G_X0 + v));
      break;
    }
    case "event": {
      for (const id of zoneIds(s, seat, "sup")) if ((defOf(s, id).ty & T_EVENT) !== 0) out.push(cm(s, id, A_TARGET));
      out.push(gm(G_PASS));
      break;
    }
    case "resource": {
      for (const id of resourceChoices(s, seat)) out.push(cm(s, id, A_TARGET));
      out.push(gm(G_PASS));
      break;
    }
    case "mulligan": {
      for (const id of handOf(s, seat)) if (!isUnitDef(defOf(s, id))) out.push(cm(s, id, A_TARGET));
      if (zoneIds(s, seat, "aside").length > 0) {
        out.push(gm(G_MULL_DISCARD));
        out.push(gm(G_MULL_RETURN));
      } else out.push(gm(G_PASS));
      break;
    }
    case "setup": {
      const hasRes = zoneIds(s, seat, "res").length > 0;
      for (const id of handOf(s, seat)) {
        const d = defOf(s, id);
        if (isUnitDef(d) && d.cost <= p.bp && stackTarget(s, id) === -1) {
          for (const ar of arenasFor(d)) out.push(cm(s, id, A_DEPLOY0 + ar));
        }
        if ((d.ty & T_RESOURCE) !== 0 && !hasRes && d.cost <= p.bp) out.push(cm(s, id, A_DEPLOY_BZ));
        if (hasCost(d) && p.bp >= 1) out.push(cm(s, id, A_BUILD));
      }
      out.push(gm(G_PASS));
      break;
    }
    case "build": {
      if (s.sel >= 0) {
        if (pilotAbility(defOf(s, s.sel)) && isUnitDef(defOf(s, s.sel))) {
          for (let ar = 0; ar < 2; ar += 1) for (const u of unitsIn(s, ar, seat)) if (canPilot(s, s.sel, u)) out.push(cm(s, u, A_EQUIP));
        } else {
          const cost = equipCost(s, s.sel) || [];
          if (canPay(s, s.sel, seat, cost, 0, -1)) {
            for (let ar = 0; ar < 3; ar += 1) for (const u of unitsIn(s, ar, seat)) if (canEquip(s, s.sel, u)) out.push(cm(s, u, A_EQUIP));
          }
        }
        if (out.length === 0) out.push(gm(G_NO));
        break;
      }
      for (let i = 0; i < s.cards.length; i += 1) {
        const c = s.cards[i];
        if (!c || c.o !== seat && c.c !== seat) continue;
        const d = s.defs[c.d];
        if (c.z === "hand" && c.o === seat && hasCost(d)) {
          if (p.bp >= 1 && !d.costX) out.push(cm(s, i, A_BUILD));
          if (completionPayment(s, i, seat)) for (const t of completeTargets(s, i)) out.push(cm(s, i, actionForTarget(t)));
        } else if (c.z === "build" && c.fd && c.o === seat) {
          if (p.bp >= 1 && c.bc < d.cost) out.push(cm(s, i, A_BUILD));
          if (completionPayment(s, i, seat)) for (const t of completeTargets(s, i)) out.push(cm(s, i, actionForTarget(t)));
        } else if (c.z === "build" && !c.fd && c.c === seat) {
          if (isUnitDef(d)) for (const ar of arenasFor(d)) out.push(cm(s, i, A_MOVE0 + ar));
          if ((d.ty & T_EQUIP) !== 0 && !c.eqT && hasAttachTarget(s, i, seat)) out.push(cm(s, i, A_EQUIP));
          if (isUnitDef(d) && pilotAbility(d) && !c.mv && hasAttachTarget(s, i, seat)) out.push(cm(s, i, A_EQUIP));
        } else if (inArena(c) && c.c === seat && isUnitDef(d) && !c.mv) {
          const cur = arenaOfZone(c.z);
          for (const ar of arenasFor(d)) if (ar !== cur) out.push(cm(s, i, A_MOVE0 + ar));
          if (pilotAbility(d) && hasAttachTarget(s, i, seat)) out.push(cm(s, i, A_EQUIP));
        } else if (c.z === "under" && c.ut === 2 && c.c === seat && !c.eqT && hasAttachTarget(s, i, seat)) {
          out.push(cm(s, i, A_EQUIP));
        } else if (c.z === "under" && c.ut === 3 && c.c === seat && !c.mv) {
          out.push(cm(s, i, A_MOVE0 + AR_CHAR));
        }
      }
      for (const m of playableActs(s, seat, "build")) out.push(m);
      out.push(gm(G_PASS));
      break;
    }
    case "retreat": {
      for (let ar = 0; ar < 3; ar += 1) for (const u of unitsIn(s, ar, seat)) if (!card(s, u).tp && !defOf(s, u).kw["NoRetreat"]) out.push(cm(s, u, A_RETREAT));
      out.push(gm(G_PASS));
      break;
    }
    case "pop": {
      const kind = (s.pop as Pop).kind;
      for (const m of playableActs(s, seat, popWhen(kind))) out.push(m);
      if (kind === "gen" || kind === "astart" || kind === "aend") for (const m of hiddenCostMoves(s, seat)) out.push(m);
      out.push(gm(G_PASS));
      break;
    }
    case "choose-attacker": {
      for (const u of attackerChoices(s)) out.push(cm(s, u, A_ATTACK));
      break;
    }
    case "attack-target":
    case "double": {
      for (const u of attackTargets(s, s.sel)) out.push(cm(s, u, A_ATTACK));
      if (s.ph === "attack-target") {
        const acts = actsOf(s, s.sel);
        for (let k = 0; k < acts.length && k < 4; k += 1) if (actUsable(s, acts[k], seat, "would", s.sel)) out.push(cm(s, s.sel, A_ACT0 + k));
        out.push(gm(G_SKIP_ATTACK));
      } else out.push(gm(G_NO));
      break;
    }
    case "target": {
      const ch = s.choice as Choice;
      const f = ch.need[ch.got.length];
      for (const id of candidates(s, f, ch.ctrl, ch.src)) if (ch.got.indexOf(id) < 0) out.push(cm(s, id, A_TARGET));
      // A started play is committed (it is only offered when it has a target): no free cancel, which
      // would also let a player loop forever. An optional trigger may still be declined.
      const t = ch.then === "trig" ? (defOf(s, ch.src).ab[ch.ab] as Ability) : null;
      if ((t && t.k === "trig" && t.opt) || out.length === 0) out.push(gm(G_NO));
      break;
    }
    default:
      break;
  }
  return out;
}

// --------------------------------------------------------------------------------------------
// Attacks
// --------------------------------------------------------------------------------------------

/** Untapped units in the current arena that have not attacked, fastest first. */
function attackerPool(s: State): number[] {
  const out: number[] = [];
  for (const u of unitsIn(s, s.arena, -1)) {
    const c = card(s, u);
    if (c.tp || s.attacked.indexOf(u) >= 0) continue;
    const k = stats(s, u).kw;
    if (k["Untouchable"] || k["NoAttack"]) continue;
    out.push(u);
  }
  return out;
}

/** The units that may attack next: highest speed, Dark Side first on ties. */
function attackerChoices(s: State): number[] {
  const pool = attackerPool(s);
  if (pool.length === 0) return [];
  let best = -1;
  for (const u of pool) best = Math.max(best, stats(s, u).sp);
  const fastest = pool.filter((u) => stats(s, u).sp === best);
  const darkOnes = fastest.filter((u) => card(s, u).c === s.dark);
  return darkOnes.length > 0 ? darkOnes : fastest;
}

function declareAttack(s: State, a: number, d: number): void {
  const ac = card(s, a);
  ac.tp = true;
  if (s.attacked.indexOf(a) < 0) s.attacked.push(a);
  s.atk = {
    a, d, ar: arenaOfZone(card(s, d).z), pw: 0, shields: 0, hits: 0, dice: [], pending: 0, prevented: 0,
    deflect: [], retaliate: [], disrupted: false, persuade: 0, absorbTo: [], usedPrev: [], stage: 0
  };
  log(s, nameOf(s, a) + " attacks " + nameOf(s, d) + ".");
  queueTriggers(s, a, "attacks");
  queueTriggers(s, d, "attacked");
  s.fl = "atkPop";
  s.ph = "flow";
}

function expectedHits(dice: number, need: number): number {
  return Math.round((dice * Math.max(0, 7 - need)) / 6);
}

/** The number of dice the attack in progress rolls. */
function attackPower(s: State): number {
  const atk = s.atk as Attack;
  const a = atk.a;
  const as = stats(s, a);
  const ds = stats(s, atk.d);
  let power = as.pw;
  if (atk.ar !== arenaOfZone(card(s, a).z) && !as.kw["AttackAr" + atk.ar]) {
    const x = atk.ar === AR_GROUND ? as.kw["Bombard"] : atk.ar === AR_SPACE ? as.kw["Ion Cannon"] : as.kw["Barrage"];
    power = (x || 0) + (as.pw - defOf(s, a).pw);
  }
  power += atk.pw - (ds.kw["Shields"] || 0);
  return power < 0 ? 0 : power;
}

/**
 * Physical dice: stop in a "roll" phase until the table has fed in `n` faces (one move per die).
 * Rerolls and extra dice (Lucky, Fury, dice of damage) still come from the seeded RNG.
 */
function waitForDice(s: State, n: number, roller: number, why: string): boolean {
  if (!s.pd || n <= 0 || s.dq.length >= n) return false;
  s.ph = "roll";
  s.who = roller;
  s.rollN = n;
  s.rollWhy = why;
  return true;
}

function rollAttack(s: State): void {
  const atk = s.atk as Attack;
  const a = atk.a;
  const d = atk.d;
  const as = stats(s, a);
  const ds = stats(s, d);
  const power = attackPower(s);
  const acc = as.kw["Accuracy"] || 0;
  const need = ds.kw["Armor"] ? 5 : 4;
  const hitOf = (v: number) => v + acc >= need;
  let dice: number[] = [];
  for (let i = 0; i < power; i += 1) dice.push(rollDie(s));
  // Foresight / Forewarning predictions: the most likely number of hits.
  const guess = expectedHits(power, need - acc);
  // Triggers on the initial roll (natural results).
  if (as.kw["Fury"] && dice.indexOf(4) >= 0) for (let i = 0; i < as.kw["Fury"]; i += 1) dice.push(rollDie(s));
  if (as.kw["Focus"] && dice.indexOf(5) >= 0) card(s, a).bf.push({ sp: 0, pw: as.kw["Focus"], hp: 0, u: "T", kw: null });
  const backfire = as.kw["Backfire"] && dice.indexOf(3) >= 0 ? as.kw["Backfire"] : 0;
  // Lucky: the attacker rerolls misses, the defender makes the attacker reroll hits.
  let lucky = as.kw["Lucky"] || 0;
  for (let i = 0; i < dice.length && lucky > 0; i += 1) if (!hitOf(dice[i])) {
    dice[i] = rollDie(s);
    lucky -= 1;
  }
  let dl = ds.kw["Lucky"] || 0;
  for (let i = 0; i < dice.length && dl > 0; i += 1) if (hitOf(dice[i])) {
    dice[i] = rollDie(s);
    dl -= 1;
  }
  let hits = 0;
  for (const v of dice) if (hitOf(v)) hits += 1;
  atk.dice = dice;
  atk.hits = hits;
  let pending = hits;
  if (as.kw["Critical Hit"] && dice.indexOf(6) >= 0) pending += as.kw["Critical Hit"];
  atk.pending = pending;
  log(s, nameOf(s, a) + " rolls " + dice.join(",") + ": " + hits + " hit" + (hits === 1 ? "" : "s") + (pending !== hits ? " (" + pending + " damage)" : "") + ".");
  if (ds.kw["Parry"] && dice.indexOf(1) >= 0) atk.prevented += Math.min(ds.kw["Parry"], pending);
  if (ds.kw["Riposte"] && dice.indexOf(2) >= 0) atk.retaliate.push({ u: d, n: -ds.kw["Riposte"] });
  if (backfire) atk.retaliate.push({ u: a, n: -1000 - backfire });
  // Foresight / Forewarning.
  for (const [unit, ev] of [[a, "foresight"], [d, "forewarning"]] as [number, string][]) {
    const ud = defOf(s, unit);
    for (let i = 0; i < ud.ab.length; i += 1) {
      const ab = ud.ab[i];
      if (ab.k === "trig" && ab.ev === ev && guess === hits) s.q.push({ src: unit, ab: i, ctrl: card(s, unit).c });
    }
  }
  // Overkill: hits beyond the defender's remaining health go to another enemy unit.
  if (as.kw["Overkill"]) {
    const excess = pending - Math.max(0, remainingHealth(s, d));
    if (excess > 0) {
      const others = unitsIn(s, atk.ar, card(s, d).c).filter((u) => u !== d);
      if (others.length > 0) {
        others.sort((x, y) => {
          const kx = remainingHealth(s, x) <= excess ? 1 : 0;
          const ky = remainingHealth(s, y) <= excess ? 1 : 0;
          return ky - kx || defOf(s, y).cost - defOf(s, x).cost;
        });
        atk.absorbTo = [others[0], excess];
        atk.pending -= excess;
      }
    }
  }
  atk.stage = 1;
}

function placeDamage(s: State): void {
  const atk = s.atk as Attack;
  const a = atk.a;
  const d = atk.d;
  const as = stats(s, a);
  const ds = s.cards[d] ? stats(s, d) : null;
  let dmg = Math.max(0, atk.pending - atk.prevented);
  if (as.kw["Ferocity"] && ds && !ds.kw["Fortitude"]) dmg = atk.pending;
  if (as.kw["Double Damage"]) dmg *= 2;
  const killedBefore = !s.cards[d] || !inArena(card(s, d));
  if (!killedBefore && dmg > 0) {
    log(s, nameOf(s, d) + " takes " + dmg + " damage.");
    const stun = as.kw["Stun"] || 0;
    addDamage(s, d, dmg, a);
    if (stun > 0 && inArena(card(s, d))) card(s, d).bf.push({ sp: 0, pw: -stun, hp: 0, u: "B", kw: null });
    if (!inArena(card(s, d))) {
      // Area Damage and Avenge.
      if (as.kw["Area Damage"]) {
        const foes = unitsIn(s, atk.ar, card(s, d).o === card(s, a).c ? other(card(s, a).c) : other(card(s, a).c));
        foes.sort((x, y) => remainingHealth(s, x) - remainingHealth(s, y));
        if (foes.length > 0) diceOfDamage(s, foes[0], as.kw["Area Damage"], a);
      }
      for (const u of unitsIn(s, atk.ar, other(card(s, a).c))) {
        const av = stats(s, u).kw["Avenge"];
        if (av) atk.retaliate.push({ u, n: av });
      }
    }
  }
  for (const df of atk.deflect) {
    const n = Math.floor(df.n / 1000);
    const to = df.n % 1000;
    addDamage(s, to, n, df.from);
  }
  if (atk.absorbTo.length === 2) addDamage(s, atk.absorbTo[0], atk.absorbTo[1], a);
  atk.stage = 2;
}

function endAttack(s: State): void {
  const atk = s.atk as Attack;
  for (const r of atk.retaliate) {
    if (!s.cards[atk.a] || !inArena(card(s, atk.a))) break;
    if (r.n <= -1000) diceOfDamage(s, atk.a, -1000 - r.n, atk.a); // Backfire
    else if (r.n < 0) addDamage(s, atk.a, -r.n, r.u); // Riposte
    else diceOfDamage(s, atk.a, r.n, r.u); // Retaliate / Avenge
  }
  expire(s, "A");
  const a = atk.a;
  s.atk = null;
  if (s.cards[a] && inArena(card(s, a)) && stats(s, a).kw["Double Strike"] && card(s, a).tp && s.attacked.filter((x) => x === a).length === 1 && attackTargets(s, a).length > 0) {
    s.attacked.push(a);
    s.sel = a;
    s.ph = "double";
    s.who = card(s, a).c;
    return;
  }
  s.fl = "betweenPop";
  s.ph = "flow";
}

// --------------------------------------------------------------------------------------------
// POP chances
// --------------------------------------------------------------------------------------------

function openPop(s: State, kind: Pop["kind"], next: string): void {
  s.pop = { kind, passes: 0 };
  s.popNext = next;
  s.ph = "pop";
  s.who = s.dark;
}

/** Pass automatically for a player with nothing to play. Returns true when the POP closed. */
function settlePop(s: State): boolean {
  for (let guard = 0; guard < 4; guard += 1) {
    if (s.ph !== "pop" || !s.pop) return false;
    if (s.pop.passes >= 2) {
      s.pop = null;
      s.fl = s.popNext;
      s.ph = "flow";
      return true;
    }
    const moves = legalMoves(s);
    if (moves.length > 1) return false;
    s.pop.passes += 1;
    s.who = other(s.who);
  }
  return false;
}

// --------------------------------------------------------------------------------------------
// Automatic steps
// --------------------------------------------------------------------------------------------

function startGame(s: State): void {
  s.turn = 0;
  s.fl = "turnStart";
  s.ph = "flow";
}

function payUpkeep(s: State, seat: number): void {
  for (let ar = 0; ar < 3; ar += 1) {
    for (const u of unitsIn(s, ar, seat)) {
      for (const ab of defOf(s, u).ab) {
        if (ab.k !== "kw" || ab.kw.indexOf("Upkeep:") !== 0) continue;
        const opts = ab.kw.slice(7).replace(/\.$/, "").split(/,? or /);
        for (const o of opts) {
          const costs = parseCosts(o.trim(), defOf(s, u).n, defOf(s, u).base);
          if (costs && canPay(s, u, seat, costs, 0, -1)) {
            pay(s, u, seat, costs, 0, -1);
            break;
          }
        }
      }
    }
  }
}

/** Run automatic steps until a decision is needed (or the game ends). */
function advance(s: State): void {
  for (let guard = 0; guard < 400; guard += 1) {
    if (s.win >= 0) {
      s.ph = "over";
      return;
    }
    if (s.ph === "target" || s.ph === "double" || s.ph === "roll") return;
    if (s.q.length > 0 && processQueue(s)) return;
    if (s.win >= 0) continue;
    if (s.ph === "pop") {
      if (!settlePop(s)) return;
      continue;
    }
    if (s.ph !== "flow") {
      // A decision phase whose only option is a single forced move is still offered: callers decide.
      return;
    }
    const fl = s.fl;
    if (fl === "pregame") {
      s.fl = "event0";
    } else if (fl === "event0" || fl === "event1") {
      const seat = fl === "event0" ? s.dark : other(s.dark);
      s.fl = fl === "event0" ? "event1" : "resource0";
      if (zoneIds(s, seat, "sup").some((id) => (defOf(s, id).ty & T_EVENT) !== 0)) {
        s.ph = "event";
        s.who = seat;
        return;
      }
    } else if (fl === "resource0" || fl === "resource1") {
      const seat = fl === "resource0" ? s.dark : other(s.dark);
      s.fl = fl === "resource0" ? "resource1" : "deal";
      if (s.P[seat].deck.some((id) => (defOf(s, id).ty & T_RESOURCE) !== 0)) {
        s.ph = "resource";
        s.who = seat;
        return;
      }
    } else if (fl === "deal") {
      for (const seat of [0, 1]) {
        shuffleIds(s, s.P[seat].deck);
        draw(s, seat, HAND_SIZE - handOf(s, seat).length);
      }
      s.fl = "mull0";
    } else if (fl === "mull0" || fl === "mull1") {
      const seat = fl === "mull0" ? s.dark : other(s.dark);
      s.fl = fl === "mull0" ? "mull1" : "setup";
      if (handOf(s, seat).some((id) => !isUnitDef(defOf(s, id)))) {
        s.ph = "mulligan";
        s.who = seat;
        return;
      }
    } else if (fl === "setup") {
      s.P[0].bp = START_BUILD;
      s.P[1].bp = START_BUILD;
      s.setupTurn = s.dark;
      s.ph = "setup";
      s.who = s.dark;
      return;
    } else if (fl === "turnStart") {
      s.turn += 1;
      if (s.turn > MAX_TURNS) {
        s.win = 2;
        log(s, "The game is a draw after " + MAX_TURNS + " turns.");
        continue;
      }
      untapAll(s);
      for (const c of s.cards) if (c) {
        c.ua = 0;
        c.mv = false;
        c.eqT = false;
      }
      for (const seat of [0, 1]) s.P[seat].force += 4;
      s.fl = "buildRoll";
    } else if (fl === "buildRoll") {
      // The Dark Side rolls the build die for both players.
      if (waitForDice(s, 1, s.dark, "build")) return;
      s.roll = rollDie(s);
      s.dq = [];
      for (const seat of [0, 1]) {
        let all = true;
        for (let ar = 0; ar < 3; ar += 1) if (unitsIn(s, ar, seat).length === 0) all = false;
        s.P[seat].bp = s.roll + (all ? 1 : 0);
      }
      log(s, "Turn " + s.turn + ": build roll " + s.roll + ".");
      queueGlobal(s, "turnStart", -1);
      queueGlobal(s, "buildRoll", -1);
      s.step = s.dark;
      s.fl = "buildStart";
    } else if (fl === "buildStart") {
      const seat = s.step;
      draw(s, seat, 1);
      payUpkeep(s, seat);
      for (let ar = 0; ar < 3; ar += 1) {
        for (const u of unitsIn(s, ar, seat)) {
          const dc = stats(s, u).kw["Damage Control"] || 0;
          if (dc > 0 && card(s, u).dm > 0) card(s, u).dm = Math.max(0, card(s, u).dm - dc);
        }
      }
      queueGlobal(s, "buildStart", seat);
      s.fl = "build";
    } else if (fl === "build") {
      s.ph = "build";
      s.who = s.step;
      s.sel = -1;
      return;
    } else if (fl === "retreat") {
      s.ph = "retreat";
      s.who = s.step;
      return;
    } else if (fl === "battleStart") {
      queueGlobal(s, "battleStart", -1);
      s.arena = 0;
      s.fl = "arenaStart";
    } else if (fl === "arenaStart") {
      s.attacked = [];
      for (const u of unitsIn(s, s.arena, -1)) {
        const v = stats(s, u).kw["Velocity"] || 0;
        if (v > 0) card(s, u).bf.push({ sp: v, pw: 0, hp: 0, u: "T", kw: null });
      }
      queueGlobal(s, "arenaStart" + s.arena, -1);
      s.fl = "arenaPop";
    } else if (fl === "arenaPop") {
      openPop(s, "astart", "attackSelect");
    } else if (fl === "attackSelect") {
      const choices = attackerChoices(s);
      if (choices.length === 0) {
        openPop(s, "aend", "arenaEnd");
        continue;
      }
      const seat = card(s, choices[0]).c;
      if (choices.length > 1) {
        s.ph = "choose-attacker";
        s.who = seat;
        return;
      }
      if (!beginAttackChoice(s, choices[0])) continue;
      return;
    } else if (fl === "atkPop") {
      openPop(s, "atk", "atkRoll");
    } else if (fl === "atkRoll") {
      const atk = s.atk as Attack;
      const aOk = !!s.cards[atk.a] && inArena(card(s, atk.a));
      const dOk = !!s.cards[atk.d] && inArena(card(s, atk.d));
      if (atk.disrupted || !aOk || !dOk) {
        s.fl = "atkEnd";
        continue;
      }
      if (waitForDice(s, attackPower(s), card(s, atk.a).c, "attack")) return;
      rollAttack(s);
      s.dq = [];
      s.fl = "atkPlace";
      if (atk.pending - atk.prevented > 0) openPop(s, "prev", "atkPlace");
    } else if (fl === "atkPlace") {
      placeDamage(s);
      s.fl = "atkEnd";
    } else if (fl === "atkEnd") {
      endAttack(s);
      if (s.ph !== "flow") return;
    } else if (fl === "unwind") {
      unwindStack(s);
      if (s.ph !== "flow" && s.ph !== "pop") return;
    } else if (fl === "betweenPop") {
      openPop(s, "gen", "attackSelect");
    } else if (fl === "arenaEnd") {
      s.arena += 1;
      s.fl = s.arena < 3 ? "arenaStart" : "battleEnd";
    } else if (fl === "battleEnd") {
      queueGlobal(s, "battleEnd", -1);
      s.fl = "endTurn";
    } else if (fl === "endTurn") {
      expire(s, "T");
      for (const seat of [s.dark, other(s.dark)]) {
        if (arenasControlled(s, seat) >= 2) {
          s.win = seat;
          log(s, s.seats[seat] + " controls " + arenasControlled(s, seat) + " arenas and wins.");
          break;
        }
      }
      s.fl = "turnStart";
    } else {
      throw new Error("unknown flow step " + fl);
    }
  }
}

/** Offer the attacker its target choice; auto-tap it when it has nothing to do. Returns true on a decision. */
function beginAttackChoice(s: State, a: number): boolean {
  s.sel = a;
  const seat = card(s, a).c;
  s.who = seat;
  const targets = attackTargets(s, a);
  const acts = actsOf(s, a).filter((e) => actUsable(s, e, seat, "would", a));
  if (targets.length === 0 && acts.length === 0) {
    card(s, a).tp = true;
    if (s.attacked.indexOf(a) < 0) s.attacked.push(a);
    s.fl = "attackSelect";
    s.ph = "flow";
    return false;
  }
  s.ph = "attack-target";
  return true;
}

// --------------------------------------------------------------------------------------------
// Apply
// --------------------------------------------------------------------------------------------

function cloneState(s: State): State {
  return {
    v: s.v,
    seats: s.seats,
    defs: s.defs,
    cards: s.cards.map((c) => (c ? { ...c, bf: c.bf.slice() } : null)),
    P: s.P.map((p) => ({ ...p, deck: p.deck.slice() })),
    dark: s.dark,
    rng: s.rng,
    turn: s.turn,
    ph: s.ph,
    who: s.who,
    step: s.step,
    arena: s.arena,
    pop: s.pop ? { ...s.pop } : null,
    popNext: s.popNext,
    atk: s.atk
      ? {
          ...s.atk,
          dice: s.atk.dice.slice(),
          deflect: s.atk.deflect.map((x) => ({ ...x })),
          retaliate: s.atk.retaliate.map((x) => ({ ...x })),
          absorbTo: s.atk.absorbTo.slice(),
          usedPrev: s.atk.usedPrev.slice()
        }
      : null,
    choice: s.choice ? { ...s.choice, need: s.choice.need.slice(), got: s.choice.got.slice() } : null,
    sel: s.sel,
    win: s.win,
    attacked: s.attacked.slice(),
    roll: s.roll,
    log: [],
    plies: s.plies,
    q: s.q.map((x) => ({ ...x })),
    fl: s.fl,
    setupTurn: s.setupTurn,
    stk: s.stk.map((x) => ({ ...x, got: x.got.slice() })),
    stkBack: s.stkBack ? { ...s.stkBack, pop: s.stkBack.pop ? { ...s.stkBack.pop } : null } : null,
    pd: s.pd,
    dq: s.dq.slice(),
    rollN: s.rollN,
    rollWhy: s.rollWhy
  };
}

/** Put a completed card where it goes (`t`: arena 0..2, or 3). Pays nothing. */
function placeCompleted(s: State, id: number, t: number): void {
  const c = card(s, id);
  const d = s.defs[c.d];
  const seat = c.o;
  c.fd = false;
  c.bc = 0;
  c.c = seat;
  if (isUnitDef(d)) {
    const st = stackTarget(s, id);
    if (st >= 0) {
      const head = card(s, st);
      if (d.cost > defOf(s, st).cost) {
        // The new version goes on the stack's head; the old one (and everything under it) moves under.
        c.z = head.z;
        c.tp = head.tp;
        c.dm = head.dm;
        c.bf = head.bf;
        for (const u of attached(s, st, -1)) card(s, u).h = id;
        head.z = "under";
        head.h = id;
        head.ut = 1;
        head.bf = [];
        head.dm = 0;
        log(s, d.n + " is stacked on " + defOf(s, st).n + ".");
        if (inArena(c)) queueTriggers(s, id, "deploy");
      } else {
        c.z = "under";
        c.h = st;
        c.ut = 1;
        log(s, d.n + " is stacked under " + defOf(s, st).n + ".");
      }
      return;
    }
    c.z = t === 3 ? "build" : zoneOfArena(t);
    c.dep = s.turn;
    log(s, d.n + (t === 3 ? " is deployed to the build zone." : " is deployed to the " + ARENA_NAMES[t] + " arena."));
    if (t < 3) {
      queueTriggers(s, id, "deploy");
      ambush(s, id);
    }
    return;
  }
  if ((d.ty & T_LOCATION) !== 0) {
    const old = locationIn(s, t);
    if (old >= 0) toDiscard(s, old, false);
    c.z = zoneOfArena(t);
    log(s, d.n + " is put into the " + ARENA_NAMES[t] + " arena.");
    queueTriggers(s, id, "complete");
    return;
  }
  if ((d.ty & T_RESOURCE) !== 0) {
    c.z = "res";
    log(s, d.n + " is completed.");
    queueTriggers(s, id, "complete");
    return;
  }
  if ((d.ty & T_MISSION) !== 0) {
    log(s, d.n + " is completed.");
    c.z = "aside";
    queueTriggers(s, id, "complete");
    // The Mission is discarded once its effect resolves; the queue entry still refers to it.
    s.q.push({ src: id, ab: -1, ctrl: seat });
    return;
  }
  c.z = "build"; // Equipment waits face up in the build zone.
  log(s, d.n + " is completed.");
}

/** Ambush: an opposing unit with an affordable "Ambush X" does X dice of damage to a unit entering its arena. */
function ambush(s: State, id: number): void {
  const c = card(s, id);
  const ar = arenaOfZone(c.z);
  if (ar < 0) return;
  for (const u of unitsIn(s, ar, other(c.c))) {
    for (const ent of actsOf(s, u)) {
      const e = ent.ab.fx[0];
      if (!e || e.e !== "ambush") continue;
      if (!canPay(s, u, card(s, u).c, ent.ab.cost, 0, -1)) continue;
      pay(s, u, card(s, u).c, ent.ab.cost, 0, -1);
      diceOfDamage(s, id, e.n, u);
      if (!s.cards[id] || !inArena(card(s, id))) return;
    }
  }
}

/** Start using an activated ability: choose targets first, then pay and resolve. */
function startAct(s: State, holder: number, k: number, back: Phase): void {
  const seat = s.who;
  const ent = actsOf(s, holder)[k];
  const ab = ent.ab;
  const isPrevent = ab.fx.some((e) => e.e === "prevent");
  const ch: Choice = { src: holder, ab: k, ctrl: seat, need: isPrevent ? [] : ab.tg.slice(), got: [], then: "act", x: 0, back, bw: -1 };
  if (ch.need.length > 0) {
    s.choice = ch;
    s.ph = "target";
    return;
  }
  finishAct(s, ch);
}

function finishAct(s: State, ch: Choice): void {
  const holder = ch.src;
  const seat = ch.ctrl;
  const ent = actsOf(s, holder)[ch.ab];
  s.choice = null;
  if (!ent) {
    s.ph = ch.back;
    return;
  }
  const ab = ent.ab;
  const hc = card(s, holder);
  const fromHand = hc.z === "hand";
  const x = xFor(s, seat, ab.fx, ab.cost);
  if (fromHand) hc.z = "aside";
  pay(s, holder, seat, ab.cost, x, holder);
  if (!fromHand) {
    const perAttack = ab.fx.some((e) => e.e === "prevent" || e.e === "retaliate" || e.e === "intercept" || e.e === "redirect");
    if (perAttack && s.atk) s.atk.usedPrev.push(holder * 1000 + ent.idx);
    else hc.ua |= 1 << (ent.idx % 30);
  }
  log(s, s.seats[seat] + " plays " + nameOf(s, holder) + ": " + ab.src);
  // Onto the response stack; the other player may answer it with a disrupt.
  if (s.stk.length === 0) {
    s.stkBack = { ph: ch.back, who: s.who, pop: s.pop ? { ...s.pop } : null, popNext: s.popNext, fl: s.fl };
  }
  s.stk.push({
    holder, k: ch.ab, ctrl: seat, got: ch.got.slice(), x,
    battle: fromHand && (defOf(s, holder).ty & T_BATTLE) !== 0,
    dsr: ab.fx.some((e) => e.e === "disrupt" && e.what !== "attack"),
    off: false,
    fromHand
  });
  if (canRespond(s, other(seat))) {
    s.pop = { kind: "dsr", passes: 0 };
    s.popNext = "unwind";
    s.ph = "pop";
    s.who = other(seat);
    return;
  }
  unwindStack(s);
}

/** Resolve the response stack, latest play first, then return to where play stood. */
function unwindStack(s: State): void {
  let bottomCtrl = -1;
  while (s.stk.length > 0) {
    const p = s.stk.pop() as Pending;
    bottomCtrl = p.ctrl;
    if (!p.off) {
      const ent = actsOf(s, p.holder)[p.k];
      if (ent) resolveFx(s, p.holder, p.ctrl, ent.ab.fx, p.got, p.x);
    }
    if (p.fromHand && s.cards[p.holder] && card(s, p.holder).z === "aside") toDiscard(s, p.holder, false);
    if (s.win >= 0) break;
  }
  const back = s.stkBack;
  s.stkBack = null;
  if (!back) return;
  s.ph = back.ph;
  s.pop = back.pop;
  s.popNext = back.popNext;
  s.fl = back.fl;
  s.who = back.who;
  // After a play in a POP, the other player has the next chance.
  if (s.ph === "pop" && s.pop && bottomCtrl >= 0) {
    s.pop.passes = 0;
    s.who = other(bottomCtrl);
  }
}

function setupNext(s: State, seat: number): void {
  const p = s.P[seat];
  const o = s.P[other(seat)];
  if (p.bp <= 0) p.setupDone = true;
  if (p.setupDone && o.setupDone) {
    for (const x of [0, 1]) s.P[x].bp = 0;
    startGame(s);
    return;
  }
  if (p.setupDone) s.who = other(seat);
  else if (!o.setupDone && p.setupSpent > o.setupSpent) s.who = other(seat);
  else s.who = seat;
  s.ph = "setup";
}

function applyMove(s0: State, m: Move): State {
  const s = cloneState(s0);
  s.plies += 1;
  const seat = s.who;
  const p = s.P[seat];
  const id = m.r >= 0 ? cellMapOf(s, seat).instOf[m.r] : -1;
  const a = m.a;
  switch (s.ph) {
    case "roll": {
      if (a > G_X0 && a <= G_X0 + 6) s.dq.push(a - G_X0);
      if (s.dq.length >= s.rollN) {
        s.ph = "flow";
        s.rollN = 0;
      }
      break;
    }
    case "event": {
      if (id >= 0) {
        card(s, id).z = "evt";
        log(s, s.seats[seat] + " plays the Event " + nameOf(s, id) + ".");
      }
      s.ph = "flow";
      break;
    }
    case "resource": {
      if (id >= 0) {
        p.deck = p.deck.filter((x) => x !== id);
        card(s, id).z = "hand";
        log(s, s.seats[seat] + " pulls " + nameOf(s, id) + ".");
      }
      s.ph = "flow";
      break;
    }
    case "mulligan": {
      if (a === A_TARGET && id >= 0) {
        card(s, id).z = "aside";
        break;
      }
      const aside = zoneIds(s, seat, "aside");
      draw(s, seat, aside.length);
      for (const x of aside) {
        if (a === G_MULL_DISCARD) toDiscard(s, x, false);
        else {
          card(s, x).z = "deck";
          p.deck.push(x);
        }
      }
      if (a === G_MULL_RETURN) shuffleIds(s, p.deck);
      if (aside.length > 0) log(s, s.seats[seat] + " mulligans " + aside.length + " card" + (aside.length === 1 ? "" : "s") + ".");
      p.mull = true;
      s.ph = "flow";
      break;
    }
    case "setup": {
      if (a === G_PASS) {
        p.setupDone = true;
      } else if (a === A_BUILD) {
        const c = card(s, id);
        c.z = "build";
        c.fd = true;
        c.bc = p.bp;
        p.setupSpent += p.bp;
        p.bp = 0;
        p.setupDone = true;
      } else {
        const c = card(s, id);
        const d = defOf(s, id);
        p.bp -= d.cost;
        p.setupSpent += d.cost;
        if (a === A_DEPLOY_BZ) {
          c.z = "res";
        } else {
          c.z = zoneOfArena(a - A_DEPLOY0);
        }
        log(s, s.seats[seat] + " sets up " + d.n + ".");
        draw(s, seat, 1);
      }
      setupNext(s, seat);
      break;
    }
    case "build": {
      if (s.sel >= 0) {
        const eq = s.sel;
        s.sel = -1;
        if (a === A_EQUIP && id >= 0 && pilotAbility(defOf(s, eq)) && isUnitDef(defOf(s, eq))) {
          const pc = card(s, eq);
          for (const x of attached(s, eq, -1)) toDiscard(s, x, true);
          pc.z = "under";
          pc.h = id;
          pc.ut = 3;
          pc.mv = true;
          log(s, nameOf(s, eq) + " pilots " + nameOf(s, id) + ".");
        } else if (a === A_EQUIP && id >= 0) {
          pay(s, eq, seat, equipCost(s, eq) || [], 0, -1);
          const e = card(s, eq);
          e.z = "under";
          e.h = id;
          e.ut = 2;
          e.eqT = true;
          e.tp = false;
          log(s, nameOf(s, eq) + " is equipped to " + nameOf(s, id) + ".");
        }
        break;
      }
      if (a === G_PASS) {
        p.bp = 0;
        if (s.step === s.dark) {
          s.step = other(s.dark);
          s.fl = "buildStart";
        } else {
          s.step = s.dark;
          s.fl = "retreat";
        }
        s.ph = "flow";
        break;
      }
      const c = card(s, id);
      if (a === A_BUILD) {
        if (c.z === "hand") {
          c.z = "build";
          c.fd = true;
          c.bc = 1;
        } else c.bc += 1;
        p.bp -= 1;
      } else if (a >= A_DEPLOY0 && a <= A_DEPLOY_BZ) {
        const need = completeCost(s, id);
        const how = completionPayment(s, id, seat);
        if (how === "bp") p.bp -= need;
        else if (how === "hidden") p.force -= need;
        else if (how === "alt") pay(s, id, seat, altCost(defOf(s, id)) || [], 0, id);
        placeCompleted(s, id, a === A_DEPLOY_BZ ? 3 : a - A_DEPLOY0);
      } else if (a >= A_MOVE0 && a < A_MOVE0 + 3 && c.z === "under" && c.ut === 3) {
        c.z = "a2";
        c.h = -1;
        c.ut = 0;
        c.mv = true;
        log(s, nameOf(s, id) + " stops piloting and moves to the Character arena.");
      } else if (a >= A_MOVE0 && a < A_MOVE0 + 3) {
        const wasArena = inArena(c);
        c.z = zoneOfArena(a - A_MOVE0);
        if (wasArena) c.mv = true;
        log(s, nameOf(s, id) + " moves to the " + ARENA_NAMES[a - A_MOVE0] + " arena.");
        ambush(s, id);
      } else if (a === A_EQUIP) {
        s.sel = id;
      } else if (a >= A_ACT0 && a < A_ACT0 + 4) {
        startAct(s, id, a - A_ACT0, "build");
      }
      break;
    }
    case "retreat": {
      if (a === G_PASS) {
        if (s.step === s.dark) {
          s.step = other(s.dark);
          s.fl = "retreat";
        } else s.fl = "battleStart";
        s.ph = "flow";
        break;
      }
      const c = card(s, id);
      c.tp = true;
      retreatUnit(s, id);
      log(s, nameOf(s, id) + " retreats.");
      break;
    }
    case "pop": {
      const pop = s.pop as Pop;
      if (a === G_PASS) {
        pop.passes += 1;
        s.who = other(seat);
        break;
      }
      pop.passes = 0;
      if (a >= A_ACT0 && a < A_ACT0 + 4) {
        startAct(s, id, a - A_ACT0, "pop");
      } else if (a >= A_DEPLOY0 && a < A_DEPLOY0 + 3) {
        // Hidden Cost: pay the rest in Force.
        p.force -= completeCost(s, id);
        placeCompleted(s, id, a - A_DEPLOY0);
      }
      // A play's own resolution decides who is next (unwindStack); a Hidden Cost completion passes the chance on.
      if (a >= A_DEPLOY0 && a < A_DEPLOY0 + 3 && s.ph === "pop") s.who = other(seat);
      break;
    }
    case "choose-attacker": {
      beginAttackChoice(s, id);
      break;
    }
    case "attack-target": {
      if (a === G_SKIP_ATTACK) {
        card(s, s.sel).tp = true;
        if (s.attacked.indexOf(s.sel) < 0) s.attacked.push(s.sel);
        log(s, nameOf(s, s.sel) + " does not attack.");
        s.sel = -1;
        s.fl = "betweenPop";
        s.ph = "flow";
      } else if (a === A_ATTACK) {
        const atkr = s.sel;
        s.sel = -1;
        declareAttack(s, atkr, id);
      } else if (a >= A_ACT0 && a < A_ACT0 + 4) {
        // "Play only when this unit would attack": used instead of attacking.
        const atkr = s.sel;
        if (s.attacked.indexOf(atkr) < 0) s.attacked.push(atkr);
        s.fl = "betweenPop";
        startAct(s, atkr, a - A_ACT0, "flow");
        s.sel = -1;
      }
      break;
    }
    case "double": {
      const atkr = s.sel;
      s.sel = -1;
      if (a === A_ATTACK) declareAttack(s, atkr, id);
      else {
        s.fl = "betweenPop";
        s.ph = "flow";
      }
      break;
    }
    case "target": {
      const ch = s.choice as Choice;
      if (a === G_NO) {
        s.choice = null;
        s.ph = ch.back;
        if (ch.then === "trig" && ch.bw >= 0) s.who = ch.bw;
        else if (ch.back === "pop") s.who = ch.ctrl;
        break;
      }
      ch.got.push(id);
      if (ch.got.length < ch.need.length) break;
      if (ch.then === "trig") {
        const ab = defOf(s, ch.src).ab[ch.ab];
        s.choice = null;
        if (ab && ab.k === "trig") {
          log(s, nameOf(s, ch.src) + ": " + ab.src);
          resolveFx(s, ch.src, ch.ctrl, ab.fx, ch.got, 0);
        }
        s.ph = ch.back;
        if (ch.bw >= 0) s.who = ch.bw;
      } else finishAct(s, ch);
      break;
    }
    default:
      break;
  }
  advance(s);
  if (s.win < 0 && s.plies >= MAX_PLIES) {
    s.win = 2;
    s.ph = "over";
    log(s, "The game is a draw: it ran too long.");
  }
  return s;
}

// ============================================================================================
// Star Wars TCG rules kernel - part 5: setup, encoding, heuristic and the kernel object.
// ============================================================================================

/** One deck in the match setup: indices into `catalog`, with counts. */
interface DeckSetup {
  name: string;
  side: string;
  main: [number, number][];
  supply: [number, number][];
}

/** `match.start({ kernel, setup })` data: both decks (seat order) and the shuffle seed. */
interface MatchSetup {
  v: number;
  seed: number;
  catalog: RawCard[];
  decks: DeckSetup[];
  /** "table": rolls wait for real dice (the table feeds the faces in as moves); absent: seeded RNG. */
  dice?: string;
}

function isMatchSetup(x: unknown): x is MatchSetup {
  if (typeof x !== "object" || x === null) return false;
  const o = x as { catalog?: unknown; decks?: unknown; seed?: unknown };
  return Array.isArray(o.catalog) && Array.isArray(o.decks) && o.decks.length >= 2 && typeof o.seed === "number";
}

/**
 * Two plain decks the kernel can always build: what `initial(seats)` plays when no setup is
 * given (the editor's checks, a trainer with no deck pool). Generated, so the kernel carries no
 * card data of its own.
 */
function demoSetup(seed: number): MatchSetup {
  const catalog: RawCard[] = [];
  const decks: DeckSetup[] = [];
  const arenaNames = ["Space", "Ground", "Character"];
  const extras = ["", "Armor", "Accuracy 1", "Pay 1 Force -> Evade 1", "Critical Hit 1", "Shields 1", "Stealth", "Pay 2 Force -> This unit gets +2 power until end of turn."];
  for (let side = 0; side < 2; side += 1) {
    const main: [number, number][] = [];
    for (let ar = 0; ar < 3; ar += 1) {
      for (let k = 0; k < 5; k += 1) {
        const cost = 2 + k + ((side + ar) % 2);
        catalog.push({
          name: (side === 0 ? "Imperial " : "Rebel ") + arenaNames[ar] + " Unit " + (k + 1),
          type: arenaNames[ar],
          subtype: side === 0 ? "Imperial" : "Rebel",
          side: side === 0 ? "D" : "L",
          cost: cost,
          speed: 20 + 10 * ((k + ar) % 5),
          power: Math.max(1, cost - 1 + (k % 2)),
          health: Math.max(1, cost - 1 + ((k + 1) % 2)),
          text: extras[(k * 3 + ar + side) % extras.length]
        });
        main.push([catalog.length - 1, 4]);
      }
    }
    decks.push({ name: side === 0 ? "Demo Dark Side" : "Demo Light Side", side: side === 0 ? "D" : "L", main, supply: [] });
  }
  return { v: 1, seed, catalog, decks };
}

function newCard(d: number, seat: number, z: Zone): Card {
  return { d, o: seat, c: seat, z, fd: false, bc: 0, dm: 0, tp: false, rc: 0, h: -1, ut: 0, mv: false, eqT: false, ua: 0, bf: [], dep: 0 };
}

function sideRank(side: string): number {
  return side === "D" ? 0 : side === "Y" ? 1 : side === "L" ? 2 : 3;
}

function initialState(seats: string[], setup: unknown): State {
  const st = isMatchSetup(setup) ? setup : demoSetup(hashString(seats.join("|")));
  const defs = st.catalog.map((raw) => parseDef(raw));
  const cards: (Card | null)[] = [];
  for (let i = 0; i < SLOTS; i += 1) cards.push(null);
  const P: Player[] = [];
  for (let seat = 0; seat < 2; seat += 1) {
    P.push({ force: 0, bp: 0, deck: [], mull: false, setupDone: false, setupSpent: 0, drew: false, pending: 0 });
    let n = 0;
    const deck = st.decks[seat];
    for (const [idx, count] of deck.main) {
      if (idx < 0 || idx >= defs.length) continue;
      for (let k = 0; k < count && n < HALF; k += 1) {
        const id = seat * HALF + n;
        n += 1;
        cards[id] = newCard(idx, seat, "deck");
        P[seat].deck.push(id);
      }
    }
    for (const [idx, count] of deck.supply || []) {
      if (idx < 0 || idx >= defs.length) continue;
      for (let k = 0; k < count && n < HALF; k += 1) {
        const id = seat * HALF + n;
        n += 1;
        cards[id] = newCard(idx, seat, "sup");
      }
    }
  }
  const r0 = sideRank(st.decks[0].side || "N");
  const r1 = sideRank(st.decks[1].side || "N");
  const dark = r0 < r1 ? 0 : r1 < r0 ? 1 : (st.seed >>> 0) % 2;
  const s: State = {
    v: 1,
    seats: seats.slice(0, 2),
    defs,
    cards,
    P,
    dark,
    rng: (st.seed >>> 0) || 1,
    turn: 0,
    ph: "flow",
    who: dark,
    step: dark,
    arena: 0,
    pop: null,
    popNext: "",
    atk: null,
    choice: null,
    sel: -1,
    win: -1,
    attacked: [],
    roll: 0,
    log: [],
    plies: 0,
    q: [],
    fl: "pregame",
    setupTurn: dark,
    stk: [],
    stkBack: null,
    pd: st.dice === "table",
    dq: [],
    rollN: 0,
    rollWhy: ""
  };
  advance(s);
  return s;
}

// --------------------------------------------------------------------------------------------
// Encoding: 9 rows x 16 columns. Rows 0-7 are the 128 move cells (see `cellMapOf`), one card per
// cell, PLANES features each; row 8 carries the global numbers (Force, build points, phase...),
// 48 values spread over its first planes. Hidden cards show only that they are there.
// --------------------------------------------------------------------------------------------

const PLANES = 32;
const ENC_H = 9;
const ENC_W = 16;
const PHASE_LIST = ["event", "resource", "mulligan", "setup", "build", "retreat", "pop", "choose-attacker", "attack-target", "target", "double"];

function encodeState(s: State): Float32Array {
  const me = s.who;
  const area = ENC_H * ENC_W;
  const out = new Float32Array(PLANES * area);
  const put = (plane: number, cell: number, v: number) => {
    out[plane * area + cell] = v;
  };
  const map = cellMapOf(s, me);
  const legal = legalMoves(s);
  const legalCells: { [r: number]: boolean } = {};
  for (const m of legal) if (m.r >= 0) legalCells[m.r] = true;
  for (let cell = 0; cell < CELLS; cell += 1) {
    const id = map.instOf[cell];
    if (id < 0) continue;
    const c = card(s, id);
    const d = s.defs[c.d];
    const mine = c.o === me;
    put(0, cell, 1);
    const publicZone = inArena(c) || c.z === "disc" || c.z === "res" || c.z === "evt" || c.z === "under" || (c.z === "build" && !c.fd);
    const known = mine || (publicZone && !c.fd);
    put(1, cell, known ? 1 : 0);
    put(2, cell, c.tp ? 1 : 0);
    put(3, cell, c.fd ? 1 : 0);
    put(4, cell, c.dm / 10);
    put(5, cell, c.bc / 10);
    put(30, cell, attached(s, id, -1).length / 3);
    put(27, cell, legalCells[cell] ? 1 : 0);
    put(28, cell, (s.atk && s.atk.a === id) || s.sel === id ? 1 : 0);
    put(29, cell, s.atk && s.atk.d === id ? 1 : 0);
    if (!known) continue;
    put(6, cell, d.cost / 10);
    const st = inArena(c) && isUnitDef(d) ? stats(s, id) : { sp: d.sp, pw: d.pw, hp: d.hp, kw: d.kw };
    put(7, cell, st.sp / 100);
    put(8, cell, st.pw / 10);
    put(9, cell, st.hp / 10);
    put(10, cell, (st.hp - c.dm) / 10);
    const flags = [T_SPACE, T_GROUND, T_CHAR, T_BATTLE, T_MISSION, T_EQUIP, T_LOCATION, T_RESOURCE];
    for (let k = 0; k < flags.length; k += 1) if ((d.ty & flags[k]) !== 0) put(11 + k, cell, 1);
    put(19, cell, d.uq ? 1 : 0);
    const kw = st.kw;
    put(20, cell, kw["Armor"] ? 1 : 0);
    put(21, cell, kw["Stealth"] ? 1 : 0);
    put(22, cell, (kw["Shields"] || 0) / 3);
    put(23, cell, (kw["Accuracy"] || 0) / 3);
    put(24, cell, ((kw["Critical Hit"] || 0) + (kw["Fury"] || 0) + (kw["Lucky"] || 0)) / 4);
    let prev = 0;
    let acts = 0;
    let trig = 0;
    for (const ab of d.ab) {
      if (ab.k === "act") {
        if (ab.fx.some((e) => e.e === "prevent")) prev = 1;
        else acts = 1;
      } else if (ab.k === "trig") trig = 1;
    }
    put(25, cell, prev);
    put(26, cell, acts);
    put(31, cell, trig + (kw["Double Strike"] ? 0.5 : 0) + (kw["Overkill"] ? 0.5 : 0));
  }
  const opp = other(me);
  const g: number[] = [];
  for (let k = 0; k < 48; k += 1) g.push(0);
  g[0] = s.P[me].force / 20;
  g[1] = s.P[opp].force / 20;
  g[2] = s.P[me].bp / 10;
  g[3] = s.P[opp].bp / 10;
  g[4] = s.turn / MAX_TURNS;
  g[5] = s.dark === me ? 1 : 0;
  const pi = PHASE_LIST.indexOf(s.ph);
  if (pi >= 0) g[6 + pi] = 1;
  if (s.arena >= 0 && s.arena < 3) g[17 + s.arena] = 1;
  g[20] = handOf(s, me).length / 10;
  g[21] = handOf(s, opp).length / 10;
  g[22] = s.P[me].deck.length / 60;
  g[23] = s.P[opp].deck.length / 60;
  g[24] = s.pop && s.pop.kind === "prev" ? 1 : 0;
  g[25] = s.pop && s.pop.kind === "atk" ? 1 : 0;
  g[26] = s.pop && (s.pop.kind === "gen" || s.pop.kind === "astart" || s.pop.kind === "aend") ? 1 : 0;
  g[27] = (arenasControlled(s, me) - arenasControlled(s, opp)) / 3;
  g[28] = arenasControlled(s, me) / 3;
  g[29] = arenasControlled(s, opp) / 3;
  g[30] = s.roll / 6;
  g[31] = s.step === me ? 1 : 0;
  for (let ar = 0; ar < 3; ar += 1) {
    g[32 + ar] = unitsIn(s, ar, me).length / 6;
    g[35 + ar] = unitsIn(s, ar, opp).length / 6;
  }
  g[38] = s.atk ? (s.atk.pending - s.atk.prevented) / 10 : 0;
  g[39] = s.choice ? 1 : 0;
  g[40] = s.stk.length > 0 ? 1 : 0;
  g[41] = s.pop && s.pop.kind === "dsr" ? 1 : 0;
  for (let k = 0; k < 48; k += 1) if (g[k] !== 0) out[(k >> 4) * area + CELLS + (k & 15)] = g[k];
  return out;
}

/** Board-strength estimate for one seat. */
function seatScore(s: State, seat: number): number {
  let score = 0;
  for (let ar = 0; ar < 3; ar += 1) {
    const mine = unitsIn(s, ar, seat);
    for (const u of mine) {
      const st = stats(s, u);
      score += defOf(s, u).cost * 0.6 + st.pw * 0.5 + Math.max(0, st.hp - card(s, u).dm) * 0.4;
    }
    if (controlsArena(s, seat, ar)) score += 5;
    else if (mine.length > 0) score += 1;
  }
  for (const id of zoneIds(s, seat, "build")) {
    const c = card(s, id);
    score += c.fd ? c.bc * 0.6 : defOf(s, id).cost * 0.3;
  }
  // Build points still to spend this step are worth what they will buy: passing early is a loss.
  if ((s.ph === "build" || s.ph === "setup") && s.who === seat) score += s.P[seat].bp * 0.6;
  score += s.P[seat].force * 0.15 + handOf(s, seat).length * 0.4;
  return score;
}

function heuristicValue(s: State): number {
  const me = s.who;
  const v = (seatScore(s, me) - seatScore(s, other(me))) / 20;
  return Math.max(-0.95, Math.min(0.95, v / (1 + Math.abs(v))));
}

const kernel: RulesKernel<State, Move> = {
  id: "swtcg",
  version: 5,
  initial(seats: string[], setup?: unknown): State {
    return initialState(seats, setup);
  },
  currentPlayer(s: State): string {
    return s.seats[s.who];
  },
  legalMoves(s: State): Move[] {
    return legalMoves(s);
  },
  apply(s: State, m: Move): State {
    return applyMove(s, m);
  },
  terminal(s: State): { value: Record<string, number> } | null {
    if (s.win < 0) return null;
    const value: Record<string, number> = {};
    for (let i = 0; i < s.seats.length; i += 1) value[s.seats[i]] = s.win === 2 ? 0 : s.win === i ? 1 : -1;
    return { value };
  },
  encode(s: State): Float32Array {
    return encodeState(s);
  },
  encoding: { planes: PLANES, height: ENC_H, width: ENC_W },
  policySize: POLICY_SIZE,
  moveIndex(m: Move): number {
    return m.r < 0 ? CELLS * NA + m.a : m.r * NA + m.a;
  },
  moveAt(i: number): Move {
    return i >= CELLS * NA ? { r: -1, a: i - CELLS * NA } : { r: Math.floor(i / NA), a: i % NA };
  },
  heuristic(s: State): number {
    return heuristicValue(s);
  }
};

// ============================================================================================
// Star Wars TCG rules kernel - part 6: a greedy player.
//
// A one-ply rule-of-thumb player: deploy the biggest unit it can afford where it is weakest,
// keep building, never retreat, attack what it can kill, prevent damage that would kill. The
// table's "easy" bot, the search's opponent model in tests, and a baseline for trained models.
// ============================================================================================

/**
 * "Discard a card from your hand -> Gain N Force" and the like: an ability that costs a hand card
 * and gives back only Force. Unchecked, the greedy player fired it every time it could (it beat
 * ending the step) and emptied its hand for Force it then had nothing to spend on. Worth it only
 * with a big hand; otherwise it scores below passing.
 */
function cardForForceScore(s: State, ab: Ability & { k: "act" }, seat: number): number | null {
  const costsCard = ab.cost.some((k) => k.c === "discard");
  const onlyForce = ab.fx.length > 0 && ab.fx.every((e) => e.e === "force");
  if (!costsCard || !onlyForce) return null;
  return handOf(s, seat).length > 5 ? 3 : -1;
}

function moveScore(s: State, m: Move, map: CellMap): number {
  const seat = s.who;
  const id = m.r >= 0 ? map.instOf[m.r] : -1;
  const d = id >= 0 ? defOf(s, id) : null;
  const a = m.a;
  const opp = other(seat);
  switch (s.ph) {
    case "event":
    case "resource":
      return id >= 0 ? 1 : 0;
    case "mulligan":
      return m.r < 0 ? 1 : 0;
    case "setup": {
      if (!d) return 0;
      if (a >= A_DEPLOY0 && a <= A_DEPLOY0 + 2) {
        const ar = a - A_DEPLOY0;
        return 100 + d.cost * 3 - unitsIn(s, ar, seat).length * 4 + d.pw + d.hp;
      }
      if (a === A_DEPLOY_BZ) return 90 + d.cost;
      if (a === A_BUILD) return 10 + d.cost;
      return 0;
    }
    case "build": {
      if (s.sel >= 0) return m.r >= 0 ? 50 + stats(s, id).pw : 0;
      if (!d) return 1;
      const c = card(s, id);
      if (a >= A_DEPLOY0 && a <= A_DEPLOY0 + 2) {
        const ar = a - A_DEPLOY0;
        const mine = unitsIn(s, ar, seat).length;
        const theirs = unitsIn(s, ar, opp).length;
        return 200 + d.cost * 4 + (theirs > mine ? 15 : 0) - mine * 3;
      }
      if (a === A_DEPLOY_BZ) {
        if (isUnitDef(d)) return completeTargets(s, id).length === 1 ? 150 : -10;
        if ((d.ty & T_RESOURCE) !== 0) return 180;
        if ((d.ty & T_MISSION) !== 0) return d.unk === 0 ? 120 : -5;
        return 130;
      }
      if (a >= A_MOVE0 && a <= A_MOVE0 + 2) {
        if (inArena(c)) return -5;
        const ar = a - A_MOVE0;
        return 170 + (unitsIn(s, ar, opp).length > unitsIn(s, ar, seat).length ? 10 : 0);
      }
      if (a === A_EQUIP) return 110;
      if (a === A_BUILD) {
        // Keep feeding the most advanced partially built card.
        if (c.z === "build") return 60 + c.bc * 5 + d.cost;
        const partial = zoneIds(s, seat, "build").filter((x) => card(s, x).fd).length;
        return partial > 0 ? 5 : 40 + d.cost;
      }
      if (a >= A_ACT0) {
        // Tapping a unit in an arena now means it cannot attack this turn.
        const ent = actsOf(s, id)[a - A_ACT0];
        if (ent && inArena(c) && isUnitDef(d) && ent.ab.cost.some((k) => k.c === "tap")) return 0;
        const trade = ent ? cardForForceScore(s, ent.ab, seat) : null;
        if (trade !== null) return trade;
        return 20;
      }
      return 0;
    }
    case "retreat":
      return m.r < 0 ? 1 : 0;
    case "pop": {
      if (m.r < 0) return 1;
      if (a >= A_DEPLOY0 && a <= A_DEPLOY0 + 2) return 30;
      const acts = actsOf(s, id);
      const ent = acts[a - A_ACT0];
      if (!ent) return 0;
      const atk = s.atk;
      if (ent.ab.fx.some((e) => e.e === "prevent")) {
        if (atk && atk.pending - atk.prevented >= remainingHealth(s, atk.d)) return 50;
        return 0;
      }
      if (ent.ab.fx.some((e) => e.e === "disrupt")) return 15;
      const trade = cardForForceScore(s, ent.ab, seat);
      if (trade !== null) return trade;
      if (ent.ab.fx.some((e) => e.e === "stat" && e.pw > 0) && atk && card(s, atk.a).c === seat) return 10;
      if (ent.ab.fx.some((e) => e.e === "damage" || e.e === "draw" || e.e === "force")) return 5;
      return 0;
    }
    case "choose-attacker":
      return stats(s, id).pw;
    case "attack-target":
    case "double": {
      if (m.r < 0) return 1;
      if (a !== A_ATTACK) return 0;
      const rem = remainingHealth(s, id);
      const pw = stats(s, s.sel).pw - (stats(s, id).kw["Shields"] || 0);
      if (pw <= 0) return 0;
      return 10 + (rem <= pw / 2 ? 20 : 0) + defOf(s, id).cost - rem;
    }
    case "target": {
      if (m.r < 0) return 0;
      const ch = s.choice as Choice;
      const f = ch.need[ch.got.length];
      if (card(s, id).c === seat) {
        if (f.side !== "me") return -10;
        const inAttack = s.atk && (s.atk.a === id || s.atk.d === id) ? 50 : 0;
        return stats(s, id).pw + 10 + inAttack;
      }
      return 20 - remainingHealth(s, id) + defOf(s, id).cost;
    }
    default:
      return 0;
  }
}

/** The greedy player's move. Ties go to the first move in `legalMoves` order. */
function greedyMove(s: State): Move {
  const moves = legalMoves(s);
  const map = cellMapOf(s, s.who);
  let best = moves[0];
  let bestScore = -Infinity;
  for (const m of moves) {
    const v = moveScore(s, m, map);
    if (v > bestScore) {
      bestScore = v;
      best = m;
    }
  }
  return best;
}

