// ============================================================================================
// Star Wars TCG - the TABLE half of the scene script (everything that touches the table).
//
// The rules live in the kernel above (`kernel`, pure). This half:
//   - builds the match setup from the decks the lobby loaded (or a starter deck for a bot),
//   - starts a match with the kernel and that setup,
//   - draws the kernel state on the table after every move (one entity per visible card),
//   - offers each legal move as a context-menu item on the card it concerns (scoped to the
//     seat that may play it), or on that seat's action button for moves with no card,
//   - plays the bots.
// Every module-level name here starts with "tx" so the kernel extractor never mistakes table code
// for a kernel helper.
// ============================================================================================

const TX_CARD_W = 0.2083;
const TX_CARD_L = 0.2917;
const TX_SEAT_IDS = ["red", "blue"];
const TX_BOT_PACE = 0.35;
const TX_ZONE_NAMES: { [k: string]: string } = {
  hand: "Player Hand", build: "Build Zone", res: "Resource", sup: "Supply", deck: "Deck", disc: "Discard",
  a0: "Space", a1: "Ground", a2: "Characters"
};
const TX_MOD_ID = "star-wars-tcg";

type TxCardRow = Readonly<Record<string, string | number | boolean | null>>;
type TxWorldExtra = {
  resolveCards?: (ids: readonly string[]) => Promise<Array<TxCardRow | null>>;
};
type TxMatchStart = (options: { seats?: readonly string[]; kernel?: RulesKernel<State, Move>; setup?: unknown }) => Promise<MatchInfo>;
type TxCounterApi = { setCounter?: (counterId: string, count: number) => void };

interface TxEnt {
  id: string;
  key: string;
  pos: Vec3;
  yaw: number;
  dm: number;
  bc: number;
  /** The tooltip text last written ("" = none). */
  tip: string;
  /** A card dealt into its seat's real hand: the platform lays it out and its owner may drag it. */
  hand: boolean;
}

/** The game in progress (kernel state), or null before a game starts. */
let txState: State | null = null;
let txSetup: MatchSetup | null = null;
/** Seat ids in kernel order (kernel seat 0, 1). */
let txSeats: string[] = ["red", "blue"];
/** Card ids (catalogue identity) for each setup catalog entry. */
let txCatalogIds: string[] = [];
let txMoves: Move[] = [];
let txRecording = false;
let txPractice = false;
let txOver = false;
const txEnts: { [inst: number]: TxEnt } = {};
const txPiles: { [seat: number]: { id: string; n: number } } = {};
const txDiscardOrder: number[][] = [[], []];
let txZones: { [seat: number]: { [name: string]: SeatZoneInfo } } = {};
let txMenuIds: string[] = [];
let txMenuMoves: Move[] = [];
let txMenuVer = 0;
let txMenuSeat = -1;
/** The HUD move buttons now showing: button id -> the move it plays. */
let txHudMoves: { [id: string]: Move } = {};
/** The HUD button that rolls the pending dice ("" when nobody is rolling). */
let txHudRoll = "";
/** HUD state last written ("seat|key|private" -> value), so a redraw sends only what changed. */
const txHudCache: { [k: string]: UiValue } = {};
let txSource: { kind: string; id: string; version: number } = { kind: "mod", id: TX_MOD_ID, version: 1 };
let txPawns: { [seat: number]: { id: string; track: Vec3[] } } = {};
let txChain: Promise<void> = Promise.resolve();
/** A person has made a move this game (until then, a lobby deck arriving late restarts the game). */
let txHumanMoved = false;
/** While a game is being set up: late lobby decks are picked up by this start, not a restart. */
let txStarting = false;
let txRestartQueued = false;
/** Temporary one-card piles the script is dealing from (their draws are the script's own). */
const txDealPiles: { [id: string]: boolean } = {};
/** The dice the script rolled last (left on the table until the next roll, so people can read them). */
let txDiceIds: string[] = [];
/** Script dice waiting to settle: die id -> resolve(face). */
const txDieWait: { [id: string]: (value: number | null) => void } = {};

function txRun(fn: () => Promise<void>): Promise<void> {
  txChain = txChain.then(fn).catch((error) => {
    world.log("SWTCG error: " + txDescribe(error));
  });
  return txChain;
}

function txDescribe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

// --------------------------------------------------------------------------------- geometry --

function txZone(seat: number, key: string): SeatZoneInfo | null {
  const z = txZones[seat];
  return z ? z[TX_ZONE_NAMES[key] || key] || null : null;
}

function txLocal(zone: SeatZoneInfo, lx: number, lz: number, lift: number): Vec3 {
  const r = (zone.rotationY * Math.PI) / 180;
  return [
    zone.position[0] + lx * Math.cos(r) + lz * Math.sin(r),
    zone.position[1] + 0.004 + lift,
    zone.position[2] - lx * Math.sin(r) + lz * Math.cos(r)
  ];
}

function txSeatYaw(seat: number): number {
  const hand = txZone(seat, "hand");
  return hand ? hand.rotationY + 180 : seat === 0 ? 180 : 0;
}

async function txLoadZones(): Promise<boolean> {
  txZones = {};
  for (let i = 0; i < 2; i += 1) {
    let list = await world.getSeatZones(txSeats[i]);
    // An unclaimed seat (a bot's, an empty one, a preview) has no live zones: use the authored ones.
    if (!list.some((z) => z.name === TX_ZONE_NAMES["a0"])) list = TX_FALLBACK_ZONES[txSeats[i]] || list;
    const byName: { [name: string]: SeatZoneInfo } = {};
    for (const z of list) byName[z.name] = z;
    txZones[i] = byName;
  }
  return !!txZone(0, "a0") && !!txZone(1, "a0");
}

// --------------------------------------------------------------------------------- layout --

interface TxPlace {
  pos: Vec3;
  yaw: number;
  faceDown: boolean;
  /** Deal it into the seat's real hand instead of placing it. */
  hand?: boolean;
}

/**
 * Hand cards go into the seats' REAL hands (private, in the hand drawer, draggable) whenever both
 * seats are held — by people or lobby bots, whose seats are claimed. In practice the bot is the
 * script itself and its seat is unclaimed, so there is no live hand zone to deal into.
 */
function txHandMode(): boolean {
  return !txPractice;
}

/** Which of `seat`'s zones (hand, build, res, a0..a2) holds the world point, or "". */
function txZoneKeyAt(seat: number, pos: Vec3): string {
  for (const key of ["a0", "a1", "a2", "build", "res", "hand"]) {
    const z = txZone(seat, key);
    if (!z) continue;
    const r = (z.rotationY * Math.PI) / 180;
    const dx = pos[0] - z.position[0];
    const dz = pos[2] - z.position[2];
    const lx = dx * Math.cos(r) - dz * Math.sin(r);
    const lz = dx * Math.sin(r) + dz * Math.cos(r);
    if (Math.abs(lx) <= z.size[0] / 2 + 0.05 && Math.abs(lz) <= z.size[2] / 2 + 0.05) return key;
  }
  return "";
}

/** True when a person sits in the game's seat `seat` (practice: red is the person). */
function txHumanSeat(seat: number): boolean {
  if (txPractice) return seat === 0;
  const id = txSeats[seat];
  return world.getPlayers().some((p) => p.seat === id && !p.isBot);
}

/** Where each visible instance belongs on the table. */
function txLayout(s: State): { [inst: number]: TxPlace } {
  const out: { [inst: number]: TxPlace } = {};
  for (let seat = 0; seat < 2; seat += 1) {
    const yaw = txSeatYaw(seat);
    // Hand.
    const hz = txZone(seat, "hand");
    const hand = handOf(s, seat).sort((a, b) => a - b);
    if (hz && txHandMode()) {
      for (const id of hand) out[id] = { pos: hz.position, yaw, faceDown: false, hand: true };
    } else if (hz) {
      txRow(hz, hand, yaw, false, out);
      // Practice: the bot's seat is unclaimed, so its hand zone hides nothing; deal it face down.
      if (!txHumanSeat(seat)) for (const id of hand) if (out[id]) out[id].faceDown = true;
    }
    // Build zone (partially built face down, retreated units and completed Equipment face up).
    const bz = txZone(seat, "build");
    const build: number[] = [];
    for (let i = 0; i < s.cards.length; i += 1) {
      const c = s.cards[i];
      if (c && c.z === "build" && c.c === seat) build.push(i);
    }
    if (bz) {
      txRow(bz, build, yaw, false, out);
      for (const id of build) if (card(s, id).fd) out[id].faceDown = true;
    }
    // Arenas.
    for (let ar = 0; ar < 3; ar += 1) {
      const zone = txZone(seat, "a" + ar);
      if (!zone) continue;
      const here: number[] = [];
      let location = -1;
      for (let i = 0; i < s.cards.length; i += 1) {
        const c = s.cards[i];
        if (!c || c.z !== zoneOfArena(ar) || c.c !== seat) continue;
        if ((s.defs[c.d].ty & T_LOCATION) !== 0) location = i;
        else here.push(i);
      }
      here.sort((a, b) => a - b);
      here.forEach((id, k) => {
        const col = k % 4;
        const row = Math.floor(k / 4) % 3;
        const lift = Math.floor(k / 12) * 0.01;
        const pos = txLocal(zone, (col - 1.5) * 0.225, (1 - row) * 0.33, lift + 0.006);
        out[id] = { pos, yaw: yaw + (card(s, id).tp ? 90 : 0), faceDown: false };
        // Cards under this one: stacked versions, Equipment, Pilots.
        attached(s, id, -1).forEach((u, j) => {
          const under = txLocal(zone, (col - 1.5) * 0.225 + 0.02 * (j + 1), (1 - row) * 0.33 - 0.045 * (j + 1), lift + 0.003 - 0.0005 * j);
          out[u] = { pos: under, yaw: yaw + (card(s, id).tp ? 90 : 0), faceDown: false };
        });
      });
      if (location >= 0) out[location] = { pos: txLocal(zone, 0, -0.62, 0.002), yaw: yaw + 90, faceDown: false };
    }
    // Resource and Event.
    const rz = txZone(seat, "res");
    for (const id of zoneIds(s, seat, "res")) if (rz) out[id] = { pos: txLocal(rz, 0, 0, 0.004), yaw: yaw + (card(s, id).tp ? 90 : 0), faceDown: false };
    const ez = txZone(seat, "sup");
    for (const id of zoneIds(s, seat, "evt")) if (ez) out[id] = { pos: txLocal(ez, 0, 0, 0.004), yaw, faceDown: false };
    // Discard: the most recent card only.
    const dz = txZone(seat, "disc");
    const order = txDiscardOrder[seat].filter((id) => s.cards[id] && card(s, id).z === "disc" && card(s, id).o === seat);
    if (dz && order.length > 0) out[order[order.length - 1]] = { pos: txLocal(dz, 0, 0, 0.004), yaw, faceDown: false };
  }
  return out;
}

function txRow(zone: SeatZoneInfo, ids: number[], yaw: number, tapped: boolean, out: { [inst: number]: TxPlace }): void {
  const n = ids.length;
  if (n === 0) return;
  const width = zone.size[0] - TX_CARD_W;
  const step = n > 1 ? Math.min(TX_CARD_W + 0.03, width / (n - 1)) : 0;
  const start = -((n - 1) * step) / 2;
  ids.forEach((id, k) => {
    out[id] = { pos: txLocal(zone, start + k * step, 0, 0.0008 * k + 0.004), yaw: yaw + (tapped ? 90 : 0), faceDown: false };
  });
}

// --------------------------------------------------------------------------------- render --

function txCardId(s: State, inst: number): string {
  return txCatalogIds[card(s, inst).d] || "swtcg-unknown";
}

function txPlaceKey(cardId: string, place: TxPlace): string {
  return cardId + (place.hand ? "#hand" : place.faceDown ? "#fd" : "#up");
}

/**
 * Where the script spawns before moving a card into place: the open middle of the table. A seat's
 * build zone is `owner-seat-only`, and a spawn INTO it is refused for every actor but the seat's
 * own player — so a card is spawned here and then moved.
 */
function txSpawnPoint(y: number): Vec3 {
  return [0, y + 0.06, 0];
}

/** A locked table card (a `card`, not a pile: nobody can draw it out from under the script). */
async function txSpawnCard(s: State, inst: number, place: TxPlace): Promise<TxEnt | null> {
  if (place.hand) return txDealToHand(s, inst, card(s, inst).o, place);
  const cardId = txCardId(s, inst);
  const handle = (await world.spawnObject({
    kind: "card",
    presetId: "card-standard",
    name: place.faceDown ? "Face-down card" : s.defs[card(s, inst).d].n,
    position: txSpawnPoint(place.pos[1]),
    rotation: [0, place.yaw, 0],
    metadata: { cardId, cardSource: { source: txSource, deckId: null, partitionId: null }, standardPresetId: "card-standard" },
    tags: ["swtcg-card"]
  })) as CardObject | null;
  if (!handle) return null;
  handle.setPosition(place.pos);
  handle.setRotation([0, place.yaw, 0]);
  if (place.faceDown ? handle.faceUp !== false : handle.faceUp === false) handle.flip();
  handle.lock();
  return { id: handle.id, key: txPlaceKey(cardId, place), pos: place.pos, yaw: place.yaw, dm: 0, bc: 0, tip: "", hand: false };
}

/** Deal one card into `seat`'s real hand: a one-card pile, dealt with the platform's own deal. */
async function txDealToHand(s: State, inst: number, seat: number, place: TxPlace): Promise<TxEnt | null> {
  const cardId = txCardId(s, inst);
  const pile = (await world.spawnObject({
    kind: "deck",
    presetId: "deck-standard",
    name: "Dealing",
    position: txSpawnPoint(place.pos[1]),
    rotation: [0, place.yaw, 0],
    metadata: { cards: [{ cardId, faceDown: true }], cardSource: { source: txSource, deckId: null, partitionId: null } },
    tags: ["swtcg-deal"]
  })) as DeckObject | null;
  if (!pile) return null;
  txDealPiles[pile.id] = true;
  let dealt: CardObject | null = null;
  try {
    dealt = await pile.dealTo({ seat: txSeats[seat] });
  } catch (error) {
    dealt = null;
  }
  const left = await world.getObjectById(pile.id);
  if (left) left.destroy();
  delete txDealPiles[pile.id];
  if (!dealt) return null;
  return { id: dealt.id, key: txPlaceKey(cardId, place), pos: place.pos, yaw: place.yaw, dm: 0, bc: 0, tip: "", hand: true };
}

function txSame(a: Vec3, b: Vec3): boolean {
  return Math.abs(a[0] - b[0]) < 0.002 && Math.abs(a[1] - b[1]) < 0.002 && Math.abs(a[2] - b[2]) < 0.002;
}

/** Make the table match the kernel state. */
async function txRender(): Promise<void> {
  const s = txState;
  if (!s) return;
  for (let i = 0; i < s.cards.length; i += 1) {
    const c = s.cards[i];
    if (c && c.z === "disc" && txDiscardOrder[c.o].indexOf(i) < 0) txDiscardOrder[c.o].push(i);
  }
  const want = txLayout(s);
  // Remove entities that are no longer shown, or whose identity/face changed.
  for (const key of Object.keys(txEnts)) {
    const inst = Number(key);
    const ent = txEnts[inst];
    const place = want[inst];
    const wantKey = place ? txPlaceKey(txCardId(s, inst), place) : "";
    if (!place || wantKey !== ent.key) {
      const h = await world.getObjectById(ent.id);
      if (h) h.destroy();
      delete txEnts[inst];
    }
  }
  const spawns: Promise<void>[] = [];
  for (const key of Object.keys(want)) {
    const inst = Number(key);
    const place = want[inst];
    const ent = txEnts[inst];
    if (!ent) {
      spawns.push(txSpawnCard(s, inst, place).then((e) => {
        if (e) txEnts[inst] = e;
      }));
      continue;
    }
    // A hand card is laid out by the platform's hand zone, and its owner may rearrange it.
    if (ent.hand) continue;
    if (!txSame(ent.pos, place.pos) || Math.abs(ent.yaw - place.yaw) > 0.5) {
      const h = await world.getObjectById(ent.id);
      if (h) {
        h.unlock();
        h.setPosition(place.pos);
        h.setRotation([0, place.yaw, 0]);
        h.lock();
      }
      ent.pos = place.pos;
      ent.yaw = place.yaw;
    }
  }
  await Promise.all(spawns);
  // Counters: damage on units, build counters on partially built cards.
  for (const key of Object.keys(txEnts)) {
    const inst = Number(key);
    const ent = txEnts[inst];
    const c = s.cards[inst];
    if (!c) continue;
    if (ent.dm !== c.dm || ent.bc !== c.bc) {
      const h = (await world.getObjectById(ent.id)) as (ObjectHandle & TxCounterApi) | null;
      if (h && typeof h.setCounter === "function") {
        h.setCounter("damage-counter", c.dm);
        h.setCounter("build-counter", c.bc);
      }
      ent.dm = c.dm;
      ent.bc = c.bc;
    }
  }
  // Hover tooltips on PUBLIC cards only (a tooltip replicates to everyone, so never on a hand card or
  // a face-down card): name, live stats, damage and the rules text.
  for (const key of Object.keys(txEnts)) {
    const inst = Number(key);
    const ent = txEnts[inst];
    const c = s.cards[inst];
    if (!c) continue;
    const isPublic = !c.fd && c.z !== "hand";
    const tip = isPublic ? txTooltip(s, inst) : "";
    if (tip === ent.tip) continue;
    const h = await world.getObjectById(ent.id);
    if (h) {
      if (tip) h.setTooltip({ enabled: true, title: defOf(s, inst).n, description: tip, showDetails: false });
      else h.setTooltip({ enabled: false });
    }
    ent.tip = tip;
  }
  await txRenderPiles(s);
  txRenderHud(s);
  await txRenderPawns(s);
  txRenderTurn(s);
}

function txTooltip(s: State, inst: number): string {
  const c = card(s, inst);
  const d = defOf(s, inst);
  const lines: string[] = [];
  if (isUnitDef(d)) {
    const st = inArena(c) ? stats(s, inst) : { sp: d.sp, pw: d.pw, hp: d.hp, kw: d.kw };
    lines.push("**Speed " + st.sp + " · Power " + st.pw + " · Health " + st.hp + "**" + (c.dm > 0 ? "  [color=#ff6b6b]" + c.dm + " damage[/color]" : ""));
    const kws = Object.keys(st.kw).filter((k) => k.indexOf(":") < 0 && k !== "Wounded" && k !== "ExtraPilot").map((k) => (st.kw[k] > 1 || ["Armor", "Stealth", "Overkill", "Double Strike", "Inspiration", "Precision", "Ferocity", "Cunning", "Double Damage", "Fortitude", "Intimidation"].indexOf(k) < 0 ? k + " " + st.kw[k] : k));
    if (kws.length > 0) lines.push("*" + kws.join(", ") + "*");
  } else lines.push("*Build cost " + d.cost + "*");
  if (c.tp) lines.push("Tapped");
  if (d.txt) lines.push(d.txt.replace(/\s*\|\s*/g, "\n- ").replace(/^/, "- ").slice(0, 600));
  if (d.unk > 0) lines.push("[color=#9aa4b2](" + d.unk + " ability not automated)[/color]");
  return lines.join("\n");
}

async function txRenderPiles(s: State): Promise<void> {
  for (let seat = 0; seat < 2; seat += 1) {
    const n = s.P[seat].deck.length;
    const pile = txPiles[seat];
    if (pile && pile.n === n) continue;
    if (pile) {
      const h = await world.getObjectById(pile.id);
      if (h) h.destroy();
      delete txPiles[seat];
    }
    const zone = txZone(seat, "deck");
    if (!zone || n === 0) continue;
    // Face-down entries still need a real catalogue id for the pile's art to build (a made-up id
    // renders blank). One id from this seat's own deck, repeated: the pile shows only backs, and
    // face-down ids are redacted for every other peer anyway.
    const backId = txCardId(s, s.P[seat].deck[0]);
    const cards: { cardId: string; faceDown: boolean }[] = [];
    for (let k = 0; k < n; k += 1) cards.push({ cardId: backId, faceDown: true });
    const handle = await world.spawnObject({
      kind: "deck",
      presetId: "deck-standard",
      name: "Deck",
      position: txLocal(zone, 0, 0, 0.004),
      rotation: [0, txSeatYaw(seat), 0],
      metadata: { cards, cardSource: { source: txSource, deckId: null, partitionId: null } },
      tags: ["swtcg-pile"]
    });
    if (handle) {
      handle.lock();
      txPiles[seat] = { id: handle.id, n };
    }
  }
}

function txPhaseText(s: State): string {
  if (s.win >= 0) return s.win === 2 ? "Draw" : txSeatName(s.win) + " wins";
  const who = txSeatName(s.who);
  const arena = ARENA_NAMES[s.arena] || "";
  switch (s.ph) {
    case "event": return who + ": choose an Event";
    case "resource": return who + ": pull a Resource?";
    case "mulligan": return who + ": mulligan";
    case "setup": return who + ": setup (" + s.P[s.who].bp + " build left)";
    case "build": return "Turn " + s.turn + " - " + who + "'s build step";
    case "retreat": return "Turn " + s.turn + " - " + who + "'s retreat step";
    case "pop": return "Turn " + s.turn + " - " + arena + " battle - " + who + " may play an effect";
    case "choose-attacker": return arena + " battle - " + who + ": choose an attacker";
    case "attack-target": return arena + " battle - " + who + ": " + nameOf(s, s.sel) + " attacks";
    case "double": return arena + " battle - " + who + ": Double Strike";
    case "target": return who + ": choose a target";
    case "roll": return who + ": roll " + txDiceLeft(s) + (s.rollWhy === "build" ? " die for build points" : " dice - " + (s.atk ? nameOf(s, s.atk.a) + " attacks " + nameOf(s, s.atk.d) : "attack"));
    default: return "Turn " + s.turn;
  }
}

function txSideName(seat: number): string {
  const side = txSetup ? txSetup.decks[seat].side : "";
  return side === "D" ? "Dark Side" : side === "L" ? "Light Side" : side === "Y" ? "Yuuzhan Vong" : side ? "Neutral" : "";
}

function txSeatName(seat: number): string {
  const id = txSeats[seat];
  const p = world.getPlayers().find((x) => x.seat === id);
  const side = txSideName(seat);
  return (p && p.displayName ? p.displayName : id) + (side ? " (" + side + ")" : "");
}

/**
 * What the seat to act should do now (the private line under the HUD status). It reaches the HUD
 * as a bound VALUE, which is always drawn as plain text: no **bold** here.
 */
function txHowTo(s: State, seat: number): string[] {
  const btn = txPrimaryMove(s, seat);
  const press = btn ? "Or press \"" + txDescribe2(s, btn) + "\"." : "";
  const drag = txHandMode() ? "Drag a card from your hand" : "Right-click a card in your hand";
  switch (s.ph) {
    case "event":
      return ["Right-click an Event in your hand to play it.", press];
    case "resource":
      return ["Right-click a card to pull it into your hand.", press];
    case "mulligan":
      return ["Press \"Keep this hand\", or right-click cards to set them aside (mulligan)."];
    case "setup":
      return [
        "Setup: " + s.P[seat].bp + " build points to spend.",
        txHandMode()
          ? drag + " onto an arena to set it up there (pays its cost), or onto your build zone to start it face down."
          : drag + " to set it up in an arena or as a Resource.",
        "Right-click a card for every option. " + press
      ];
    case "build":
      return [
        "Your build step: " + s.P[seat].bp + " build points.",
        txHandMode() ? drag + " onto an arena to deploy it, or onto your build zone to build it." : drag + " to deploy or build it.",
        "Right-click cards for abilities and moves. " + press
      ];
    case "retreat":
      return ["Right-click units to retreat them.", press];
    case "pop":
      return ["You may play a Battle card or an ability: right-click it.", press];
    case "choose-attacker":
      return ["Right-click one of your units: \"Attack with...\"", press];
    case "attack-target":
    case "double":
      return ["Right-click the unit to attack.", press];
    case "target":
      return ["Right-click the card to target, or pick it below.", press];
    case "roll":
      return ["Press \"Roll " + txDiceLeft(s) + "d6\", or roll " + txDiceLeft(s) + "d6 in your dice tray."];
    default:
      return ["Right-click a card for your options.", press];
  }
}

/** Write one HUD state value, skipping it when it has not changed. */
function txHudSet(key: string, value: UiValue, seat?: string, priv?: boolean): void {
  const k = (seat || "") + "|" + key + "|" + (priv ? "p" : "");
  if (k in txHudCache && txHudCache[k] === value) return;
  txHudCache[k] = value;
  if (seat) ui.set(key, value, seat, priv ? { private: true } : undefined);
  else ui.set(key, value);
}

/** The HUD every game shows: status, the players' numbers, the battle log and the game controls. */
function txDrawHud(): void {
  ui.show({
    id: "swtcg-status",
    kind: "status",
    placement: { region: "upper" },
    theme: { icon: "rocket_launch", accent: "yellow" },
    title: "{phase|Star Wars TCG}",
    // The seat to act reads its own private line; in practice (nobody seated) it is shared.
    body: "{seat.howTo|}{howTo|}",
    // Practice only: the player panel draws a row per OCCUPIED seat, so nobody seated sees none.
    note: "{summary|}"
  });
  ui.show({
    id: "swtcg-players",
    kind: "player-panel",
    counters: [
      { label: "Force", value: "{seat.force|0}", icon: "bolt", tone: "accent" },
      { label: "Build", value: "{seat.bp|0}", icon: "toll" },
      { label: "Hand", value: "{seat.hand|0}", icon: "playing_cards" },
      { label: "Deck", value: "{seat.deck|0}", icon: "inventory_2" },
      { label: "Arenas", value: "{seat.arenas|0}", max: "3", icon: "flag", tone: "success" }
    ],
    note: "{seat.side|}"
  });
  ui.show({ id: "log", kind: "log", title: "Battle log", placement: { region: "end" }, maxLines: 120 });
  ui.show({
    id: "swtcg-game",
    kind: "actions",
    placement: { region: "lower-end" },
    ...(txPractice ? { allow: ["spectators"] as "spectators"[] } : { audience: { scope: "players" } as UiAudience }),
    actions: [{ id: "new-game", label: "New game", icon: "restart_alt", confirm: "Start a new Star Wars TCG game? This one is lost." }]
  });
}

function txRenderHud(s: State): void {
  txHudSet("phase", txPhaseText(s));
  txHudSet(
    "summary",
    txPractice
      ? [0, 1]
          .map((seat) => {
            const p = s.P[seat];
            return (seat === 0 ? "You" : "Bot") + ": Force " + p.force + ", Build " + p.bp + ", Hand " + handOf(s, seat).length + ", Deck " + p.deck.length + ", Arenas " + arenasControlled(s, seat);
          })
          .join("  |  ")
      : null
  );
  for (let seat = 0; seat < 2; seat += 1) {
    const id = txSeats[seat];
    const p = s.P[seat];
    txHudSet("force", p.force, id);
    txHudSet("bp", p.bp, id);
    txHudSet("hand", handOf(s, seat).length, id);
    txHudSet("deck", p.deck.length, id);
    txHudSet("arenas", arenasControlled(s, seat), id);
    txHudSet("side", txSideName(seat) || null, id);
    const acting = s.win < 0 && s.who === seat && !txIsBotSeat(seat);
    // One paragraph: a bound value's line breaks are not drawn.
    const how = acting ? txHowTo(s, seat).filter((l) => !!l).join(" ") : null;
    // Seated: private to the seat. Practice: the one person may sit anywhere, so shared.
    txHudSet("howTo", txPractice ? null : how, id, true);
    if (seat === 0) txHudSet("howTo", txPractice ? how : null);
  }
}

/** A short warning for one seat (everyone in practice): "that card can't be played there". */
function txHint(seat: number, text: string): void {
  ui.toast(text, { tone: "warning", icon: "info", ...(txPractice ? {} : { to: { scope: "seats", seats: [txSeats[seat]] } as UiAudience }) });
}

/** The game cannot start: say why in the status line and a notice. */
function txCannotStart(text: string): void {
  txHudSet("phase", "Star Wars TCG cannot start");
  txHudSet("howTo", text);
  ui.toast(text, { tone: "danger", icon: "error", seconds: 10 });
}

async function txRenderPawns(s: State): Promise<void> {
  for (let seat = 0; seat < 2; seat += 1) {
    const pawn = txPawns[seat];
    if (!pawn || pawn.track.length === 0) continue;
    const i = Math.max(0, Math.min(pawn.track.length - 1, s.P[seat].force));
    const h = await world.getObjectById(pawn.id);
    if (h && !txSame(h.position, [pawn.track[i][0], h.position[1], pawn.track[i][2]])) {
      h.unlock();
      h.setPosition([pawn.track[i][0], pawn.track[i][1] + 0.07, pawn.track[i][2]]);
      h.lock();
    }
  }
}

function txRenderTurn(s: State): void {
  if (s.win >= 0) {
    world.setTurn(null);
    return;
  }
  world.setTurn(txSeats[s.who]);
  const scores: Record<string, number> = {};
  for (let seat = 0; seat < 2; seat += 1) scores[txSeats[seat]] = arenasControlled(s, seat);
  world.setScores(scores);
}

// --------------------------------------------------------------------------------- moves --

function txDescribe2(s: State, m: Move): string {
  const seat = s.who;
  const id = cellInst(s, m.r);
  const nm = id >= 0 ? nameOf(s, id) : "";
  const a = m.a;
  if (m.r < 0) {
    if (s.ph === "roll") return "Die shows " + (a - G_X0);
    if (a === G_PASS) {
      if (s.ph === "build") return "End build step";
      if (s.ph === "retreat") return "Done retreating";
      if (s.ph === "setup") return "Finish setup (waste " + s.P[seat].bp + ")";
      if (s.ph === "mulligan") return "Keep this hand";
      if (s.ph === "event") return "Play no Event";
      if (s.ph === "resource") return "Don't pull a Resource";
      return "Pass";
    }
    if (a === G_MULL_DISCARD) return "Mulligan: discard set-aside cards";
    if (a === G_MULL_RETURN) return "Mulligan: shuffle them back";
    if (a === G_SKIP_ATTACK) return "Don't attack (tap)";
    if (a === G_NO) return s.ph === "double" ? "No second attack" : "Cancel";
    return "Choose";
  }
  const d = defOf(s, id);
  const c = card(s, id);
  switch (s.ph) {
    case "event": return "Play the Event " + nm;
    case "resource": return "Pull " + nm + " into your hand";
    case "mulligan": return "Set " + nm + " aside";
    case "setup":
      if (a === A_BUILD) return "Finish: build " + nm + " face down (" + s.P[seat].bp + " counters)";
      if (a === A_DEPLOY_BZ) return "Set up " + nm + " as your Resource (" + d.cost + ")";
      return "Set up " + nm + " in " + ARENA_NAMES[a - A_DEPLOY0] + " (" + d.cost + ")";
    case "build":
      if (s.sel >= 0) return "Equip " + nameOf(s, s.sel) + " to " + nm;
      if (a === A_BUILD) return "Build " + nm + " (" + (c.z === "build" ? c.bc + 1 : 1) + "/" + d.cost + ")";
      if (a >= A_DEPLOY0 && a < A_DEPLOY0 + 3) return (isUnitDef(d) ? "Deploy " : "Complete ") + nm + " to " + ARENA_NAMES[a - A_DEPLOY0] + " (" + completeCost(s, id) + ")";
      if (a === A_DEPLOY_BZ) return (isUnitDef(d) ? "Deploy " + nm + " to the build zone" : "Complete " + nm) + " (" + completeCost(s, id) + ")";
      if (a >= A_MOVE0 && a < A_MOVE0 + 3) return "Move " + nm + " to " + ARENA_NAMES[a - A_MOVE0];
      if (a === A_EQUIP) return "Equip " + nm + "...";
      break;
    case "retreat":
      return "Retreat " + nm;
    case "pop":
      if (a >= A_DEPLOY0 && a < A_DEPLOY0 + 3) return "Hidden Cost: complete " + nm + " (" + completeCost(s, id) + " Force)";
      break;
    case "choose-attacker":
      return "Attack with " + nm;
    case "attack-target":
    case "double":
      if (a === A_ATTACK) return nameOf(s, s.sel) + " attacks " + nm;
      break;
    case "target":
      return "Target " + nm;
    default:
      break;
  }
  if (a >= A_ACT0 && a < A_ACT0 + 4) {
    const ent = actsOf(s, id)[a - A_ACT0];
    return (c.z === "hand" ? "Play " : "Use ") + nm + ": " + (ent ? ent.ab.src : "ability");
  }
  return nm;
}

/** The move the seat's action button plays when pressed: its pass / done / skip move. */
function txPrimaryMove(s: State, seat: number): Move | null {
  if (s.win >= 0 || s.who !== seat) return null;
  const moves = legalMoves(s);
  for (const pref of [G_PASS, G_SKIP_ATTACK, G_NO]) {
    const m = moves.find((x) => x.r < 0 && x.a === pref);
    if (m) return m;
  }
  return null;
}

function txIsBotSeat(seat: number): boolean {
  if (txPractice) return seat === 1;
  const id = txSeats[seat];
  return world.getPlayers().some((p) => p.seat === id && p.isBot);
}

function txClearMenus(): void {
  for (const id of txMenuIds) world.removeObjectMenuItem(id);
  txMenuIds = [];
  txMenuMoves = [];
  if (txHudRoll || Object.keys(txHudMoves).length > 0) ui.hide("swtcg-moves");
  txHudMoves = {};
  txHudRoll = "";
}

/**
 * The decider's moves that have no card on the table to right-click (Pass, End build step,
 * Mulligan, Roll, a choice the kernel offers): an action strip, or a list when there are many.
 */
function txShowMoves(seat: number, buttons: UiButton[]): void {
  const audience: Partial<UiWidget> = txPractice
    ? { allow: ["spectators"] }
    : { audience: { scope: "seats", seats: [txSeats[seat]] } };
  if (buttons.length <= 12) {
    ui.show({ id: "swtcg-moves", kind: "actions", placement: { region: "lower" }, title: "Your move", ...audience, actions: buttons });
    return;
  }
  ui.show({
    id: "swtcg-moves",
    kind: "choice",
    placement: { region: "sheet" },
    title: "Choose",
    ...audience,
    choices: { options: buttons.slice(0, 200) }
  });
}

/** Offer the current decider's legal moves: menu items on their cards, the rest on the HUD. */
function txRebuildMenus(): void {
  txClearMenus();
  const s = txState;
  if (!s || s.win >= 0) return;
  const seat = s.who;
  if (txIsBotSeat(seat)) return;
  txMenuVer += 1;
  txMenuSeat = seat;
  if (s.ph === "roll") {
    // Never offer the faces themselves: the dice decide them.
    txHudRoll = "roll-" + txMenuVer;
    txShowMoves(seat, [{ id: txHudRoll, label: "Roll " + txDiceLeft(s) + "d6", icon: "casino", tone: "accent", emphasis: "strong" }]);
    return;
  }
  const moves = legalMoves(s);
  const map = cellMapOf(s, seat);
  const primary = txPrimaryMove(s, seat);
  const loose: UiButton[] = [];
  // The seat's pass / done / skip move goes last, drawn strong.
  const tail: UiButton[] = [];
  moves.forEach((m, i) => {
    const inst = m.r >= 0 ? map.instOf[m.r] : -1;
    const ent = inst >= 0 ? txEnts[inst] : undefined;
    if (!ent) {
      const hudId = "m" + txMenuVer + "-" + i;
      txHudMoves[hudId] = m;
      const label = txDescribe2(s, m).slice(0, 120);
      if (primary && primary.r === m.r && primary.a === m.a) tail.push({ id: hudId, label, icon: "skip_next", emphasis: "strong" });
      else loose.push({ id: hudId, label });
      return;
    }
    const anchor = ent.id;
    const id = "swm-" + txMenuVer + "-" + i;
    const item: ObjectMenuItemRegistration & { seats?: string[] } = {
      id,
      label: txDescribe2(s, m).slice(0, 80),
      match: { objectIds: [anchor] },
      order: i
    };
    if (!txPractice) item.seats = [txSeats[seat]];
    world.addObjectMenuItem(item);
    txMenuIds.push(id);
    txMenuMoves[i] = m;
  });
  const buttons = loose.concat(tail);
  if (buttons.length > 0) txShowMoves(seat, buttons);
}

function txSeatOfActor(actor: string): number {
  if (txPractice) return 0;
  const p = world.getPlayers().find((x) => x.peerId === actor);
  if (!p || !p.seat) return -1;
  return txSeats.indexOf(p.seat);
}

/**
 * The kernel starts every move with an empty log, so it is read once per state it produced — not
 * when the table is drawn (a redraw of the same state used to repeat it; a skipped one lost it).
 */
function txTakeLog(s: State): void {
  // One log entry per move (the HUD log keeps 120), so a bot's busy turn stays within the budget.
  if (s.log.length > 0) ui.log(s.log.join(" · ").slice(0, 480));
}

/** Apply one move (from a person or a bot), record it, and redraw. */
async function txPlay(m: Move): Promise<void> {
  if (!txState) return;
  txState = kernel.apply(txState, m);
  txMoves.push(m);
  txTakeLog(txState);
  if (txRecording) {
    try {
      match.move(m);
    } catch (error) {
      txRecording = false;
      world.log("SWTCG: the match stopped recording (" + txDescribe(error) + ").");
    }
  }
}

async function txAfterMoves(): Promise<void> {
  if (!txState) return;
  await txRender();
  if (txState.win >= 0 && !txOver) await txGameOver();
  txRebuildMenus();
}

// --------------------------------------------------------------------------------- bots --

/** A copy of the state with what `seat` cannot see shuffled: the search never peeks. */
function txDeterminize(s: State, seat: number): State {
  const t = JSON.parse(JSON.stringify(s)) as State;
  const opp = other(seat);
  const hidden: number[] = [];
  for (let i = 0; i < t.cards.length; i += 1) {
    const c = t.cards[i];
    if (!c || c.o !== opp) continue;
    if (c.z === "hand" || c.z === "deck" || (c.z === "build" && c.fd)) hidden.push(i);
  }
  const defsOf = hidden.map((i) => (t.cards[i] as Card).d);
  for (let i = defsOf.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const x = defsOf[i];
    defsOf[i] = defsOf[j];
    defsOf[j] = x;
  }
  hidden.forEach((i, k) => {
    (t.cards[i] as Card).d = defsOf[k];
  });
  for (const p of t.P) {
    for (let i = p.deck.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      const x = p.deck[i];
      p.deck[i] = p.deck[j];
      p.deck[j] = x;
    }
  }
  t.rng = (Math.random() * 4294967296) >>> 0 || 1;
  t.log = [];
  // The search plays its rollouts on the seeded RNG: a "roll" phase would let it pick the faces.
  t.pd = false;
  t.dq = [];
  return t;
}

type TxChooser = (s: State, difficultyId: string | null, signal: BotAbortSignal | undefined, modelId: string | null) => Promise<Move>;

const TX_SEARCH_SIMS: { [d: string]: number } = { easy: 24, medium: 64, normal: 64, hard: 160 };

async function txSearch(s: State, sims: number, modelId: string | null, signal: BotAbortSignal | undefined): Promise<Move> {
  const legal = legalMoves(s);
  if (legal.length === 1) return legal[0];
  const det = txDeterminize(s, s.who);
  try {
    const result = await ai.mcts({ kernel, modelId, state: det, simulations: sims, signal });
    const pick = legal.find((m) => m.r === result.move.r && m.a === result.move.a);
    return pick || greedyMove(s);
  } catch (error) {
    return greedyMove(s);
  }
}

const TX_CHOOSERS: { [botId: string]: TxChooser } = {
  greedy: async (s) => greedyMove(s),
  search: async (s, difficultyId, signal) => txSearch(s, TX_SEARCH_SIMS[difficultyId || "medium"] || 64, null, signal),
  "swtcg-ai": async (s, difficultyId, signal, modelId) => txSearch(s, TX_SEARCH_SIMS[difficultyId || "medium"] || 64, modelId, signal)
};

function txBotOf(seat: number): { chooser: TxChooser; difficulty: string | null; model: string | null } {
  if (txPractice) return { chooser: TX_CHOOSERS["search"], difficulty: "medium", model: null };
  const id = txSeats[seat];
  const p = world.getPlayers().find((x) => x.seat === id && x.isBot);
  const chooser = p && p.botId && TX_CHOOSERS[p.botId] ? TX_CHOOSERS[p.botId] : TX_CHOOSERS["greedy"];
  return { chooser, difficulty: p ? p.difficultyId : null, model: p && p.botId === "swtcg-ai" ? "swtcg-net" : null };
}

/** Play every decision that belongs to a bot, until a person must decide or the game ends. */
async function txDriveBots(signal?: BotAbortSignal): Promise<void> {
  for (let guard = 0; guard < 3000; guard += 1) {
    const s = txState;
    if (!s || s.win >= 0) return;
    if (!txIsBotSeat(s.who)) return;
    if (signal && signal.aborted) return;
    if (s.ph === "roll") {
      await txRollFor(s.who);
      await txRender();
      await world.wait(TX_BOT_PACE);
      continue;
    }
    const bot = txBotOf(s.who);
    const before = s.turn;
    const m = await bot.chooser(s, bot.difficulty, signal, bot.model);
    await txPlay(m);
    const moved = m.r >= 0 && m.a !== A_TARGET;
    if (moved || (txState && txState.turn !== before)) {
      await txRender();
      await world.wait(TX_BOT_PACE);
    }
  }
}

// --------------------------------------------------------------------------------- setup --

/** The decks the lobby put on the table, by seat (nearest hand zone). */
async function txFindLobbyDecks(): Promise<{ [seat: number]: { main: string[]; supply: string[]; name: string; handles: ObjectHandle[] } }> {
  const out: { [seat: number]: { main: string[]; supply: string[]; name: string; handles: ObjectHandle[] } } = {};
  const decks = await world.getAllObjects({ kind: "deck" });
  for (const d of decks) {
    if (d.tags.indexOf("swtcg-card") >= 0 || d.tags.indexOf("swtcg-pile") >= 0 || d.tags.indexOf("swtcg-deal") >= 0) continue;
    const meta = d.metadata as { cardSource?: { source?: { kind?: string; id?: string; version?: number }; partitionId?: string | null } };
    if (!meta.cardSource || !meta.cardSource.source) continue;
    const src = meta.cardSource.source;
    if (typeof src.id === "string" && typeof src.kind === "string") txSource = { kind: src.kind, id: src.id, version: typeof src.version === "number" ? src.version : 1 };
    let best = -1;
    let bestD = Infinity;
    for (let seat = 0; seat < 2; seat += 1) {
      const hz = txZone(seat, "hand");
      if (!hz) continue;
      const dx = d.position[0] - hz.position[0];
      const dz = d.position[2] - hz.position[2];
      const dist = dx * dx + dz * dz;
      if (dist < bestD) {
        bestD = dist;
        best = seat;
      }
    }
    if (best < 0) continue;
    const entry = out[best] || { main: [], supply: [], name: d.name || "Deck", handles: [] };
    const ids = (d as DeckObject).cards.map((c) => c.cardId);
    if (meta.cardSource.partitionId === "supply") entry.supply = entry.supply.concat(ids);
    else entry.main = entry.main.concat(ids);
    entry.handles.push(d);
    out[best] = entry;
  }
  return out;
}

function txRowToRaw(row: TxCardRow, cardId: string): RawCard {
  const str = (k: string) => (row[k] === null || row[k] === undefined ? "" : String(row[k]));
  return {
    name: str("name") || cardId,
    type: str("type") || str("card_type"),
    subtype: str("subtype"),
    side: str("side") || "N",
    cost: str("cost"),
    speed: str("speed"),
    power: str("power"),
    health: str("health"),
    text: str("rules_text") || str("text"),
    set: str("set"),
    cid: cardId
  };
}

/** Build the match setup: both decks as catalog indices + counts, and a fresh seed. */
async function txBuildSetup(): Promise<MatchSetup | null> {
  const resolve = (world as World & TxWorldExtra).resolveCards;
  if (typeof resolve !== "function") {
    txCannotStart("This table cannot read card data yet (world.resolveCards is missing).");
    return null;
  }
  const lobby = await txFindLobbyDecks();
  const lists: { name: string; side: string; main: string[]; supply: string[] }[] = [];
  for (let seat = 0; seat < 2; seat += 1) {
    const got = lobby[seat];
    if (got && got.main.length >= 30) {
      lists.push({ name: got.name, side: "", main: got.main, supply: got.supply });
      for (const h of got.handles) h.destroy();
    } else lists.push({ name: "", side: "", main: [], supply: [] });
  }
  // Seats without a deck (bots, practice) play a starter deck of the other side.
  const ids = Array.from(new Set(lists.flatMap((l) => l.main.concat(l.supply))));
  const rows = ids.length > 0 ? await resolve.call(world, ids) : [];
  const rowById: { [id: string]: TxCardRow | null } = {};
  ids.forEach((id, i) => {
    rowById[id] = rows[i] || null;
  });
  const sideOf = (main: string[]) => {
    const count: { [k: string]: number } = {};
    for (const id of main) {
      const r = rowById[id];
      const sd = r ? String(r["side"] || "N") : "N";
      count[sd] = (count[sd] || 0) + 1;
    }
    return count["D"] ? "D" : count["Y"] ? "Y" : count["L"] ? "L" : "N";
  };
  for (const l of lists) if (l.main.length > 0) l.side = sideOf(l.main);
  for (let seat = 0; seat < 2; seat += 1) {
    const l = lists[seat];
    if (l.main.length > 0) continue;
    const otherSide = lists[1 - seat].side;
    const pool = STARTER_DECKS.filter((d) => (otherSide === "D" ? d.side !== "D" : otherSide === "L" ? d.side !== "L" : true));
    const pick = pool[Math.floor(Math.random() * pool.length)];
    l.name = pick.name;
    l.side = pick.side;
    l.main = [];
    for (const [cid, n] of pick.cards) for (let k = 0; k < n; k += 1) l.main.push(cid);
  }
  const more = Array.from(new Set(lists.flatMap((l) => l.main.concat(l.supply)))).filter((id) => !(id in rowById));
  if (more.length > 0) {
    const extra = await resolve.call(world, more);
    more.forEach((id, i) => {
      rowById[id] = extra[i] || null;
    });
  }
  const catalog: RawCard[] = [];
  txCatalogIds = [];
  const index: { [id: string]: number } = {};
  const counts = (list: string[]) => {
    const tally: { [id: string]: number } = {};
    for (const id of list) {
      if (!rowById[id]) continue;
      if (!(id in index)) {
        index[id] = catalog.length;
        catalog.push(txRowToRaw(rowById[id] as TxCardRow, id));
        txCatalogIds.push(id);
      }
      tally[id] = (tally[id] || 0) + 1;
    }
    return Object.keys(tally).map((id) => [index[id], tally[id]] as [number, number]);
  };
  const decks: DeckSetup[] = lists.map((l) => ({ name: l.name, side: l.side, main: counts(l.main), supply: counts(l.supply) }));
  if (decks.some((d) => d.main.length === 0)) {
    txCannotStart("A deck could not be read from the card catalogue.");
    return null;
  }
  // dice: "table" - every build and attack roll waits for real dice (the kernel takes the faces as moves).
  return { v: 1, seed: (Math.random() * 4294967296) >>> 0 || 7, catalog, decks, dice: "table" };
}

/** The game's two seats: the match's participants, the seated players, or practice (red vs a bot). */
function txChooseSeats(): void {
  const seated = world.getPlayers().filter((p) => p.seat !== null && TX_SEAT_IDS.indexOf(p.seat) >= 0);
  if (seated.length >= 2) {
    txSeats = TX_SEAT_IDS.slice();
    txPractice = false;
    return;
  }
  txSeats = TX_SEAT_IDS.slice();
  txPractice = true;
}

async function txFindPawns(): Promise<void> {
  txPawns = {};
  const tokens = await world.getAllObjects({ kind: "token" });
  const snaps = await world.getSnapPoints();
  for (let seat = 0; seat < 2; seat += 1) {
    const hz = txZone(seat, "hand");
    if (!hz) continue;
    const sideZ = hz.position[2];
    const mine = snaps.filter((p) => Math.sign(p.position[2]) === Math.sign(sideZ));
    const pawn = tokens.filter((t) => Math.sign(t.position[2]) === Math.sign(sideZ) && Math.abs(t.position[2]) > 1.8).sort((a, b) => Math.abs(b.position[2]) - Math.abs(a.position[2]))[0];
    if (!pawn || mine.length === 0) continue;
    // The track starts at the snap point nearest the pawn's authored spot.
    const start = mine.slice().sort((a, b) => Math.abs(a.position[0] - pawn.position[0]) - Math.abs(b.position[0] - pawn.position[0]))[0];
    const track = mine.slice().sort((a, b) => Math.abs(a.position[0] - start.position[0]) - Math.abs(b.position[0] - start.position[0])).map((p) => p.position);
    txPawns[seat] = { id: pawn.id, track };
  }
}

async function txClearTable(): Promise<void> {
  for (const key of Object.keys(txEnts)) {
    const h = await world.getObjectById(txEnts[Number(key)].id);
    if (h) h.destroy();
    delete txEnts[Number(key)];
  }
  for (const key of Object.keys(txPiles)) {
    const h = await world.getObjectById(txPiles[Number(key)].id);
    if (h) h.destroy();
    delete txPiles[Number(key)];
  }
  for (const stray of await world.getAllObjects({ tag: "swtcg-card" })) stray.destroy();
  for (const stray of await world.getAllObjects({ tag: "swtcg-pile" })) stray.destroy();
  for (const stray of await world.getAllObjects({ tag: "swtcg-deal" })) stray.destroy();
  for (const stray of await world.getAllObjects({ tag: "swtcg-die" })) stray.destroy();
  txDiceIds = [];
  // Cards dealt into hands (a dealt card does not keep the pile's tags), and any card someone
  // pulled out of a pile by hand: in the Scripted variant every loose catalogue card is the
  // script's.
  for (const stray of await world.getAllObjects({ kind: "card" })) {
    const meta = stray.metadata as { cardSource?: { source?: { id?: string } } };
    if (meta.cardSource && meta.cardSource.source && meta.cardSource.source.id === txSource.id) stray.destroy();
  }
  // Earlier versions drew the status and log as table text and spawned a red Pass button per seat;
  // the HUD does both now.
  for (const stray of await world.getAllObjects({ tag: "swtcg-button" })) stray.destroy();
  for (const seat of ["0", "1"]) for (const kind of ["status", "log", "button"]) world.removeTextLabel("swtcg-" + kind + "-" + seat);
  txDiscardOrder[0] = [];
  txDiscardOrder[1] = [];
  ui.hide("swtcg-result");
}

async function txStartMatch(setup: MatchSetup): Promise<void> {
  txRecording = false;
  if (typeof match === "undefined") return;
  const running = match.current();
  if (running && (running.status === "live" || running.status === "opening")) {
    try {
      await match.abort("new game");
    } catch (error) {
      world.log("SWTCG: could not stop the previous match (" + txDescribe(error) + ").");
    }
  }
  if (txPractice) return;
  // The platform caps a match setup (64 KiB); a bigger one plays on, unrecorded.
  if (JSON.stringify(setup).length > 63000) {
    ui.log("These two decks are too large to record as a match; the game is played unranked.", { tone: "warning" });
    return;
  }
  try {
    const info = await (match.start as unknown as TxMatchStart)({ kernel, setup, seats: txSeats });
    txRecording = !!info && info.status === "live";
  } catch (error) {
    world.log("SWTCG: this game is not recorded as a match (" + txDescribe(error) + ").");
  }
}

/**
 * The lobby places each player's chosen deck on the table AFTER the scene script has started, so a
 * game that began at once dealt everyone a starter deck. Wait (a few seconds at most) until every
 * seated person has a deck on the table.
 */
async function txWaitForLobbyDecks(): Promise<void> {
  if (txPractice) return;
  const people: number[] = [];
  for (let seat = 0; seat < 2; seat += 1) if (txHumanSeat(seat)) people.push(seat);
  if (people.length === 0) return;
  for (let tries = 0; tries < 16; tries += 1) {
    const found = await txFindLobbyDecks();
    if (people.every((seat) => !!found[seat])) return;
    await world.wait(0.5);
  }
}

async function txNewGame(): Promise<void> {
  txOver = false;
  txStarting = true;
  txHumanMoved = false;
  try {
    await txNewGameInner();
  } finally {
    txStarting = false;
  }
}

async function txNewGameInner(): Promise<void> {
  txChooseSeats();
  txDrawHud();
  if (!(await txLoadZones())) {
    txCannotStart("The table has no seat zones for red and blue.");
    return;
  }
  txHudSet("phase", "Setting up a new game");
  await txWaitForLobbyDecks();
  await txFindPawns();
  await txClearTable();
  const setup = await txBuildSetup();
  if (!setup) return;
  txSetup = setup;
  txMoves = [];
  await txStartMatch(setup);
  txState = initialState(txSeats, setup);
  txTakeLog(txState);
  if (typeof world.setGameOver === "function") world.setGameOver(null);
  const versus = txSeatName(0) + " - " + setup.decks[0].name + " vs " + txSeatName(1) + " - " + setup.decks[1].name + (txPractice ? " (practice: you play red against a bot)" : "") + ".";
  ui.log("New game: " + versus, { tone: "info" });
  ui.toast(versus, { tone: "info", icon: "rocket_launch", seconds: 6 });
  await txAfterMoves();
  await txDriveBots();
  await txAfterMoves();
}

/** After a reload: rebuild the game from the running match (setup + recorded moves). */
async function txResume(): Promise<boolean> {
  if (typeof match === "undefined") return false;
  const info = match.current() as (MatchInfo & { setup?: unknown }) | null;
  if (!info || info.status !== "live" || !isMatchSetup(info.setup)) return false;
  try {
    const again = await (match.start as unknown as TxMatchStart)({ kernel });
    if (!again || again.id !== info.id) return false;
  } catch (error) {
    return false;
  }
  txSeats = info.participants.map((p) => p.seat);
  txPractice = false;
  if (!(await txLoadZones())) return false;
  txDrawHud();
  await txFindPawns();
  await txClearTable();
  txSetup = info.setup as MatchSetup;
  txCatalogIds = txSetup.catalog.map((r) => String((r as RawCard & { cid?: string }).cid || ""));
  let s = initialState(txSeats, txSetup);
  txMoves = [];
  for (const m of match.moves()) {
    s = kernel.apply(s, m as Move);
    txMoves.push(m as Move);
  }
  txState = s;
  txRecording = true;
  ui.log("The running match was picked back up (" + txMoves.length + " moves).", { tone: "info" });
  await txAfterMoves();
  return true;
}

async function txGameOver(): Promise<void> {
  const s = txState;
  if (!s || s.win < 0) return;
  txOver = true;
  txClearMenus();
  const result = s.win === 2 ? { draw: true as const } : { winner: txSeats[s.win] };
  const headline = s.win === 2 ? "The game is a draw." : txSeatName(s.win) + " controls " + arenasControlled(s, s.win) + " arenas and wins!";
  // Extra lines for the platform's game-over screen (shown after setGameOver).
  ui.show({
    id: "swtcg-result",
    kind: "result",
    headline,
    lines: [0, 1]
      .map((seat) => txSeatName(seat) + ": " + arenasControlled(s, seat) + " arenas" + (txSetup ? " - " + txSetup.decks[seat].name : ""))
      .concat(["Turn " + s.turn])
  });
  if (typeof world.setGameOver === "function") world.setGameOver(result);
  ui.log(headline, { tone: "success" });
  ui.toast(headline, { tone: "success", icon: "emoji_events", seconds: 8 });
  if (txRecording) {
    txRecording = false;
    const scores: Record<string, number> = {};
    scores[txSeats[0]] = arenasControlled(s, 0);
    scores[txSeats[1]] = arenasControlled(s, 1);
    match.end(result, { reason: s.win === 2 ? "turn limit" : "arenas", scores }).catch((error) => {
      world.log("SWTCG: the match result was not accepted (" + txDescribe(error) + ").");
    });
  }
}

// --------------------------------------------------------------------------------- events --

ui.onAction.add((event) => {
  if (event.widgetId === "swtcg-game") {
    if (event.actionId !== "new-game") return;
    const running = typeof match !== "undefined" ? match.current() : null;
    if (running && running.ranked && running.status === "live" && !txOver) {
      // Only the person who pressed hears it (the actor audience works before the first await).
      ui.toast("A ranked match is being played: finish it or resign before starting a new game.", { tone: "warning", to: { scope: "actor" } });
      return;
    }
    void txRun(async () => {
      await txNewGame();
    });
    return;
  }
  if (event.widgetId !== "swtcg-moves" || !event.actionId) return;
  const id = event.actionId;
  void txRun(async () => {
    const s = txState;
    if (!s || s.win >= 0 || s.who !== txMenuSeat) return;
    // The host checked the presser is in the widget's audience; still, only the deciding seat moves.
    if (!txPractice && event.seat !== txSeats[s.who]) return;
    if (txHudRoll && id === txHudRoll) {
      if (s.ph === "roll") await txHumanRoll(s.who);
      return;
    }
    const m = txHudMoves[id];
    if (!m) return;
    await txHumanPlay(m);
  });
});

globalEvents.onObjectMenuItem.add((object, itemId, context) => {
  if (itemId.indexOf("swm-") !== 0) return;
  void txRun(async () => {
    const parts = itemId.split("-");
    const ver = Number(parts[1]);
    const i = Number(parts[2]);
    const s = txState;
    if (!s || ver !== txMenuVer || s.who !== txMenuSeat) return;
    const seat = txSeatOfActor(context.actor);
    if (seat !== s.who) return;
    const m = txMenuMoves[i];
    if (!m) return;
    await txHumanPlay(m);
  });
});

/** A person's move, then every bot decision that follows it. */
async function txHumanPlay(m: Move): Promise<void> {
  txHumanMoved = true;
  await txPlay(m);
  await txAfterMoves();
  await txDriveBots();
  await txAfterMoves();
}

/** The move a hand card dropped on one of its owner's zones stands for, or null. */
function txDropMove(s: State, seat: number, inst: number, key: string): Move | null {
  if (s.win >= 0 || s.who !== seat || !key || key === "hand") return null;
  const map = cellMapOf(s, seat);
  const mine = legalMoves(s).filter((m) => m.r >= 0 && map.instOf[m.r] === inst);
  if (mine.length === 0) return null;
  const want: number[] = [];
  if (key === "a0" || key === "a1" || key === "a2") want.push(A_DEPLOY0 + Number(key.charAt(1)));
  if (key === "build") {
    want.push(A_BUILD);
    if (s.ph !== "setup") want.push(A_DEPLOY_BZ);
  }
  if (key === "res" && s.ph === "setup") want.push(A_DEPLOY_BZ);
  for (const a of want) {
    const m = mine.find((x) => x.a === a);
    if (m) return m;
  }
  // Something with one obvious play (an Event, a Battle card) can be dropped anywhere of yours.
  if (key !== "res" && mine.length === 1 && (s.ph === "event" || (mine[0].a >= A_ACT0 && mine[0].a < A_ACT0 + 4))) return mine[0];
  return null;
}

/** Playing from the hand by dragging: drop a card on an arena or your build zone. */
globalEvents.onObjectDropped.add((object, context) => {
  void txRun(async () => {
    const s = txState;
    if (!s) return;
    let inst = -1;
    for (const key of Object.keys(txEnts)) {
      const ent = txEnts[Number(key)];
      if (ent.hand && ent.id === object.id) inst = Number(key);
    }
    if (inst < 0 || !s.cards[inst]) return;
    const seat = card(s, inst).o;
    if (txSeatOfActor(context.actor) !== seat) return;
    const key = txZoneKeyAt(seat, object.position);
    if (key === "hand") return;
    const m = txDropMove(s, seat, inst, key);
    if (m) {
      await txHumanPlay(m);
      return;
    }
    // Not a play: the card goes back into the hand (dealt again on the redraw).
    const h = await world.getObjectById(object.id);
    if (h) h.destroy();
    delete txEnts[inst];
    txHint(seat, s.who !== seat ? "It is not your move yet." : key ? "That card can't be played there now." : "Drop it on an arena or your build zone.");
    await txAfterMoves();
  });
});

/** A card pulled off a script pile by hand would escape the rules: take it back. */
globalEvents.onCardDrawn.add((drawn) => {
  const meta = drawn.metadata as { sourceDeckId?: string };
  const from = meta.sourceDeckId || "";
  if (!from || txDealPiles[from]) return;
  let seat = -1;
  for (const key of Object.keys(txPiles)) if (txPiles[Number(key)].id === from) seat = Number(key);
  if (seat < 0) return;
  void txRun(async () => {
    const h = await world.getObjectById(drawn.id);
    if (h) h.destroy();
    const pile = await world.getObjectById(from);
    if (pile) pile.destroy();
    delete txPiles[seat];
    if (txState) await txRenderPiles(txState);
  });
});

/** A lobby deck that lands after the game started (and before anyone moved) restarts it with that deck. */
globalEvents.onObjectCreated.add((object) => {
  if (object.kind !== "deck" || txHumanMoved || txStarting || txRestartQueued || txPractice) return;
  if (object.tags.indexOf("swtcg-pile") >= 0 || object.tags.indexOf("swtcg-deal") >= 0 || object.tags.indexOf("swtcg-card") >= 0) return;
  const meta = object.metadata as { cardSource?: { deckId?: string | null } };
  if (!meta.cardSource || !meta.cardSource.deckId) return;
  txRestartQueued = true;
  void txRun(async () => {
    await world.wait(1.5);
    txRestartQueued = false;
    if (txHumanMoved) return;
    ui.log("A lobby deck arrived - starting the game with it.", { tone: "info" });
    await txNewGame();
  });
});

// --------------------------------------------------------------------------------- dice --

/** Faces the pending roll still needs. */
function txDiceLeft(s: State): number {
  return s.ph === "roll" ? Math.max(0, s.rollN - s.dq.length) : 0;
}

/** Feed real die faces into the kernel, one move per die. */
async function txFeedDice(values: number[]): Promise<void> {
  for (const v of values) {
    const s = txState;
    if (!s || s.ph !== "roll") break;
    if (!(v >= 1 && v <= 6)) continue;
    await txPlay({ r: -1, a: G_X0 + v });
  }
}

/** Roll one script die and wait (8 s at most) for its face; null when it could not be read. */
function txRollOne(h: ObjectHandle): Promise<number | null> {
  return new Promise<number | null>((resolve) => {
    txDieWait[h.id] = resolve;
    h.roll();
    void world.wait(8).then(() => {
      if (txDieWait[h.id] === resolve) {
        delete txDieWait[h.id];
        resolve(null);
      }
    });
  });
}

/**
 * Roll `n` real d6 on `seat`'s side of the table's centre and read the faces. A die that lands
 * cocked is rolled again (twice at most); one that still cannot be read gets a random face, and
 * the log says so.
 */
