        case "resource": return "Pull " + nm + " into your hand";
        case "mulligan": return "Set " + nm + " aside";
        case "setup":
            if (a === A_BUILD)
                return "Finish: build " + nm + " face down (" + s.P[seat].bp + " counters)";
            if (a === A_DEPLOY_BZ)
                return "Set up " + nm + " as your Resource (" + d.cost + ")";
            return "Set up " + nm + " in " + ARENA_NAMES[a - A_DEPLOY0] + " (" + d.cost + ")";
        case "build":
            if (s.sel >= 0)
                return "Equip " + nameOf(s, s.sel) + " to " + nm;
            if (a === A_BUILD)
                return "Build " + nm + " (" + (c.z === "build" ? c.bc + 1 : 1) + "/" + d.cost + ")";
            if (a >= A_DEPLOY0 && a < A_DEPLOY0 + 3)
