        case "retreat":
            return "Retreat " + nm;
        case "pop":
            if (a >= A_DEPLOY0 && a < A_DEPLOY0 + 3)
                return "Hidden Cost: complete " + nm + " (" + completeCost(s, id) + " Force)";
