/** A copy of the state with what `seat` cannot see shuffled: the search never peeks. */
function txDeterminize(s, seat) {
    const t = JSON.parse(JSON.stringify(s));
    const opp = other(seat);
    const hidden = [];
    for (let i = 0; i < t.cards.length; i += 1) {
        const c = t.cards[i];
        if (!c || c.o !== opp)
            continue;
        if (c.z === "hand" || c.z === "deck" || (c.z === "build" && c.fd))
            hidden.push(i);
    }
    const defsOf = hidden.map((i) => t.cards[i].d);
    for (let i = defsOf.length - 1; i > 0; i -= 1) {
        const j = Math.floor(Math.random() * (i + 1));
        const x = defsOf[i];
        defsOf[i] = defsOf[j];
        defsOf[j] = x;
    }
    hidden.forEach((i, k) => {
        t.cards[i].d = defsOf[k];
    });
    for (const p of t.P) {
        for (let i = p.deck.length - 1; i > 0; i -= 1) {
            const j = Math.floor(Math.random() * (i + 1));
            const x = p.deck[i];
            p.deck[i] = p.deck[j];
            p.deck[j] = x;
        }
    }
    t.rng = (Math.random() * 4294967296) >>> 0 || 1;
    t.log = [];
    // The search plays its rollouts on the seeded RNG: a "roll" phase would let it pick the faces.
    t.pd = false;
    t.dq = [];
    return t;
}
const TX_SEARCH_SIMS = { easy: 24, medium: 64, normal: 64, hard: 160 };
async function txSearch(s, sims, modelId, signal) {
    const legal = legalMoves(s);
    if (legal.length === 1)
        return legal[0];
    const det = txDeterminize(s, s.who);
    try {
        const result = await ai.mcts({ kernel, modelId, state: det, simulations: sims, signal });
        const pick = legal.find((m) => m.r === result.move.r && m.a === result.move.a);
        return pick || greedyMove(s);
    }
    catch (error) {
