    search: async (s, difficultyId, signal) => txSearch(s, TX_SEARCH_SIMS[difficultyId || "medium"] || 64, null, signal),
    "swtcg-ai": async (s, difficultyId, signal, modelId) => txSearch(s, TX_SEARCH_SIMS[difficultyId || "medium"] || 64, modelId, signal)
