/** The decks the lobby put on the table, by seat (nearest hand zone). */
async function txFindLobbyDecks() {
    const out = {};
    const decks = await world.getAllObjects({ kind: "deck" });
    for (const d of decks) {
        if (d.tags.indexOf("swtcg-card") >= 0 || d.tags.indexOf("swtcg-pile") >= 0 || d.tags.indexOf("swtcg-deal") >= 0)
            continue;
        const meta = d.metadata;
        if (!meta.cardSource || !meta.cardSource.source)
            continue;
        const src = meta.cardSource.source;
        if (typeof src.id === "string" && typeof src.kind === "string")
            txSource = { kind: src.kind, id: src.id, version: typeof src.version === "number" ? src.version : 1 };
        let best = -1;
        let bestD = Infinity;
        for (let seat = 0; seat < 2; seat += 1) {
            const hz = txZone(seat, "hand");
            if (!hz)
                continue;
            const dx = d.position[0] - hz.position[0];
            const dz = d.position[2] - hz.position[2];
            const dist = dx * dx + dz * dz;
            if (dist < bestD) {
                bestD = dist;
                best = seat;
            }
        }
        if (best < 0)
            continue;
        const entry = out[best] || { main: [], supply: [], name: d.name || "Deck", handles: [] };
        const ids = d.cards.map((c) => c.cardId);
        if (meta.cardSource.partitionId === "supply")
            entry.supply = entry.supply.concat(ids);
        else
            entry.main = entry.main.concat(ids);
        entry.handles.push(d);
        out[best] = entry;
    }
    return out;
}
function txRowToRaw(row, cardId) {
    const str = (k) => (row[k] === null || row[k] === undefined ? "" : String(row[k]));
    return {
        name: str("name") || cardId,
        type: str("type") || str("card_type"),
        subtype: str("subtype"),
        side: str("side") || "N",
        cost: str("cost"),
        speed: str("speed"),
        power: str("power"),
        health: str("health"),
        text: str("rules_text") || str("text"),
        set: str("set"),
        cid: cardId
    };
}
/** Build the match setup: both decks as catalog indices + counts, and a fresh seed. */
async function txBuildSetup() {
    const resolve = world.resolveCards;
    if (typeof resolve !== "function") {
        txCannotStart("This table cannot read card data yet (world.resolveCards is missing).");
        return null;
    }
    const lobby = await txFindLobbyDecks();
    const lists = [];
    for (let seat = 0; seat < 2; seat += 1) {
        const got = lobby[seat];
        if (got && got.main.length >= 30) {
            lists.push({ name: got.name, side: "", main: got.main, supply: got.supply });
            for (const h of got.handles)
                h.destroy();
        }
        else
            lists.push({ name: "", side: "", main: [], supply: [] });
    }
    // Seats without a deck (bots, practice) play a starter deck of the other side.
    const ids = Array.from(new Set(lists.flatMap((l) => l.main.concat(l.supply))));
    const rows = ids.length > 0 ? await resolve.call(world, ids) : [];
    const rowById = {};
    ids.forEach((id, i) => {
        rowById[id] = rows[i] || null;
    });
    const sideOf = (main) => {
        const count = {};
        for (const id of main) {
            const r = rowById[id];
            const sd = r ? String(r["side"] || "N") : "N";
            count[sd] = (count[sd] || 0) + 1;
        }
        return count["D"] ? "D" : count["Y"] ? "Y" : count["L"] ? "L" : "N";
    };
    for (const l of lists)
        if (l.main.length > 0)
            l.side = sideOf(l.main);
    for (let seat = 0; seat < 2; seat += 1) {
        const l = lists[seat];
        if (l.main.length > 0)
            continue;
        const otherSide = lists[1 - seat].side;
        const pool = STARTER_DECKS.filter((d) => (otherSide === "D" ? d.side !== "D" : otherSide === "L" ? d.side !== "L" : true));
        const pick = pool[Math.floor(Math.random() * pool.length)];
        l.name = pick.name;
        l.side = pick.side;
        l.main = [];
        for (const [cid, n] of pick.cards)
            for (let k = 0; k < n; k += 1)
                l.main.push(cid);
    }
    const more = Array.from(new Set(lists.flatMap((l) => l.main.concat(l.supply)))).filter((id) => !(id in rowById));
    if (more.length > 0) {
        const extra = await resolve.call(world, more);
        more.forEach((id, i) => {
            rowById[id] = extra[i] || null;
        });
    }
    const catalog = [];
    txCatalogIds = [];
    const index = {};
    const counts = (list) => {
        const tally = {};
        for (const id of list) {
            if (!rowById[id])
                continue;
            if (!(id in index)) {
                index[id] = catalog.length;
                catalog.push(txRowToRaw(rowById[id], id));
                txCatalogIds.push(id);
            }
            tally[id] = (tally[id] || 0) + 1;
        }
        return Object.keys(tally).map((id) => [index[id], tally[id]]);
    };
    const decks = lists.map((l) => ({ name: l.name, side: l.side, main: counts(l.main), supply: counts(l.supply) }));
    if (decks.some((d) => d.main.length === 0)) {
        txCannotStart("A deck could not be read from the card catalogue.");
        return null;
    }
    // dice: "table" - every build and attack roll waits for real dice (the kernel takes the faces as moves).
    return { v: 1, seed: (Math.random() * 4294967296) >>> 0 || 7, catalog, decks, dice: "table" };
}
/** The game's two seats: the match's participants, the seated players, or practice (red vs a bot). */
function txChooseSeats() {
    const seated = world.getPlayers().filter((p) => p.seat !== null && TX_SEAT_IDS.indexOf(p.seat) >= 0);
    if (seated.length >= 2) {
