        const sideZ = hz.position[2];
        const mine = snaps.filter((p) => Math.sign(p.position[2]) === Math.sign(sideZ));
        const pawn = tokens.filter((t) => Math.sign(t.position[2]) === Math.sign(sideZ) && Math.abs(t.position[2]) > 1.8).sort((a, b) => Math.abs(b.position[2]) - Math.abs(a.position[2]))[0];
        if (!pawn || mine.length === 0)
            continue;
        // The track starts at the snap point nearest the pawn's authored spot.
        const start = mine.slice().sort((a, b) => Math.abs(a.position[0] - pawn.position[0]) - Math.abs(b.position[0] - pawn.position[0]))[0];
        const track = mine.slice().sort((a, b) => Math.abs(a.position[0] - start.position[0]) - Math.abs(b.position[0] - start.position[0])).map((p) => p.position);
        txPawns[seat] = { id: pawn.id, track };
    }
}
async function txClearTable() {
    for (const key of Object.keys(txEnts)) {
        const h = await world.getObjectById(txEnts[Number(key)].id);
        if (h)
            h.destroy();
        delete txEnts[Number(key)];
    }
    for (const key of Object.keys(txPiles)) {
        const h = await world.getObjectById(txPiles[Number(key)].id);
        if (h)
            h.destroy();
        delete txPiles[Number(key)];
    }
    for (const stray of await world.getAllObjects({ tag: "swtcg-card" }))
        stray.destroy();
    for (const stray of await world.getAllObjects({ tag: "swtcg-pile" }))
        stray.destroy();
    for (const stray of await world.getAllObjects({ tag: "swtcg-deal" }))
        stray.destroy();
    for (const stray of await world.getAllObjects({ tag: "swtcg-die" }))
        stray.destroy();
    txDiceIds = [];
    // Cards dealt into hands (a dealt card does not keep the pile's tags), and any card someone
    // pulled out of a pile by hand: in the Scripted variant every loose catalogue card is the
    // script's.
    for (const stray of await world.getAllObjects({ kind: "card" })) {
        const meta = stray.metadata;
        if (meta.cardSource && meta.cardSource.source && meta.cardSource.source.id === txSource.id)
            stray.destroy();
    }
    // Earlier versions drew the status and log as table text and spawned a red Pass button per seat;
    // the HUD does both now.
    for (const stray of await world.getAllObjects({ tag: "swtcg-button" }))
        stray.destroy();
    for (const seat of ["0", "1"])
        for (const kind of ["status", "log", "button"])
            world.removeTextLabel("swtcg-" + kind + "-" + seat);
    txDiscardOrder[0] = [];
    txDiscardOrder[1] = [];
    ui.hide("swtcg-result");
}
async function txStartMatch(setup) {
    txRecording = false;
    if (typeof match === "undefined")
        return;
    const running = match.current();
    if (running && (running.status === "live" || running.status === "opening")) {
        try {
            await match.abort("new game");
        }
        catch (error) {
            world.log("SWTCG: could not stop the previous match (" + txDescribe(error) + ").");
        }
    }
    if (txPractice)
        return;
    // The platform caps a match setup (64 KiB); a bigger one plays on, unrecorded.
    if (JSON.stringify(setup).length > 63000) {
        ui.log("These two decks are too large to record as a match; the game is played unranked.", { tone: "warning" });
        return;
    }
    try {
        const info = await match.start({ kernel, setup, seats: txSeats });
        txRecording = !!info && info.status === "live";
    }
    catch (error) {
        world.log("SWTCG: this game is not recorded as a match (" + txDescribe(error) + ").");
    }
}
/**
 * The lobby places each player's chosen deck on the table AFTER the scene script has started, so a
 * game that began at once dealt everyone a starter deck. Wait (a few seconds at most) until every
 * seated person has a deck on the table.
 */
async function txWaitForLobbyDecks() {
    if (txPractice)
        return;
    const people = [];
    for (let seat = 0; seat < 2; seat += 1)
        if (txHumanSeat(seat))
            people.push(seat);
    if (people.length === 0)
        return;
    for (let tries = 0; tries < 16; tries += 1) {
        const found = await txFindLobbyDecks();
        if (people.every((seat) => !!found[seat]))
            return;
        await world.wait(0.5);
    }
}
async function txNewGame() {
    txOver = false;
    txStarting = true;
    txHumanMoved = false;
    try {
        await txNewGameInner();
    }
    finally {
        txStarting = false;
    }
}
async function txNewGameInner() {
    txChooseSeats();
    txDrawHud();
    if (!(await txLoadZones())) {
        txCannotStart("The table has no seat zones for red and blue.");
        return;
    }
    txHudSet("phase", "Setting up a new game");
    await txWaitForLobbyDecks();
    await txFindPawns();
    await txClearTable();
    const setup = await txBuildSetup();
    if (!setup)
        return;
    txSetup = setup;
    txMoves = [];
    await txStartMatch(setup);
    txState = initialState(txSeats, setup);
    txTakeLog(txState);
    if (typeof world.setGameOver === "function")
        world.setGameOver(null);
    const versus = txSeatName(0) + " - " + setup.decks[0].name + " vs " + txSeatName(1) + " - " + setup.decks[1].name + (txPractice ? " (practice: you play red against a bot)" : "") + ".";
    ui.log("New game: " + versus, { tone: "info" });
    ui.toast(versus, { tone: "info", icon: "rocket_launch", seconds: 6 });
    await txAfterMoves();
    await txDriveBots();
    await txAfterMoves();
}
/** After a reload: rebuild the game from the running match (setup + recorded moves). */
async function txResume() {
    if (typeof match === "undefined")
        return false;
    const info = match.current();
    if (!info || info.status !== "live" || !isMatchSetup(info.setup))
        return false;
    try {
        const again = await match.start({ kernel });
        if (!again || again.id !== info.id)
            return false;
    }
    catch (error) {
        return false;
    }
    txSeats = info.participants.map((p) => p.seat);
    txPractice = false;
    if (!(await txLoadZones()))
        return false;
    txDrawHud();
    await txFindPawns();
    await txClearTable();
    txSetup = info.setup;
    txCatalogIds = txSetup.catalog.map((r) => String(r.cid || ""));
    let s = initialState(txSeats, txSetup);
    txMoves = [];
    for (const m of match.moves()) {
        s = kernel.apply(s, m);
        txMoves.push(m);
    }
    txState = s;
    txRecording = true;
    ui.log("The running match was picked back up (" + txMoves.length + " moves).", { tone: "info" });
    await txAfterMoves();
    return true;
}
async function txGameOver() {
    const s = txState;
    if (!s || s.win < 0)
        return;
    txOver = true;
    txClearMenus();
    const result = s.win === 2 ? { draw: true } : { winner: txSeats[s.win] };
    const headline = s.win === 2 ? "The game is a draw." : txSeatName(s.win) + " controls " + arenasControlled(s, s.win) + " arenas and wins!";
    // Extra lines for the platform's game-over screen (shown after setGameOver).
    ui.show({
        id: "swtcg-result",
        kind: "result",
        headline,
        lines: [0, 1]
            .map((seat) => txSeatName(seat) + ": " + arenasControlled(s, seat) + " arenas" + (txSetup ? " - " + txSetup.decks[seat].name : ""))
            .concat(["Turn " + s.turn])
    });
    if (typeof world.setGameOver === "function")
        world.setGameOver(result);
    ui.log(headline, { tone: "success" });
    ui.toast(headline, { tone: "success", icon: "emoji_events", seconds: 8 });
    if (txRecording) {
        txRecording = false;
        const scores = {};
        scores[txSeats[0]] = arenasControlled(s, 0);
        scores[txSeats[1]] = arenasControlled(s, 1);
        match.end(result, { reason: s.win === 2 ? "turn limit" : "arenas", scores }).catch((error) => {
            world.log("SWTCG: the match result was not accepted (" + txDescribe(error) + ").");
        });
    }
}
