ui.onAction.add((event) => {
    if (event.widgetId === "swtcg-game") {
        if (event.actionId !== "new-game")
            return;
        const running = typeof match !== "undefined" ? match.current() : null;
        if (running && running.ranked && running.status === "live" && !txOver) {
            // Only the person who pressed hears it (the actor audience works before the first await).
            ui.toast("A ranked match is being played: finish it or resign before starting a new game.", { tone: "warning", to: { scope: "actor" } });
            return;
        }
        void txRun(async () => {
            await txNewGame();
        });
        return;
    }
    if (event.widgetId !== "swtcg-moves" || !event.actionId)
        return;
    const id = event.actionId;
    void txRun(async () => {
        const s = txState;
        if (!s || s.win >= 0 || s.who !== txMenuSeat)
            return;
        // The host checked the presser is in the widget's audience; still, only the deciding seat moves.
        if (!txPractice && event.seat !== txSeats[s.who])
            return;
        if (txHudRoll && id === txHudRoll) {
            if (s.ph === "roll")
                await txHumanRoll(s.who);
            return;
        }
        const m = txHudMoves[id];
        if (!m)
            return;
        await txHumanPlay(m);
    });
});
globalEvents.onObjectMenuItem.add((object, itemId, context) => {
