/** The move a hand card dropped on one of its owner's zones stands for, or null. */
function txDropMove(s, seat, inst, key) {
    if (s.win >= 0 || s.who !== seat || !key || key === "hand")
        return null;
    const map = cellMapOf(s, seat);
    const mine = legalMoves(s).filter((m) => m.r >= 0 && map.instOf[m.r] === inst);
    if (mine.length === 0)
        return null;
    const want = [];
    if (key === "a0" || key === "a1" || key === "a2")
        want.push(A_DEPLOY0 + Number(key.charAt(1)));
    if (key === "build") {
        want.push(A_BUILD);
        if (s.ph !== "setup")
            want.push(A_DEPLOY_BZ);
    }
    if (key === "res" && s.ph === "setup")
        want.push(A_DEPLOY_BZ);
    for (const a of want) {
        const m = mine.find((x) => x.a === a);
        if (m)
            return m;
    }
    // Something with one obvious play (an Event, a Battle card) can be dropped anywhere of yours.
    if (key !== "res" && mine.length === 1 && (s.ph === "event" || (mine[0].a >= A_ACT0 && mine[0].a < A_ACT0 + 4)))
        return mine[0];
    return null;
}
/** Playing from the hand by dragging: drop a card on an arena or your build zone. */
globalEvents.onObjectDropped.add((object, context) => {
    void txRun(async () => {
        const s = txState;
        if (!s)
            return;
        let inst = -1;
        for (const key of Object.keys(txEnts)) {
            const ent = txEnts[Number(key)];
            if (ent.hand && ent.id === object.id)
                inst = Number(key);
        }
        if (inst < 0 || !s.cards[inst])
            return;
        const seat = card(s, inst).o;
        if (txSeatOfActor(context.actor) !== seat)
            return;
        const key = txZoneKeyAt(seat, object.position);
        if (key === "hand")
            return;
        const m = txDropMove(s, seat, inst, key);
        if (m) {
            await txHumanPlay(m);
            return;
        }
        // Not a play: the card goes back into the hand (dealt again on the redraw).
        const h = await world.getObjectById(object.id);
        if (h)
            h.destroy();
        delete txEnts[inst];
        txHint(seat, s.who !== seat ? "It is not your move yet." : key ? "That card can't be played there now." : "Drop it on an arena or your build zone.");
        await txAfterMoves();
    });
});
/** A card pulled off a script pile by hand would escape the rules: take it back. */
globalEvents.onCardDrawn.add((drawn) => {
    const meta = drawn.metadata;
    const from = meta.sourceDeckId || "";
    if (!from || txDealPiles[from])
        return;
    let seat = -1;
    for (const key of Object.keys(txPiles))
        if (txPiles[Number(key)].id === from)
            seat = Number(key);
    if (seat < 0)
        return;
    void txRun(async () => {
        const h = await world.getObjectById(drawn.id);
        if (h)
            h.destroy();
        const pile = await world.getObjectById(from);
        if (pile)
            pile.destroy();
        delete txPiles[seat];
        if (txState)
            await txRenderPiles(txState);
    });
});
/** A lobby deck that lands after the game started (and before anyone moved) restarts it with that deck. */
globalEvents.onObjectCreated.add((object) => {
    if (object.kind !== "deck" || txHumanMoved || txStarting || txRestartQueued || txPractice)
        return;
    if (object.tags.indexOf("swtcg-pile") >= 0 || object.tags.indexOf("swtcg-deal") >= 0 || object.tags.indexOf("swtcg-card") >= 0)
        return;
    const meta = object.metadata;
    if (!meta.cardSource || !meta.cardSource.deckId)
        return;
    txRestartQueued = true;
    void txRun(async () => {
        await world.wait(1.5);
        txRestartQueued = false;
        if (txHumanMoved)
            return;
        ui.log("A lobby deck arrived - starting the game with it.", { tone: "info" });
        await txNewGame();
    });
});
// --------------------------------------------------------------------------------- dice --
/** Faces the pending roll still needs. */
function txDiceLeft(s) {
    return s.ph === "roll" ? Math.max(0, s.rollN - s.dq.length) : 0;
}
/** Feed real die faces into the kernel, one move per die. */
async function txFeedDice(values) {
    for (const v of values) {
        const s = txState;
        if (!s || s.ph !== "roll")
            break;
        if (!(v >= 1 && v <= 6))
            continue;
        await txPlay({ r: -1, a: G_X0 + v });
    }
}
/** Roll one script die and wait (8 s at most) for its face; null when it could not be read. */
function txRollOne(h) {
    return new Promise((resolve) => {
        txDieWait[h.id] = resolve;
        h.roll();
        void world.wait(8).then(() => {
            if (txDieWait[h.id] === resolve) {
                delete txDieWait[h.id];
                resolve(null);
            }
        });
    });
}
/**
 * Roll `n` real d6 on `seat`'s side of the table's centre and read the faces. A die that lands
 * cocked is rolled again (twice at most); one that still cannot be read gets a random face, and
 * the log says so.
 */
async function txRollDice(n, seat) {
    for (const id of txDiceIds) {
        const old = await world.getObjectById(id);
        if (old)
            old.destroy();
    }
    txDiceIds = [];
    const hz = txZone(seat, "hand");
    const y = hz ? hz.position[1] : 2.5;
    const side = hz && hz.position[2] < 0 ? -1 : 1;
    const handles = [];
    for (let i = 0; i < n; i += 1) {
        const col = i % 6;
        const row = Math.floor(i / 6);
        const h = await world.spawnObject({
            kind: "die",
            presetId: "die-d6",
            name: "d6",
            position: [(col - 2.5) * 0.14, y + 0.25, side * (0.12 + row * 0.14)],
            tags: ["swtcg-die"]
        });
        if (h)
            handles.push(h);
    }
    txDiceIds = handles.map((h) => h.id);
    const rolled = await Promise.all(handles.map(async (h) => {
        let face = await txRollOne(h);
        for (let again = 0; again < 2 && face === null; again += 1)
            face = await txRollOne(h);
        return face;
    }));
    const faces = [];
    for (const face of rolled) {
        if (face !== null && face >= 1 && face <= 6)
            faces.push(face);
        else {
            const stand = 1 + Math.floor(Math.random() * 6);
            ui.log("A die could not be read; it counts as " + stand + ".", { tone: "warning" });
            faces.push(stand);
        }
    }
    while (faces.length < n)
        faces.push(1 + Math.floor(Math.random() * 6));
    return faces;
}
/** Roll the pending dice for `seat` (a bot, or a person who pressed Roll). */
async function txRollFor(seat) {
    const s = txState;
    if (!s || s.ph !== "roll" || s.who !== seat)
        return;
    await txFeedDice(await txRollDice(txDiceLeft(s), seat));
}
/** A person rolls with the red button (or its Roll menu item), then the game carries on. */
async function txHumanRoll(seat) {
    txHumanMoved = true;
    await txRollFor(seat);
    await txAfterMoves();
    await txDriveBots();
    await txAfterMoves();
}
globalEvents.onDiceRolled.add((die, value) => {
    const wait = txDieWait[die.id];
    if (!wait)
        return;
    delete txDieWait[die.id];
    wait(value);
});
/** A roll in the roller's own dice tray answers a pending roll: its d6 faces are used, in order. */
globalEvents.onDiceRollResult.add((summary) => {
    const s = txState;
    if (!s || s.ph !== "roll" || txIsBotSeat(s.who))
        return;
    const roller = s.who;
    const mine = summary.seat === txSeats[roller] || (txPractice && roller === 0 && summary.seat === null);
    if (!mine)
        return;
    const faces = summary.dice.filter((d) => d.sides === 6 && typeof d.value === "number").map((d) => d.value);
    if (faces.length === 0)
        return;
    void txRun(async () => {
        const now = txState;
        if (!now || now.ph !== "roll" || now.who !== roller)
            return;
        const need = txDiceLeft(now);
        txHumanMoved = true;
        await txFeedDice(faces.slice(0, need));
        if (faces.length < need)
            txHint(roller, "Counted " + faces.length + " - roll " + (need - faces.length) + " more d6.");
        await txAfterMoves();
        await txDriveBots();
        await txAfterMoves();
    });
});
/** A bot's turn: play every decision that is its to make, then hand back to the table. */
function txBotTurn(ctx) {
